window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0148", [{"word":"globalization","ipa_uk":"/ˌɡləʊbəlaɪˈzeɪʃən/","ipa_us":"/ˌɡloʊbələˈzeɪʃən/","definition_zh":"全球化；世界各地经济、社会与文化联系日益紧密的整体过程","definition_en":"the process by which economies, societies and cultures around the world become closely connected","core_image":"同一只集装箱在几个大洲的吊机之间换手，货单上的地名不断更换，箱里的货物始终没变","scene":"港口的集装箱从一处码头换到另一处，同一件商品在不同大洲的货架上出现。Container ships carry the same goods across three continents in a single week, a visible sign of globalization.","sceneCN":"这里 globalization 指「各地经济、社会与文化联系不断加深的整体过程」（第 1 个义项：把世界连成一个接触面的总过程）；句意为集装箱船一周内把同一批货物运过三个大洲，这是全球化可见的标志。可辨识物件：集装箱、货轮、吊机、货架、货单。","pos":[{"tag":"n.","zh":"全球化（常作不可数，指整体过程）"},{"tag":"n.","zh":"具体形式的全球化（可数，学术用法，如不同的全球化）"}],"collocations":[{"phrase":"economic globalization","zh":"经济全球化"},{"phrase":"cultural globalization","zh":"文化全球化"},{"phrase":"the forces of globalization","zh":"全球化的推动力量"},{"phrase":"the pace of globalization","zh":"全球化的速度"},{"phrase":"anti-globalization","zh":"反全球化"},{"phrase":"globalization of trade","zh":"贸易全球化"}],"forms":[{"label":"不可数用法（整体过程）","form":"globalization"},{"label":"复数（学术用法，指不同形式）","form":"globalizations"},{"label":"形容词（全球的）","form":"global"},{"label":"动词（使全球化）","form":"globalize"},{"label":"副词（在全球范围）","form":"globally"}],"derivatives":[{"word":"globalize","pos":"v.","zh":"使全球化；使扩展到全球"},{"word":"globalized","pos":"adj.","zh":"已被全球化的"},{"word":"global","pos":"adj.","zh":"全球的；全世界的"},{"word":"globally","pos":"adv.","zh":"在全球范围内"},{"word":"globalism","pos":"n.","zh":"全球主义；世界一体化主张"},{"word":"anti-globalization","pos":"n./adj.","zh":"反全球化（的）"}],"senses":[{"no":"01","title":"One connected world","titleCN":"全球联成一个整体","definition":"the process by which economies, societies and cultures around the world become closely connected","definitionCN":"世界各地经济、社会与文化联系日益紧密的过程","example":"Container ships carry the same goods across three continents in a single week, a visible sign of globalization.","exampleCN":"集装箱船一周内把同一批货物运过三个大洲，这是全球化可见的标志。","why":"The core of the word is a ball: Latin globus is a round mass, and the process turns the whole planet into one round field of contact.","whyCN":"词的核心是一只球：拉丁 globus 指圆球，这个过程把整个星球变成一个圆形的接触面。"},{"no":"02","title":"Economic integration","titleCN":"经济一体化","definition":"the deepening of trade, investment and production links across national borders","definitionCN":"贸易、投资与生产越过国界而日益联结","example":"Globalization let the firm move parts across four borders before final assembly.","exampleCN":"全球化让这家公司在最终组装前把零件送过四道国界。","why":"Trade is the oldest thread: routes crossed continents long before the word was coined, and the modern term names their deepening.","whyCN":"贸易是最早的一条线：在这个词出现之前，商路就已跨越大洲，现代词只是为这种加深命名。"},{"no":"03","title":"One shared market","titleCN":"共同市场","definition":"the worldwide spread of brands, retail formats and consumer habits","definitionCN":"品牌、零售形态与消费习惯在全球铺开","example":"Globalization put the same coffee chain on streets from Seoul to Santiago.","exampleCN":"全球化把同一家咖啡连锁店开到从首尔到圣地亚哥的街头。","why":"When identical brands appear everywhere, the world behaves like a single market in daily experience.","whyCN":"当相同品牌到处出现，世界在日常体验里就像一个大市场。"},{"no":"04","title":"Cultural mixing","titleCN":"文化交融","definition":"the mixing of media, food, music and styles from different societies","definitionCN":"不同社会的媒介、饮食、音乐与风格相互混合","example":"Globalization brought Korean dramas, Nigerian music and Italian cooking into one living room.","exampleCN":"全球化把韩剧、尼日利亚音乐与意大利菜带进同一间客厅。","why":"Goods travel with stories and tastes, so the process mixes cultures as well as currencies.","whyCN":"货物随故事与口味一起流动，因此这个过程既混合货币，也混合文化。"},{"no":"05","title":"Instant worldwide contact","titleCN":"全球即时联通","definition":"the linking of communication and information systems across the planet","definitionCN":"通信与信息系统在全球范围内连成网络","example":"The globalization of the internet lets a class in Nairobi join a lecture in Toronto.","exampleCN":"互联网的全球化让内罗毕的一间教室接入多伦多的讲座。","why":"Cables and satellites collapsed distance into an instant, and that technical layer is the spine of the modern sense.","whyCN":"海底电缆与卫星把距离压缩成一瞬，这层技术是现代词义的骨架。"},{"no":"06","title":"Mobile labour","titleCN":"跨境流动的劳动力","definition":"the cross-border movement of workers, students and professionals","definitionCN":"工人、学生与专业人员越过国界流动","example":"Globalization of labour sends nurses and engineers along routes their parents never imagined.","exampleCN":"劳动力的全球化让护士与工程师走上父辈从未想象过的路线。","why":"Capital crosses borders faster than people, yet people still move, and the word covers that human traffic too.","whyCN":"资本比人更快越过国界，但人仍在移动，这个词也覆盖了这部分人口流动。"},{"no":"07","title":"Contested costs","titleCN":"被争论的代价","definition":"the uneven gains and losses that critics and supporters argue over","definitionCN":"批评者与支持者争论中的不均衡得失","example":"Critics argue that globalization rewards mobile capital while leaving local workers exposed.","exampleCN":"批评者认为全球化奖励可流动的资本，却让本地工人暴露在风险中。","why":"The same links that enrich some places expose others, so the word carries an argument inside it.","whyCN":"同样的联结让一些地方富裕，也让另一些地方暴露，因此这个词内部带着一场争论。"},{"no":"08","title":"Any process reaching planetary scale","titleCN":"泛指达到全球尺度","definition":"the extension of any phenomenon until it covers the whole world","definitionCN":"任何现象扩展到覆盖整个世界","example":"The report warns about the globalization of a single disease rather than celebrating it.","exampleCN":"这份报告警告某种疾病的全球化，而非为此庆贺。","why":"The suffix can attach to almost anything, so the term generalizes from trade to any spread that reaches the whole planet.","whyCN":"这个后缀几乎可以附着在任何名词上，因此该词从贸易泛化到任何达到全球尺度的扩散。"}],"etymology":{"intro":{"en":"Globalization joins global, from Latin globus 'a ball, a round mass' through Old French, with the verb suffix -ize and the noun suffix -ation. The term itself is a twentieth-century coinage. Dates are approximate.","cn":"globalization 由 global 加动词后缀与名词后缀构成；global 经古法语来自拉丁 globus「球、圆块」。这个词本身是二十世纪的合成词。年代均为约数。"},"items":[{"era":"LATIN GLOBUS","en":"Globus meant 'a ball, a round mass, a cluster'. Its deeper origin is not established, so no earlier form is given here.","cn":"globus 意为「球、圆块、聚集的一团」。其更深来源未得到证明，因此这里不给出更早的形态。"},{"era":"OLD FRENCH GLOBE","en":"Globe reached English through Old French in the fourteenth century, naming a sphere and later a map of the earth.","cn":"globe 在十四世纪经古法语进入英语，先指球体，后指地球图。"},{"era":"ENGLISH GLOBAL","en":"The adjective global appeared in the seventeenth century, first meaning 'shaped like a ball' and then 'covering the whole world'.","cn":"形容词 global 在十七世纪出现，先指「球形的」，后指「覆盖全世界的」。"},{"era":"LATIN AND GREEK SUFFIXES","en":"The verb suffix came through French from Greek -izein 'to make or do', and the noun suffix came from Latin -atio, which names an action or a process.","cn":"动词后缀经法语来自希腊语，表示「使……、做……」；名词后缀来自拉丁语，表示动作或过程。"},{"era":"MODERN COINAGE","en":"Globalization is a twentieth-century word; it spread widely in the 1980s and 1990s alongside debates about trade, media and migration.","cn":"globalization 是二十世纪的词；它在二十世纪八九十年代随贸易、媒体与移民的争论而广泛流行。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): no single first printed use is recorded, and the pre-Latin origin of globus is unsettled, so any older form offered for it is a reconstruction.","cn":"来源不确定（首见年代）：没有确切的最早印刷书证；globus 在拉丁语之前的来源亦无定论，凡为其给出的更早形态均属重构形式。"}]},"similar":{"note":{"en":"Group one holds words built on the same Latin ball; group two holds terms that name the same worldwide reach from other angles.","cn":"第一组是同出拉丁「球」词干的词；第二组是从其他角度指称同一种全球覆盖的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"global","ipa":"/ˈɡləʊbəl/","tag":"the adjective","definition":"The adjective meaning worldwide; globalization is the noun for the process behind it.","definitionCN":"意为「全球的」形容词；globalization 是这一过程的名词。"},{"word":"globally","ipa":"/ˈɡləʊbəli/","tag":"the adverb","definition":"Means across the world; it describes where something happens, not the process itself.","definitionCN":"意为「在全球范围」；描述事情发生的范围，而非过程本身。"},{"word":"globalism","ipa":"/ˈɡləʊbəlɪzəm/","tag":"the doctrine","definition":"Names a policy or ideology of worldwide integration, often used with a critical tone.","definitionCN":"指世界一体化的政策或意识形态，常带批评语气。"},{"word":"globalize","ipa":"/ˌɡləʊbəˈlaɪz/","tag":"the verb","definition":"The verb that names the action; globalization is its unfolding or result.","definitionCN":"指动作的动词；globalization 是这一动作的展开或结果。"}]},{"heading":"NEAR MEANING","entries":[{"word":"internationalization","ipa":"/ˌɪntəˌnæʃəˈnaɪzeɪʃən/","tag":"deliberate policy","definition":"The planned opening of institutions to other countries; globalization is the broader drift.","definitionCN":"指机构有计划地向他国开放；全球化是更宽泛的整体趋势。"},{"word":"liberalization","ipa":"/ˌlɪbərəlaɪˈzeɪʃən/","tag":"removing barriers","definition":"The removal of trade and market controls, one engine of globalization rather than the whole of it.","definitionCN":"指取消贸易与市场管制，是全球化的一台引擎，而非全部。"},{"word":"integration","ipa":"/ˌɪntɪˈɡreɪʃən/","tag":"joining parts","definition":"The joining of separate units into one system; it names the result rather than the historical process.","definitionCN":"指把分离的单位并入一个体系；说的是结果，而非历史过程。"},{"word":"westernization","ipa":"/ˌwestənaɪˈzeɪʃən/","tag":"one direction","definition":"The spread of Western models specifically; globalization is wider and in principle two-way.","definitionCN":"特指西方模式的扩散；全球化范围更广，原则上也是双向的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin globus 'ball' plus the noun suffix: the world handled as one round object.","cn":"拉丁 globus「球」加名词后缀：把世界当作一只圆球来处理。"},{"en":"The family runs globe, global, globally, globalize, globalization.","cn":"同族词包括 globe、global、globally、globalize、globalization。"},{"en":"Fixed phrases mark it: economic globalization, cultural globalization, the pace of globalization.","cn":"固定搭配标出它：经济全球化、文化全球化、全球化的速度。"},{"en":"The word rose with container shipping and the internet, so picture a crane and a cable.","cn":"这个词随集装箱航运与互联网兴起，因此可以想象吊机与电缆。"},{"en":"Globalization is the noun, globalize the verb, globalized the adjective for places already changed.","cn":"globalization 是名词，globalize 是动词，globalized 是形容已被改变之地的形容词。"}],"abstract":[{"en":"Picture one ball wound with many threads that all pull at once.","cn":"想象一只球被许多线缠住，每条线同时向外拉。"},{"en":"Picture a single shelf where goods from every coast sit side by side.","cn":"想象一排货架，各海岸来的货物并排摆放。"},{"en":"Picture a map folded until the far edges touch.","cn":"想象一张地图被折到最远的边缘彼此相接。"}]},"examples":[{"en":"Globalization lowered the price of the phone but closed the factory that once made its parts.","cn":"全球化压低了手机价格，却关掉了当年生产零件的工厂。"},{"en":"Studies of globalization often measure trade, migration and media flows together.","cn":"全球化研究常把贸易、移民与媒体流动放在一起测量。"},{"en":"The village felt globalization first as a new road, then as a new supermarket.","cn":"这个村子先是以一条新路感受到全球化，随后是一家新超市。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「全球」加「化」——把整个地球当成一只可以反复转动的球","word":"globalization"},"root":"global 来自拉丁 globus「球、圆块」，经古法语 globe 进入英语；globalization 由 global 加动词后缀与名词后缀构成，是二十世纪的现代合成词。globus 在拉丁语之前的来源不确定。","sensesIntro":{"en":"Eight senses follow one line: the world is treated as a single round ball, first linked by trade, then turned into a shared market, a mixed culture and an instant network, until the word becomes a debate about who gains and a general name for any planetary reach.","cn":"八个义项沿同一条线展开：世界被当作一只圆球，先由贸易连起，再变成共同市场、混合文化与即时网络，最后这个词既成为关于谁获益的争论，也成为任何全球尺度扩散的通称。"},"semanticMap":{"core":{"en":"CORE IMAGE: a single round ball wound with many threads that pull it in every direction.","cn":"核心意象：一只圆球被许多线缠住，每条线都朝不同方向拉动它。"},"chain":["ONE SPHERE","TRADE ROUTES","SHARED MARKET","MIXED CULTURES","INSTANT LINKS","PLANETARY SCALE"],"branches":[{"senses":"01","en":"ROUND WORLD: the base image is a single ball rather than separate places.","cn":"圆球世界：基础意象是一只球，而非彼此分离的地点。"},{"senses":"02 · 06","en":"MONEY AND PEOPLE: goods and workers cross the same borders at different speeds.","cn":"钱与人：货物与工人以不同速度越过同样的边界。"},{"senses":"03 · 04","en":"MARKET AND STORY: brands and stories travel together, so a shared market also mixes tastes.","cn":"市场与故事：品牌与故事同行，因此共同市场也混合口味。"},{"senses":"05","en":"CABLES: the instant layer that makes distance feel irrelevant.","cn":"电缆：让距离显得无关紧要的即时层。"},{"senses":"07 · 08","en":"THE ARGUMENT: the word is used both to praise reach and to name its costs.","cn":"争论：这个词既用来称赞覆盖范围，也用来指称代价。"}]},"affixes":{"intro":{"en":"Globalization can be read from a Latin noun for a ball, English adjective and verb suffixes, and the derived words built on the same stem.","cn":"globalization 可以按拉丁「球」名词、英语形容词与动词后缀以及同一词干上的派生词逐段读出。"},"latinIntro":{"en":"Latin globus supplies globe, global and the whole family; the verb suffix came through French from Greek, and the noun suffix came from Latin.","cn":"拉丁 globus 衍生 globe、global 与整个词族；动词后缀经法语来自希腊语，名词后缀来自拉丁语。"},"items":[{"word":"globus","structure":"globus, globi (Latin noun, second declension)","meaning":"ball, round mass","meaningCN":"球；圆块","example":"The root gives the round shape at the centre of the word.","exampleCN":"这个词根提供词中心的圆形意象。"},{"word":"globe","structure":"globus through Old French","meaning":"a sphere; a map of the earth","meaningCN":"球体；地球图","example":"A globe on the desk shows the whole planet at once.","exampleCN":"桌上的地球仪一次显示整个星球。"},{"word":"global","structure":"globe + -al (relating to)","meaning":"relating to the whole world","meaningCN":"与整个世界相关的","example":"A global market spans every continent.","exampleCN":"全球市场横跨每个大洲。"},{"word":"globalize","structure":"global + -ize (make, cause to be)","meaning":"to make worldwide","meaningCN":"使全球化","example":"Firms globalize their supply chains.","exampleCN":"企业把供应链全球化。"},{"word":"globalization","structure":"globalize + -ation (process or result)","meaning":"the process of becoming worldwide","meaningCN":"全球化的过程","example":"Globalization reshaped the port town.","exampleCN":"全球化重塑了这座港口城镇。"},{"word":"-ize","structure":"-ize (verb suffix, through French from Greek)","meaning":"to make, to cause to be","meaningCN":"使……；使成为","example":"The suffix turns a state into an action.","exampleCN":"这个后缀把状态变成动作。"},{"word":"-ation","structure":"-ation (noun suffix, from Latin -atio)","meaning":"action, process or result","meaningCN":"动作、过程或结果","example":"The suffix names the process rather than the actor.","exampleCN":"这个后缀指过程，而非行动者。"},{"word":"globalism","structure":"global + -ism (system or doctrine)","meaning":"a doctrine of worldwide integration","meaningCN":"世界一体化主张","example":"Globalism is the idea behind the process.","exampleCN":"全球主义是这一过程背后的观念。"},{"word":"globally","structure":"global + -ly (adverb suffix)","meaning":"across the world","meaningCN":"在全球范围","example":"The standard is applied globally.","exampleCN":"这一标准在全球适用。"},{"word":"anti-globalization","structure":"anti- (against) + globalization","meaning":"opposition to global integration","meaningCN":"反全球化","example":"The anti-globalization march drew thousands.","exampleCN":"反全球化游行吸引了数千人。"}],"derivatives":[{"word":"globalized","structure":"globalize + -ed (past participle)","meaning":"having been made worldwide","meaningCN":"已被全球化的"},{"word":"globalizing","structure":"globalize + -ing (present participle)","meaning":"in the process of becoming worldwide","meaningCN":"正在全球化的"},{"word":"globalist","structure":"global + -ist (person or advocate)","meaning":"a supporter of worldwide integration","meaningCN":"全球主义者；支持全球一体化的人"}],"latinEntries":[{"word":"globus","structure":"globus, globi (m., second declension)","meaning":"ball, round mass","meaningCN":"球；圆块"},{"word":"globosus","structure":"globosus, -a, -um (adjective)","meaning":"round, spherical","meaningCN":"圆的；球形的"}]}},{"word":"globalize","ipa_uk":"/ˌɡləʊbəˈlaɪz/","ipa_us":"/ˈɡloʊbəlaɪz/","definition_zh":"使全球化；使扩展到全球范围","definition_en":"to make something operate, spread or be organized across the whole world","core_image":"一张原本只画着本地街道的地图，被人不断添上新航线与新办公点，直到纸面铺满各洲","scene":"一家小厂把订单、客服与仓储陆续搬到几个大洲，管理层决定把业务彻底国际化。The board decided to globalize the business by opening offices on four continents.","sceneCN":"这里 globalize 指「使业务扩展到全球范围」（第 1 个义项：把某事物的活动范围放大到全球）；句意为董事会决定在四大洲开设办事处，把业务全球化。可辨识物件：世界地图、办公桌、航线、订单表、仓库。","pos":[{"tag":"vt.","zh":"使全球化；使扩展到全球"},{"tag":"vi.","zh":"变得全球化；走向国际"}],"collocations":[{"phrase":"globalize the economy","zh":"使经济全球化"},{"phrase":"globalize a business","zh":"使企业全球化"},{"phrase":"globalize markets","zh":"使市场全球化"},{"phrase":"globalize production","zh":"使生产全球化"},{"phrase":"globalize education","zh":"使教育全球化"}],"forms":[{"label":"三单（he/she/it）","form":"globalizes"},{"label":"过去式","form":"globalized"},{"label":"过去分词","form":"globalized"},{"label":"现在分词","form":"globalizing"},{"label":"名词（全球化）","form":"globalization"},{"label":"形容词（已被全球化的）","form":"globalized"}],"derivatives":[{"word":"globalization","pos":"n.","zh":"全球化"},{"word":"globalized","pos":"adj.","zh":"已被全球化的"},{"word":"globalizing","pos":"adj.","zh":"正在全球化的"},{"word":"globalism","pos":"n.","zh":"全球主义"},{"word":"globally","pos":"adv.","zh":"在全球范围"},{"word":"globalizer","pos":"n.","zh":"推动全球化的人或机构"}],"senses":[{"no":"01","title":"Extend something worldwide","titleCN":"使扩展到全球","definition":"to make something operate or reach across the whole world","definitionCN":"使某事物的运作或影响覆盖整个世界","example":"The foundation hopes to globalize its clean-water programme within a decade.","exampleCN":"该基金会希望在十年内把净水项目推广到全球。","why":"Global plus the verb suffix meaning 'to make' gives the plain action: turn a local thing into a worldwide one.","whyCN":"global 加表示「使……」的动词后缀，得到最直接的动作：把本地的东西变成全球的东西。"},{"no":"02","title":"Make a business international","titleCN":"使企业国际化","definition":"to move a company's offices, production or sales into several countries","definitionCN":"把公司的办公、生产或销售扩展到多个国家","example":"The board decided to globalize the business by opening offices on four continents.","exampleCN":"董事会决定在四大洲开设办事处，把业务全球化。","why":"The commercial sense is the most visible: a firm globalizes when its desks and factories sit in different countries.","whyCN":"商业义最可见：当办公桌与工厂分布在不同国家，企业就完成了全球化。"},{"no":"03","title":"Open an economy to world markets","titleCN":"使经济向世界市场开放","definition":"to remove national limits so that an economy works on world terms","definitionCN":"取消本国限制，使经济按全球规则运行","example":"The reforms were designed to globalize the domestic market step by step.","exampleCN":"这些改革旨在逐步让国内市场全球化。","why":"Policy makers use the verb for the deliberate opening of markets, not for trade that happens by itself.","whyCN":"政策制定者用这个动词指有意开放市场，而非自然发生的贸易。"},{"no":"04","title":"Spread a culture or idea worldwide","titleCN":"使文化或观念传遍世界","definition":"to carry a practice, language or belief beyond its home region","definitionCN":"把某种做法、语言或信念带出原生地区","example":"Streaming platforms helped globalize a local style of dance music.","exampleCN":"流媒体平台帮助一种本地舞曲风格走向全球。","why":"Culture travels through media and migration, so the same verb covers the spread of habits as well as goods.","whyCN":"文化经媒体与移民传播，因此同一个动词既覆盖货物，也覆盖习惯的扩散。"},{"no":"05","title":"Link communication systems worldwide","titleCN":"使通信系统全球联通","definition":"to connect networks so that information reaches any region","definitionCN":"连接网络，使信息能到达任何地区","example":"Undersea cables globalize the internet in ways that satellites alone could not.","exampleCN":"海底电缆让互联网真正全球化，这是单靠卫星做不到的。","why":"The technical sense names the physical layer: wires, cables and protocols that make the world one network.","whyCN":"技术义指物理层：线路、电缆与协议把世界变成一个网络。"},{"no":"06","title":"Standardize on a world scale","titleCN":"使标准统一到全球","definition":"to make rules, measures or formats the same everywhere","definitionCN":"使规则、度量或格式在各处一致","example":"Accountants tried to globalize reporting standards across the industry.","exampleCN":"会计师们试图让整个行业的报告标准全球化。","why":"A standard that applies everywhere is another way of making one world out of many practices.","whyCN":"一套到处适用的标准，是另一种把多种做法变成一个世界的方式。"},{"no":"07","title":"Draw a place into global networks","titleCN":"把某地拉入全球网络","definition":"to pull a local place or person into worldwide flows, often in the passive","definitionCN":"把本地地点或人卷入全球流动，常用被动式","example":"The fishing village was globalized by tourism before it had a paved road.","exampleCN":"这个渔村在还没有柏油路之前就被旅游业全球化了。","why":"In the passive the verb often describes what happens to a place rather than what a place does.","whyCN":"在被动式里，这个动词常描述一个地方遭遇了什么，而非它主动做了什么。"},{"no":"08","title":"Frame a local matter as global","titleCN":"把本地问题放进全球框架","definition":"to treat an issue as part of a worldwide pattern rather than a local accident","definitionCN":"把某个问题看作全球格局的一部分，而非本地偶发事件","example":"The course teaches students to globalize their thinking about water scarcity.","exampleCN":"这门课教学生把水资源短缺的思考放到全球框架中。","why":"The abstract sense moves the verb from space to thought: to globalize a problem is to see its worldwide shape.","whyCN":"抽象义把动词从空间移到思维：把问题全球化，就是看出它的全球形态。"}],"etymology":{"intro":{"en":"Globalize is global plus the verb suffix -ize, which came through French from Greek. Global itself goes back through Old French to Latin globus 'ball'. Dates are approximate.","cn":"globalize 是 global 加动词后缀构成；该后缀经法语来自希腊语。global 本身经古法语上溯到拉丁 globus「球」。年代均为约数。"},"items":[{"era":"LATIN GLOBUS","en":"Globus meant 'a ball, a round mass'. Its deeper origin is not established, so no earlier form can be given with confidence.","cn":"globus 意为「球、圆块」。其更深来源未得到证明，因此无法有把握地给出更早形态。"},{"era":"ENGLISH GLOBAL","en":"The adjective global appeared in the seventeenth century and shifted from 'ball-shaped' to 'covering the whole world'.","cn":"形容词 global 在十七世纪出现，词义由「球形的」转为「覆盖全世界的」。"},{"era":"GREEK AND FRENCH SUFFIX","en":"The verb suffix -ize came through French from Greek -izein, meaning 'to make, to do, to cause to be'.","cn":"动词后缀经法语来自希腊语，意为「使……、做……、使成为」。"},{"era":"VERB FORM","en":"The verb globalize is recorded from the twentieth century, when firms and institutions began to speak of spreading operations across the planet.","cn":"动词 globalize 的书证可追到二十世纪，当时企业与机构开始谈论把业务铺向全球。"},{"era":"MODERN SPREAD","en":"Its use widened with global supply chains and international media in the late twentieth century.","cn":"二十世纪后期，随着全球供应链与国际媒体发展，它的用法扩大。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest printed use is not fixed, and the pre-Latin origin of globus remains unsettled, so any older form is a reconstruction.","cn":"来源不确定（首见年代）：最早印刷书证无法确定；globus 在拉丁语之前的来源仍无定论，凡更早形态均属重构形式。"}]},"similar":{"note":{"en":"Group one shares the ball stem and is easily confused with the verb; group two holds verbs of widening reach.","cn":"第一组共享「球」词干，容易与这个动词混淆；第二组是表示扩大覆盖范围的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"global","ipa":"/ˈɡləʊbəl/","tag":"adjective","definition":"The adjective describes the scale; the verb names the act of reaching it.","definitionCN":"形容词描述尺度；动词指达到这一尺度的动作。"},{"word":"globalization","ipa":"/ˌɡləʊbəlaɪˈzeɪʃən/","tag":"the process noun","definition":"The noun for the process that the verb sets going.","definitionCN":"指这个动词所启动的过程的名词。"},{"word":"globalized","ipa":"/ˌɡləʊbəˈlaɪzd/","tag":"past participle","definition":"Describes something already made worldwide, not the act of making it.","definitionCN":"描述已被推向全球的事物，而非使之全球化的动作。"},{"word":"globalism","ipa":"/ˈɡləʊbəlɪzəm/","tag":"the doctrine","definition":"The ideology that favours worldwide integration; the verb is the practice.","definitionCN":"指支持世界一体化的意识形态；动词则是实践。"}]},{"heading":"NEAR MEANING","entries":[{"word":"internationalize","ipa":"/ɪnˌtæʃəˈnælaɪz/","tag":"put under many nations","definition":"To bring something under the control or presence of several nations, often by treaty.","definitionCN":"指让某事物处于多国管辖或参与之下，常通过条约。"},{"word":"expand","ipa":"/ɪkˈspænd/","tag":"grow outward","definition":"A general verb for making something larger; it says nothing about crossing borders.","definitionCN":"泛指使某物变大，不含跨越国界之意。"},{"word":"liberalize","ipa":"/ˈlɪbərəlaɪz/","tag":"remove controls","definition":"To loosen state controls, which often accompanies globalizing an economy but is not the same act.","definitionCN":"指放松国家管制，常与经济全球化同行，但并非同一动作。"},{"word":"universalize","ipa":"/juːˈnɪvəsəlaɪz/","tag":"make common to all","definition":"To make something hold for everyone; it stresses coverage of people rather than geography.","definitionCN":"指使某事物对所有人成立，强调覆盖人群而非地理。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real verb forms, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实动词形式，而非编造的顺口溜。"},"normal":[{"en":"global plus the suffix that means 'make': to make something global.","cn":"global 加表示「使……」的后缀：使某事物全球。"},{"en":"The verb family runs globalize, globalizes, globalized, globalizing, globalization.","cn":"动词词族包括 globalize、globalizes、globalized、globalizing、globalization。"},{"en":"Fixed phrases: globalize the economy, globalize a business, globalize markets.","cn":"固定搭配：使经济全球化、使企业全球化、使市场全球化。"},{"en":"The passive is common: a village can be globalized by tourism.","cn":"被动式很常见：一个村庄可能被旅游业全球化。"},{"en":"Spelling note: the stem takes one consonant, with no doubled final letter.","cn":"注意拼写：词干后只接一个辅音字母，不双写词尾辅音。"}],"abstract":[{"en":"Picture a shop sign being translated into more and more languages.","cn":"想象一块店招被译成越来越多的语言。"},{"en":"Picture one desk spawning copies of itself in every time zone.","cn":"想象一张办公桌在每个时区复制出自己。"},{"en":"Picture a local recipe appearing on menus across the sea.","cn":"想象一道本地菜谱出现在海那边的菜单上。"}]},"examples":[{"en":"The company globalized its customer service without moving its headquarters.","cn":"这家公司把客服全球化，却没有搬走总部。"},{"en":"Cheap shipping helped globalize even small workshops.","cn":"廉价航运帮助连小作坊也走向全球。"},{"en":"Teachers globalize the syllabus by adding sources from other countries.","cn":"教师通过加入别国资料使课程全球化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「全球」加「使……化」——把业务铺到每一块大陆","word":"globalize"},"root":"global 经古法语来自拉丁 globus「球、圆块」，加动词后缀（经法语源自希腊语，意为「使……」）构成 globalize。globus 在拉丁语之前的来源不确定。","sensesIntro":{"en":"Eight senses follow one action: something local is made to reach the whole world, whether that thing is a programme, a company, a market, a culture, a network, a standard, a place caught in flows, or a way of thinking.","cn":"八个义项沿同一个动作展开：把本地事物推向整个世界，这个事物可以是项目、企业、市场、文化、网络、标准、被卷入流动的地点，也可以是一种思维方式。"},"semanticMap":{"core":{"en":"CORE IMAGE: a map that starts with one street and keeps gaining routes until every continent is covered.","cn":"核心意象：一张地图起初只有一条街，随后不断添上航线，直到覆盖每一块大陆。"},"chain":["WHOLE WORLD","COMPANY","OPEN ECONOMY","CULTURE","NETWORK","GLOBAL FRAME"],"branches":[{"senses":"01","en":"PLAIN ACT: the suffix simply turns 'global' into 'make global'.","cn":"基本动作：后缀只是把「全球的」变成「使全球」。"},{"senses":"02 · 07","en":"FIRM AND PLACE: a company spreads its offices, while a village is pulled into flows it did not start.","cn":"企业与地方：公司铺开办事处，村庄则被卷入并非由它开启的流动。"},{"senses":"03 · 06","en":"MARKET AND RULE: opening an economy and setting one standard are two ways of making the world one field.","cn":"市场与规则：开放经济与统一标准，是把世界变成一块场地的两种方式。"},{"senses":"04","en":"CULTURE: songs, habits and languages travel with the same channels as goods.","cn":"文化：歌曲、习惯与语言随货物走同样的通道。"},{"senses":"05 · 08","en":"WIRES AND MIND: cables make the network real, and the verb can then be applied to thought itself.","cn":"线路与思维：电缆让网络成真，随后这个动词也可以用到思维上。"}]},"affixes":{"intro":{"en":"Globalize is a transparent English construction: a Latin-derived adjective, a Greek-derived verb suffix and a family of related forms.","cn":"globalize 是一个透明的英语构造：拉丁来源的形容词、希腊来源的动词后缀，以及一族相关形式。"},"latinIntro":{"en":"Latin globus gives globe and global; the verb suffix came through French from Greek, and the noun suffix from Latin.","cn":"拉丁 globus 衍生 globe 与 global；动词后缀经法语来自希腊语，名词后缀来自拉丁语。"},"items":[{"word":"globus","structure":"globus, globi (Latin noun, second declension)","meaning":"ball, round mass","meaningCN":"球；圆块","example":"The root supplies the round image of the world.","exampleCN":"这个词根提供世界的圆形意象。"},{"word":"globe","structure":"globus through Old French","meaning":"a sphere; the earth as a map","meaningCN":"球体；地球","example":"A globe turns the planet into one object.","exampleCN":"地球仪把行星变成一个物件。"},{"word":"global","structure":"globe + -al (relating to)","meaning":"relating to the whole world","meaningCN":"与整个世界相关的","example":"Global trade links distant ports.","exampleCN":"全球贸易连接遥远的港口。"},{"word":"-ize","structure":"-ize (verb suffix, through French from Greek)","meaning":"to make, to cause to be","meaningCN":"使……；使成为","example":"The suffix turns an adjective into an action.","exampleCN":"这个后缀把形容词变成动作。"},{"word":"globalize","structure":"global + -ize","meaning":"to make worldwide","meaningCN":"使全球化","example":"Firms globalize their supply chains.","exampleCN":"企业使供应链全球化。"},{"word":"globalization","structure":"globalize + -ation (process or result)","meaning":"the process of becoming worldwide","meaningCN":"全球化的过程","example":"Globalization followed the new shipping routes.","exampleCN":"全球化随新航线而来。"},{"word":"globalized","structure":"globalize + -ed (past participle)","meaning":"already made worldwide","meaningCN":"已被全球化的","example":"A globalized city hosts many languages.","exampleCN":"一座全球化的城市容纳多种语言。"},{"word":"globalizing","structure":"globalize + -ing (present participle)","meaning":"in the process of becoming worldwide","meaningCN":"正在全球化的","example":"The globalizing industry hires abroad.","exampleCN":"这个正在全球化的行业在海外招人。"},{"word":"globalism","structure":"global + -ism (doctrine)","meaning":"a doctrine of worldwide integration","meaningCN":"世界一体化主张","example":"Globalism defends the process in principle.","exampleCN":"全球主义在原则上为这一过程辩护。"},{"word":"globally","structure":"global + -ly (adverb)","meaning":"across the world","meaningCN":"在全球范围","example":"The brand is sold globally.","exampleCN":"这个品牌在全球销售。"}],"derivatives":[{"word":"globalizer","structure":"globalize + -er (one who acts)","meaning":"a person or body that makes something worldwide","meaningCN":"推动全球化的人或机构"},{"word":"anti-globalization","structure":"anti- (against) + globalization","meaning":"opposition to worldwide integration","meaningCN":"反全球化"},{"word":"globalist","structure":"global + -ist (advocate)","meaning":"a supporter of worldwide integration","meaningCN":"全球主义者"}],"latinEntries":[{"word":"globus","structure":"globus, globi (m., second declension)","meaning":"ball, round mass","meaningCN":"球；圆块"},{"word":"globosus","structure":"globosus, -a, -um (adjective)","meaning":"round, spherical","meaningCN":"圆的；球形的"}]}},{"word":"globalized","ipa_uk":"/ˌɡləʊbəˈlaɪzd/","ipa_us":"/ˈɡloʊbəlaɪzd/","definition_zh":"已被全球化的；具有全球联系或全球特征的","definition_en":"having been made worldwide in reach, organization or character","core_image":"一条老街的店铺招牌仍写着本地语言，店里卖的却是来自几个大洲的商品，收银台连着跨国账目","scene":"同一条街上有本地菜市场，也有来自各地的连锁店，年轻人的手机里装着各国的应用。The city has become thoroughly globalized, with foreign brands on every corner.","sceneCN":"这里 globalized 是形容词，指「已被全球化改造的」（第 1 个义项：已完成全球化的状态）；句意为这座城市已被彻底全球化，每个街角都有外国品牌。可辨识物件：菜市场、连锁店招牌、手机屏幕、街角广告。","pos":[{"tag":"adj.","zh":"已被全球化的；全球化了的"},{"tag":"adj.","zh":"（动词过去分词）使全球化的"}],"collocations":[{"phrase":"highly globalized","zh":"高度全球化的"},{"phrase":"a globalized economy","zh":"全球化经济"},{"phrase":"a globalized world","zh":"全球化的世界"},{"phrase":"globalized markets","zh":"全球化市场"},{"phrase":"globalized supply chains","zh":"全球化供应链"},{"phrase":"a globalized city","zh":"全球化的城市"}],"forms":[{"label":"原级（形容词）","form":"globalized"},{"label":"比较级","form":"more globalized"},{"label":"最高级","form":"most globalized"},{"label":"动词原形","form":"globalize"},{"label":"名词（全球化）","form":"globalization"}],"derivatives":[{"word":"globalize","pos":"v.","zh":"使全球化"},{"word":"globalization","pos":"n.","zh":"全球化"},{"word":"globalizing","pos":"adj.","zh":"正在全球化的"},{"word":"global","pos":"adj.","zh":"全球的"},{"word":"globally","pos":"adv.","zh":"在全球范围"},{"word":"globalism","pos":"n.","zh":"全球主义"}],"senses":[{"no":"01","title":"Already worldwide in reach","titleCN":"已达到全球范围","definition":"having already been extended so that it covers the whole world","definitionCN":"已被扩展到覆盖整个世界","example":"The city has become thoroughly globalized, with foreign brands on every corner.","exampleCN":"这座城市已被彻底全球化，每个街角都有外国品牌。","why":"The participial ending marks a finished state: the work of reaching worldwide is already done.","whyCN":"分词词尾标记完成状态：扩展到全球的工作已经完成。"},{"no":"02","title":"Linked across countries","titleCN":"跨国联结的","definition":"connected to networks, partners or markets in many countries","definitionCN":"与多个国家的网络、伙伴或市场相连","example":"A globalized supply chain can stall when one distant port closes.","exampleCN":"一条全球化的供应链可能因一个远方港口关闭而停摆。","why":"Connection is the everyday test of the word: can the thing reach and be reached from far away?","whyCN":"联结是这个词的日常检验：该事物能否到达远方，又能否被远方触及。"},{"no":"03","title":"Organized by multinational capital","titleCN":"由跨国资本组织的","definition":"run by firms that invest, produce or hire beyond their home country","definitionCN":"由在本国之外投资、生产或雇工的企业运营","example":"The globalized auto industry designs in one country and assembles in another.","exampleCN":"全球化的汽车工业在一个国家设计，在另一个国家组装。","why":"The adjective often describes an industry whose parts are scattered by investment decisions rather than by local custom.","whyCN":"这个形容词常描述一种产业，其各部分因投资决策而分散，而非依本地习惯布局。"},{"no":"04","title":"Shaped by worldwide cultural flow","titleCN":"受全球文化流动塑造的","definition":"marked by media, food and styles drawn from many societies","definitionCN":"带有来自多个社会的媒介、饮食与风格印记","example":"Their playlist is thoroughly globalized, mixing artists from five continents.","exampleCN":"他们的播放列表彻底全球化，混着来自五个大洲的艺人。","why":"Culture, not only capital, leaves marks: a globalized taste is one assembled from many places.","whyCN":"留下印记的不只是资本，还有文化：全球化的口味是由许多地方拼成的。"},{"no":"05","title":"Standardized and homogenized","titleCN":"标准化、同质化的","definition":"made uniform by worldwide models so that local variation is reduced","definitionCN":"被全球模式统一，本地差异因此减少","example":"Critics call the globalized shopping street a row of identical glass fronts.","exampleCN":"批评者把这条全球化的商业街称作一排相同的玻璃门面。","why":"The same process that connects places can also flatten them, and the adjective carries that criticism.","whyCN":"连接各地的过程也可能把它们压平，这个形容词带着这层批评。"},{"no":"06","title":"Dependent on international trade","titleCN":"依赖国际贸易的","definition":"reliant on exports, imports or foreign demand for its survival","definitionCN":"依靠出口、进口或外国需求维持","example":"The globalized farm exports its harvest and imports its fuel.","exampleCN":"这个全球化的农场出口收成，进口燃料。","why":"Dependence is the price of connection: a globalized producer rarely supplies only its own street.","whyCN":"依赖是联结的代价：全球化的生产者很少只供应自己那条街。"},{"no":"07","title":"Placed in worldwide comparison","titleCN":"被放进全球比较的","definition":"judged, ranked or measured against peers anywhere in the world","definitionCN":"与世界任何地方的同类被一起评判、排名或衡量","example":"A globalized university ranking weighs departments against foreign rivals.","exampleCN":"全球化的大学排名把各院系与外国对手放在一起衡量。","why":"Once a standard is worldwide, every local result is read against distant ones.","whyCN":"一旦标准全球化，每个本地结果都要对照远方结果来读。"},{"no":"08","title":"Globally minded","titleCN":"具有全球视野的","definition":"thinking habitually on a world scale rather than a local one","definitionCN":"习惯以全球尺度而非本地尺度思考","example":"Her globalized outlook came from years of working across borders.","exampleCN":"她的全球视野来自多年跨国工作。","why":"The abstract sense moves from conditions to habits of mind: a person can be globalized in outlook.","whyCN":"抽象义从外部条件移到思维习惯：一个人的视野也可以是全球化的。"}],"etymology":{"intro":{"en":"Globalized is the past participle of globalize, built on global plus -ize and -ed. Global goes back through Old French to Latin globus 'ball'. Dates are approximate.","cn":"globalized 是 globalize 的过去分词，由 global 加动词后缀与分词词尾构成。global 经古法语上溯到拉丁 globus「球」。年代均为约数。"},"items":[{"era":"LATIN GLOBUS","en":"Globus meant 'a ball, a round mass'. Its deeper origin is not established, so no earlier form is given with confidence.","cn":"globus 意为「球、圆块」。其更深来源未得到证明，因此无法有把握地给出更早形态。"},{"era":"ENGLISH GLOBAL","en":"The adjective global appeared in the seventeenth century and later came to mean 'covering the whole world'.","cn":"形容词 global 在十七世纪出现，后来意为「覆盖全世界的」。"},{"era":"VERB GLOBALIZE","en":"The verb globalize is a twentieth-century formation from global plus the suffix meaning 'to make'.","cn":"动词 globalize 是二十世纪由 global 加表示「使……」的后缀构成。"},{"era":"PAST PARTICIPLE","en":"Adding the participial ending turned the verb into a description of a finished condition.","cn":"加上分词词尾后，动词变成对一种完成状态的描述。"},{"era":"MODERN USE","en":"The adjective spread with talk of global markets, global cities and global supply chains in the late twentieth century.","cn":"二十世纪后期，随着全球市场、全球城市与全球供应链的说法，这个形容词流行起来。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest use of the adjective is not fixed, and the pre-Latin origin of globus remains unsettled, so any older form is a reconstruction.","cn":"来源不确定（首见年代）：这个形容词的最早书证无法确定；globus 在拉丁语之前的来源仍无定论，凡更早形态均属重构形式。"}]},"similar":{"note":{"en":"Group one shares the same stem; group two holds adjectives of wide connection.","cn":"第一组共享同一词干；第二组是表示广泛联结的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"globalize","ipa":"/ˌɡləʊbəˈlaɪz/","tag":"the verb","definition":"The action that produces the state; the participle describes the result.","definitionCN":"产生这一状态的动作；分词描述结果。"},{"word":"globalization","ipa":"/ˌɡləʊbəlaɪˈzeɪʃən/","tag":"the process","definition":"The process as a whole, rather than one thing that has undergone it.","definitionCN":"指整个过程，而非某个经历此过程的事物。"},{"word":"global","ipa":"/ˈɡləʊbəl/","tag":"plain adjective","definition":"Simply means worldwide; it does not say whether the reach is complete.","definitionCN":"只表示全球的，不说明覆盖是否已完成。"},{"word":"globally","ipa":"/ˈɡləʊbəli/","tag":"adverb","definition":"Describes the scale of an action, not the condition of a thing.","definitionCN":"描述动作的尺度，而非事物的状态。"}]},{"heading":"NEAR MEANING","entries":[{"word":"international","ipa":"/ˌɪntəˈnæʃənəl/","tag":"between nations","definition":"Involves two or more nations but need not cover the globe.","definitionCN":"涉及两个或更多国家，但不必覆盖全球。"},{"word":"integrated","ipa":"/ˈɪntɪɡreɪtɪd/","tag":"joined into one system","definition":"Describes parts joined into a working whole, which is one effect of globalization.","definitionCN":"描述各部分并入一个运作整体，这是全球化的一个结果。"},{"word":"multinational","ipa":"/ˌmʌltiˈnæʃənəl/","tag":"many countries","definition":"Usually describes a company operating in several countries, not a whole society.","definitionCN":"通常描述在多国运营的公司，而非整个社会。"},{"word":"westernized","ipa":"/ˈwestənaɪzd/","tag":"adopting Western models","definition":"Names one direction of change; globalized is broader and less directional.","definitionCN":"指一个方向的变化；globalized 范围更广、方向性更弱。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real contrasts, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实对比，而非编造的顺口溜。"},"normal":[{"en":"The ending marks a finished state: not 'becoming global' but 'already globalized'.","cn":"词尾标记完成状态：不是「正在变全球」，而是「已经全球化」。"},{"en":"The family runs globalize, globalized, globalizing, globalization.","cn":"同族词包括 globalize、globalized、globalizing、globalization。"},{"en":"Fixed phrases: a globalized economy, globalized markets, globalized supply chains.","cn":"固定搭配：全球化经济、全球化市场、全球化供应链。"},{"en":"Compare with global: global names the scale, globalized names the result.","cn":"与 global 比较：global 指尺度，globalized 指结果。"},{"en":"The word often appears with cities, industries and farms, not with single objects.","cn":"这个词常与城市、产业、农场连用，而非与单个物件连用。"}],"abstract":[{"en":"Picture a street where every sign is local but every product is from elsewhere.","cn":"想象一条街，招牌全是本地的，商品却全来自别处。"},{"en":"Picture a machine whose parts were made on four continents before it was assembled.","cn":"想象一台机器，组装之前零件已在四大洲造成。"},{"en":"Picture a person who checks the weather in three countries before breakfast.","cn":"想象一个人吃早饭前先查三个国家的天气。"}]},"examples":[{"en":"A globalized port handles goods from more countries than its own citizens can name.","cn":"一座全球化的港口处理的货物来自比本地居民能说出的更多的国家。"},{"en":"The globalized curriculum includes sources translated from four languages.","cn":"全球化的课程包含从四种语言译来的资料。"},{"en":"Even a globalized village keeps local festivals alive.","cn":"即便是全球化的村庄也保留着本地节庆。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「全球」加「已……化」——整座城市已经接上全球的插头","word":"globalized"},"root":"globalized 是 globalize 的过去分词；global 经古法语来自拉丁 globus「球、圆块」，动词后缀经法语源自希腊语，意为「使……」。globus 更早的来源不确定。","sensesIntro":{"en":"Eight senses describe one finished condition from different angles: a thing may be worldwide in reach, linked across borders, run by multinational capital, marked by foreign culture, flattened into sameness, dependent on trade, placed in global comparison, or global in outlook.","cn":"八个义项从不同角度描述同一种完成状态：某事物可以在范围上覆盖全球、跨国联结、由跨国资本运营、带外国文化印记、被压平成同一模样、依赖贸易、被放进全球比较，或在视野上全球化。"},"semanticMap":{"core":{"en":"CORE IMAGE: a shop whose sign is local but whose goods and accounts come from several continents.","cn":"核心意象：一家招牌是本地的店，货物与账目却来自几个大洲。"},"chain":["FINISHED STATE","CROSS-BORDER LINKS","MULTINATIONAL CAPITAL","CULTURAL FLOW","UNIFORMITY","WORLD OUTLOOK"],"branches":[{"senses":"01","en":"DONE, NOT DOING: the participle points to a condition already reached.","cn":"已完成而非进行中：分词指向已经达到的状态。"},{"senses":"02 · 06","en":"LINKED AND EXPOSED: connection brings trade and also dependence.","cn":"联结与暴露：联结带来贸易，也带来依赖。"},{"senses":"03","en":"CAPITAL: offices and factories follow investment across borders.","cn":"资本：办事处与工厂随投资越过国界。"},{"senses":"04 · 05","en":"CULTURE AND FLATTENING: borrowed tastes enrich a place and can also make it look like every other place.","cn":"文化与压平：借来的口味丰富一个地方，也可能让它看起来和别处一样。"},{"senses":"07 · 08","en":"MEASURE AND MIND: worldwide ranking turns local results into comparisons, and the same scale can become a habit of thought.","cn":"衡量与思维：全球排名把本地结果变成比较，同一尺度也可以变成思维习惯。"}]},"affixes":{"intro":{"en":"The adjective is built from a Latin noun for a ball, an English adjective, a Greek-derived verb suffix and a participial ending.","cn":"这个形容词由拉丁「球」名词、英语形容词、希腊来源的动词后缀与分词词尾构成。"},"latinIntro":{"en":"Latin globus supplies globe and global; the verb suffix came through French from Greek, and the participial ending is English.","cn":"拉丁 globus 衍生 globe 与 global；动词后缀经法语来自希腊语，分词词尾是英语本族成分。"},"items":[{"word":"globus","structure":"globus, globi (Latin noun, second declension)","meaning":"ball, round mass","meaningCN":"球；圆块","example":"The root gives the round image of the world.","exampleCN":"这个词根提供世界的圆形意象。"},{"word":"globe","structure":"globus through Old French","meaning":"a sphere; the earth as a map","meaningCN":"球体；地球","example":"A globe makes the planet one object.","exampleCN":"地球仪把行星变成一个物件。"},{"word":"global","structure":"globe + -al (relating to)","meaning":"relating to the whole world","meaningCN":"与整个世界相关的","example":"Global trade links distant ports.","exampleCN":"全球贸易连接遥远的港口。"},{"word":"globalize","structure":"global + -ize (make, cause to be)","meaning":"to make worldwide","meaningCN":"使全球化","example":"Firms globalize their supply chains.","exampleCN":"企业使供应链全球化。"},{"word":"-ed","structure":"-ed (English participial ending)","meaning":"having undergone the action","meaningCN":"已经经历该动作的","example":"The ending turns the verb into a state.","exampleCN":"这个词尾把动词变成状态。"},{"word":"globalized","structure":"globalize + -ed","meaning":"already made worldwide","meaningCN":"已被全球化的","example":"A globalized city hosts many languages.","exampleCN":"一座全球化的城市容纳多种语言。"},{"word":"globalizing","structure":"globalize + -ing (present participle)","meaning":"in the process of becoming worldwide","meaningCN":"正在全球化的","example":"The globalizing industry hires abroad.","exampleCN":"这个正在全球化的行业在海外招人。"},{"word":"globalization","structure":"globalize + -ation (process noun)","meaning":"the process of becoming worldwide","meaningCN":"全球化的过程","example":"Globalization reshaped the port.","exampleCN":"全球化重塑了港口。"},{"word":"globalism","structure":"global + -ism (doctrine)","meaning":"a doctrine of worldwide integration","meaningCN":"世界一体化主张","example":"Globalism defends the trend in principle.","exampleCN":"全球主义在原则上为这一趋势辩护。"},{"word":"globally","structure":"global + -ly (adverb)","meaning":"across the world","meaningCN":"在全球范围","example":"The brand is sold globally.","exampleCN":"这个品牌在全球销售。"}],"derivatives":[{"word":"globalize","structure":"global + -ize (verb)","meaning":"to make worldwide","meaningCN":"使全球化"},{"word":"globalization","structure":"globalize + -ation (noun)","meaning":"the process of becoming worldwide","meaningCN":"全球化"},{"word":"globalizer","structure":"globalize + -er (agent)","meaning":"one that makes something worldwide","meaningCN":"推动全球化者"}],"latinEntries":[{"word":"globus","structure":"globus, globi (m., second declension)","meaning":"ball, round mass","meaningCN":"球；圆块"},{"word":"globosus","structure":"globosus, -a, -um (adjective)","meaning":"round, spherical","meaningCN":"圆的；球形的"}]}},{"word":"cultural diffusion","ipa_uk":"/ˌkʌltʃərəl dɪˈfjuːʒən/","ipa_us":"/ˌkʌltʃərəl dɪˈfjuːʒən/","definition_zh":"文化扩散；文化要素通过接触从一个社会传到另一个社会的过程","definition_en":"the spread of customs, tools, ideas or languages from one society to another through contact","core_image":"一条古道上，一袋种子、一只陶罐和一句祝福语同时向前走，到了山口就换成了当地人的手","scene":"沿着古道，一种作物、一套陶器纹样和一句祝福语从山地传到海边。The spread of maize from one valley to another is a clear case of cultural diffusion.","sceneCN":"这里 cultural diffusion 指「文化要素经接触从一个社会传到另一个社会」（第 1 个义项：文化特质跨群体传播的总过程）；句意为玉米从一个山谷传到另一个山谷，是文化扩散的明显例子。可辨识物件：古道、种子袋、陶罐、山口、海船。","pos":[{"tag":"n.","zh":"文化扩散（人类学术语，常作不可数）"},{"tag":"n.","zh":"一次具体的文化扩散（可数）"}],"collocations":[{"phrase":"cultural diffusion of ideas","zh":"观念的文化扩散"},{"phrase":"the study of cultural diffusion","zh":"文化扩散研究"},{"phrase":"cultural diffusion through trade","zh":"经由贸易的文化扩散"},{"phrase":"cultural diffusion and adaptation","zh":"文化扩散与调适"},{"phrase":"a case of cultural diffusion","zh":"一个文化扩散案例"},{"phrase":"the direction of cultural diffusion","zh":"文化扩散的方向"}],"forms":[{"label":"不可数用法（整体过程）","form":"cultural diffusion"},{"label":"可数复数（具体案例）","form":"cultural diffusions"},{"label":"形容词（文化的）","form":"cultural"},{"label":"名词（扩散）","form":"diffusion"},{"label":"动词（扩散）","form":"diffuse"},{"label":"形容词（扩散性的）","form":"diffusive"}],"derivatives":[{"word":"diffuse","pos":"v./adj.","zh":"扩散；散布 / 分散的"},{"word":"diffusion","pos":"n.","zh":"扩散；传播"},{"word":"diffusive","pos":"adj.","zh":"扩散性的"},{"word":"cultural","pos":"adj.","zh":"文化的"},{"word":"culture","pos":"n.","zh":"文化；培养"},{"word":"culturally","pos":"adv.","zh":"在文化上"}],"senses":[{"no":"01","title":"Traits spreading between societies","titleCN":"文化特质跨社会传播","definition":"the movement of customs, tools or ideas from one society to another through contact","definitionCN":"风俗、工具或观念经接触从一个社会传到另一个社会","example":"The spread of maize from one valley to another is a clear case of cultural diffusion.","exampleCN":"玉米从一个山谷传到另一个山谷，是文化扩散的明显例子。","why":"Diffusion is the general word for spreading outward, and anthropology attached it to culture as the normal path by which traits travel.","whyCN":"diffusion 泛指向外散开，人类学把它接到文化上，指文化特质传播的常规路径。"},{"no":"02","title":"Channels of contact","titleCN":"接触渠道","definition":"the routes by which traits travel, such as migration, trade or conquest","definitionCN":"文化特质借以传播的路径，如迁徙、贸易或征服","example":"Trade caravans were the main channel of cultural diffusion across the desert.","exampleCN":"商队是穿越沙漠的主要文化扩散渠道。","why":"Nothing spreads without a carrier; the term often names the road as much as the thing that moves.","whyCN":"没有载体就没有传播；这个词常既指移动之物，也指它所走的道路。"},{"no":"03","title":"Material diffusion","titleCN":"物质文化扩散","definition":"the spread of objects, crops and techniques between regions","definitionCN":"器物、作物与技术在各地区间传播","example":"Bronze casting reached new regions by cultural diffusion rather than by conquest alone.","exampleCN":"青铜铸造经文化扩散而非仅靠征服传到新地区。","why":"Tools leave durable traces, so material diffusion is the easiest kind for archaeologists to see.","whyCN":"工具留下耐久痕迹，因此物质扩散是考古学家最容易看到的一类。"},{"no":"04","title":"Ideas and beliefs","titleCN":"观念与信仰的扩散","definition":"the spread of religious, political or scientific ideas across societies","definitionCN":"宗教、政治或科学观念跨越社会传播","example":"The monastery network drove the cultural diffusion of a new script.","exampleCN":"修道院网络推动了一种新文字的文化扩散。","why":"Ideas travel lighter than objects but need institutions to carry them, which is why schools and monasteries appear in the record.","whyCN":"观念比物件轻，却需要机构来承载，因此学校与修道院常出现在记载中。"},{"no":"05","title":"Language diffusion","titleCN":"语言扩散","definition":"the spread of words, sounds or whole languages from one community to another","definitionCN":"词语、语音或整门语言从一个群体传到另一个群体","example":"Loanwords record cultural diffusion long after the traders have gone.","exampleCN":"借词记录下文化扩散，即便商人早已离去。","why":"Language is the clearest fossil of contact: borrowed words remain after the goods are forgotten.","whyCN":"语言是接触最清晰的化石：货物被遗忘后，借词仍留下。"},{"no":"06","title":"Indirect or stimulus diffusion","titleCN":"间接扩散与刺激扩散","definition":"a trait inspired from afar but rebuilt locally rather than copied whole","definitionCN":"受远方启发却在本地重建，而非整体照搬","example":"The local wheel was a case of stimulus diffusion: the idea arrived, the design did not.","exampleCN":"本地车轮属于刺激扩散：想法到了，设计没到。","why":"Contact does not always carry a finished object; sometimes it carries only an idea strong enough to start local work.","whyCN":"接触未必带来成品，有时只带来一个足以引发本地制作的想法。"},{"no":"07","title":"Reinterpretation on arrival","titleCN":"到达后的再解释","definition":"the remaking of a borrowed trait so that it fits local meanings","definitionCN":"把借来的文化特质重新改造，以贴合本地意义","example":"The borrowed festival underwent cultural diffusion into a harvest celebration.","exampleCN":"这个借来的节日经文化扩散变成了丰收庆典。","why":"A trait changes meaning when it changes hands, and the term covers that local rewriting, not only the journey.","whyCN":"文化特质易手时意义也变，这个词覆盖这种本地改写，而不只是旅程。"},{"no":"08","title":"Two-way spread","titleCN":"双向传播","definition":"exchange in both directions rather than a one-way export","definitionCN":"双向交换，而非单向输出","example":"Food travelled in both directions, so cultural diffusion ran both ways across the border.","exampleCN":"食物双向流动，因此文化扩散在边境两侧同时进行。","why":"The word does not require a superior source; diffusion can run from colony to metropole as well as the reverse.","whyCN":"这个词并不预设优越的源头；扩散既可从殖民地流向宗主国，也可反向。"}],"etymology":{"intro":{"en":"Cultural diffusion joins cultural, from Latin cultura 'tilling, cultivation' and colere 'to till, cultivate, worship', with diffusion, from Latin diffundere 'to pour out in different directions'. The anthropological sense is late nineteenth century. Dates are approximate.","cn":"cultural diffusion 由 cultural 与 diffusion 合成：cultural 来自拉丁 cultura「耕作、培养」与 colere「耕作、培养、敬奉」；diffusion 来自拉丁 diffundere「向各处倒出」。人类学义形成于十九世纪后期。年代均为约数。"},"items":[{"era":"LATIN CULTURA","en":"Cultura came from colere 'to till, cultivate, inhabit, worship'; the noun first named farming and later the tending of the mind.","cn":"cultura 来自 colere「耕作、培养、居住、敬奉」；这个名词先指农耕，后指心智的培养。"},{"era":"LATIN DIFFUNDERE","en":"Diffundere combined dis- 'apart, in different directions' with fundere 'to pour', giving the image of liquid spreading outward.","cn":"diffundere 由 dis-「分开、向各方」与 fundere「倒」构成，意象是液体向四周散开。"},{"era":"ENGLISH DIFFUSION","en":"English diffusion appeared in the sixteenth century for physical spreading, such as light, heat or liquid.","cn":"英语 diffusion 在十六世纪出现，指光、热或液体等物理性的散开。"},{"era":"ANTHROPOLOGY","en":"Late nineteenth-century anthropologists borrowed the word for the spread of cultural traits, and the phrase cultural diffusion became standard.","cn":"十九世纪后期的人类学家借用这个词指文化特质的传播，cultural diffusion 这一短语随之成为标准说法。"},{"era":"LATER DEBATE","en":"Twentieth-century debates over how much of a culture is borrowed rather than invented kept the term central to the discipline.","cn":"二十世纪关于一种文化有多少是借来而非自创的争论，使这个术语一直处于学科中心。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the first use of the exact phrase is not fixed, and the pre-Latin origin of colere and fundere is reconstructed rather than attested.","cn":"来源不确定（首见年代与更深词源）：这个确切短语的最早使用无法确定；colere 与 fundere 在拉丁语之前的来源属重构形式，并无实际书证。"}]},"similar":{"note":{"en":"Group one shares the two Latin stems; group two holds terms for culture travelling between societies.","cn":"第一组共享两个拉丁词干；第二组是描述文化在社会间流动的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"diffusion","ipa":"/dɪˈfjuːʒən/","tag":"the bare noun","definition":"The physical or general spreading; the full phrase adds the cultural content.","definitionCN":"指物理或一般性的散开；完整短语才加上文化内容。"},{"word":"diffuse","ipa":"/dɪˈfjuːz/","tag":"the verb","definition":"To spread outward; used of light, heat, ideas or practices.","definitionCN":"向外散开；可用于光、热、观念或做法。"},{"word":"cultural","ipa":"/ˈkʌltʃərəl/","tag":"the adjective","definition":"Relates to culture; it marks what is spreading, not the spread itself.","definitionCN":"与文化相关；标记传播的内容，而非传播本身。"},{"word":"culture","ipa":"/ˈkʌltʃə/","tag":"the base noun","definition":"The whole way of life; one culture can borrow from another.","definitionCN":"指整套生活方式；一种文化可以向另一种借用。"}]},{"heading":"NEAR MEANING","entries":[{"word":"transmission","ipa":"/trænsˈmɪʃən/","tag":"handing on","definition":"The passing of culture from person to person, often within a society rather than between societies.","definitionCN":"指文化在人与人之间传递，常在一社会内部而非社会之间。"},{"word":"borrowing","ipa":"/ˈbɒrəʊɪŋ/","tag":"taking a trait","definition":"The adoption of a specific item from another culture, a narrower act than diffusion.","definitionCN":"指采纳另一文化的具体项目，比扩散更窄。"},{"word":"acculturation","ipa":"/æˌkʌltʃəˈreɪʃən/","tag":"change through contact","definition":"The wider change that follows prolonged contact, including but not limited to diffusion.","definitionCN":"指长期接触后的更广泛变化，包含扩散但不止于扩散。"},{"word":"enculturation","ipa":"/ˌenkʌltʃəˈreɪʃən/","tag":"learning one's own","definition":"Learning the culture one is born into; it is not cross-society spread.","definitionCN":"指习得自己出生其中的文化，并非跨社会传播。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real contrasts, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实对比，而非编造的顺口溜。"},"normal":[{"en":"Culture came from a verb meaning 'to till', and diffusion from a verb meaning 'to pour out'.","cn":"culture 来自意为「耕作」的动词，diffusion 来自意为「倒出」的动词。"},{"en":"The family runs culture, cultural, culturally, diffuse, diffusion, diffusive.","cn":"同族词包括 culture、cultural、culturally、diffuse、diffusion、diffusive。"},{"en":"Fixed phrases: cultural diffusion through trade, a case of cultural diffusion.","cn":"固定搭配：经由贸易的文化扩散、一个文化扩散案例。"},{"en":"The phrase usually appears in anthropology and history, not in everyday small talk.","cn":"这个短语通常出现在人类学与历史学中，而非日常闲谈。"},{"en":"Distinguish it from transmission, which can happen inside one society.","cn":"把它与 transmission 区分开：后者可发生在同一社会内部。"}],"abstract":[{"en":"Picture a seed bag and a clay pot walking the same road together.","cn":"想象一袋种子与一只陶罐在同一条路上一起走。"},{"en":"Picture a song arriving by sea and being sung in a new key on shore.","cn":"想象一首歌经海路到达，在岸上换了调子被唱起。"},{"en":"Picture a borrowed tool being reshaped by the hand that receives it.","cn":"想象一件借来的工具被接手的那只手改造。"}]},"examples":[{"en":"Historians use shipping records to trace cultural diffusion across the Indian Ocean.","cn":"历史学家用航运记录追踪印度洋上的文化扩散。"},{"en":"Cultural diffusion explains why two distant cuisines share the same spice.","cn":"文化扩散解释了为何两种相隔遥远的饮食共用同一种香料。"},{"en":"The term covers both copied objects and locally rebuilt ideas.","cn":"这个术语既覆盖照搬的物件，也覆盖本地重建的观念。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「cultural（文化的）+ diffusion（扩散）」——文化像水一样从一处渗到另一处","word":"cultural diffusion"},"root":"cultural 来自拉丁 cultura「耕作、培养」，源于 colere「耕作、培养、敬奉」；diffusion 来自拉丁 diffundere「向各处倒出」，由 dis-「分开」与 fundere「倒」构成。更早的印欧形态均属重构。","sensesIntro":{"en":"Eight senses follow one journey: a trait leaves one society through a channel, and the term then separates material objects, ideas, language, indirect inspiration, local rewriting and two-way traffic.","cn":"八个义项沿同一段旅程展开：文化特质经某种渠道离开一个社会，这个术语再区分物质物件、观念、语言、间接启发、本地改写与双向流动。"},"semanticMap":{"core":{"en":"CORE IMAGE: a seed bag and a clay pot travelling one road and changing hands at the pass.","cn":"核心意象：一袋种子与一只陶罐走在同一条路上，在关口易手。"},"chain":["CONTACT","ROUTES","OBJECTS","IDEAS","REBUILDING","BOTH WAYS"],"branches":[{"senses":"01","en":"CONTACT FIRST: without two societies meeting, nothing travels.","cn":"接触在先：没有两个社会相遇，就没有东西移动。"},{"senses":"02 · 08","en":"ROUTES AND RETURN: the same road can carry traffic in both directions.","cn":"道路与回流：同一条路可以双向承载。"},{"senses":"03 · 04","en":"OBJECTS AND IDEAS: things and thoughts need different carriers but share one name.","cn":"物件与观念：东西与思想需要不同载体，却共用一个名称。"},{"senses":"05","en":"LANGUAGE: borrowed words survive after the goods are gone.","cn":"语言：货物消失后，借词仍然留下。"},{"senses":"06 · 07","en":"REBUILDING: contact can deliver an idea rather than an object, and arrival always rewrites meaning.","cn":"重建：接触可以送来想法而非物件，而到达总会改写意义。"}]},"affixes":{"intro":{"en":"The phrase can be read from two Latin stems: one for tilling and cultivation, one for pouring outward.","cn":"这个短语可以按两个拉丁词干读出：一个表示耕作与培养，一个表示向外倾倒。"},"latinIntro":{"en":"Latin cultura supplies culture and cultural, while Latin fundere supplies diffuse and diffusion; dis- adds the outward direction.","cn":"拉丁 cultura 衍生 culture 与 cultural，拉丁 fundere 衍生 diffuse 与 diffusion；dis- 增添向外方向。"},"items":[{"word":"colere","structure":"colere, colui, cultum (Latin verb, third conjugation)","meaning":"to till, cultivate, inhabit, worship","meaningCN":"耕作；培养；居住；敬奉","example":"The verb supplies the farming image behind culture.","exampleCN":"这个动词提供 culture 背后的农耕意象。"},{"word":"cultura","structure":"cultura, culturae (Latin noun, first declension)","meaning":"tilling; cultivation; care","meaningCN":"耕作；培养；照料","example":"Cultura first named the field and later the mind.","exampleCN":"cultura 先指田地，后指心智。"},{"word":"cultural","structure":"cultura + -al (relating to)","meaning":"relating to culture","meaningCN":"与文化相关的","example":"Cultural traits travel between societies.","exampleCN":"文化特质在社会间流动。"},{"word":"culture","structure":"cultura through Old French","meaning":"the way of life of a people","meaningCN":"一个民族的生活方式","example":"One culture borrows from another.","exampleCN":"一种文化向另一种借用。"},{"word":"fundere","structure":"fundere, fudi, fusum (Latin verb, third conjugation)","meaning":"to pour","meaningCN":"倾倒；使流出","example":"The verb gives the image of liquid spreading.","exampleCN":"这个动词给出液体散开的意象。"},{"word":"dis-","structure":"dis- (Latin prefix)","meaning":"apart, in different directions","meaningCN":"分开；向不同方向","example":"The prefix sends the flow outward.","exampleCN":"这个前缀把流动送往四方。"},{"word":"diffundere","structure":"dis- + fundere (Latin verb)","meaning":"to pour out in different directions","meaningCN":"向各处倒出","example":"The compound names a spreading outward.","exampleCN":"这个合成词指向外散开。"},{"word":"diffuse","structure":"diffundere, through French","meaning":"to spread out","meaningCN":"扩散；散布","example":"Ideas diffuse faster than objects.","exampleCN":"观念比物件扩散得快。"},{"word":"diffusion","structure":"diffuse + -ion (process noun)","meaning":"the process of spreading out","meaningCN":"扩散的过程","example":"Diffusion leaves traces in language.","exampleCN":"扩散在语言中留下痕迹。"},{"word":"-al","structure":"-al (adjective suffix, from Latin)","meaning":"relating to","meaningCN":"与……相关的","example":"The suffix turns a noun into an adjective.","exampleCN":"这个后缀把名词变成形容词。"}],"derivatives":[{"word":"diffusive","structure":"diffuse + -ive (tending to)","meaning":"tending to spread out","meaningCN":"有扩散倾向的"},{"word":"culturally","structure":"cultural + -ly (adverb)","meaning":"in cultural terms","meaningCN":"在文化方面"},{"word":"cultivated","structure":"cultivate + -ed (past participle)","meaning":"tilled or developed by care","meaningCN":"被耕种的；有修养的"}],"latinEntries":[{"word":"cultura","structure":"cultura, culturae (f., first declension)","meaning":"tilling; cultivation; care","meaningCN":"耕作；培养；照料"},{"word":"fundere","structure":"fundere, fudi, fusum (verb, third conjugation)","meaning":"to pour","meaningCN":"倾倒；使流出"},{"word":"diffusio","structure":"diffusio, diffusionis (f., third declension)","meaning":"a spreading out","meaningCN":"扩散；散开"}]}},{"word":"assimilation","ipa_uk":"/əˌsɪmɪˈleɪʃən/","ipa_us":"/əˌsɪməˈleɪʃən/","definition_zh":"同化；吸收；使某物融入更大的整体","definition_en":"the process of becoming like something else, or of absorbing something into a larger whole","core_image":"一颗石子落进一锅浓汤，外形渐渐消失，味道却散进整锅汤里","scene":"新搬来的家庭在几年里改说当地语言、参加本地节庆，孩子们的同学不再觉得他们外来。Over two generations, the immigrant family achieved full assimilation into the host community.","sceneCN":"这里 assimilation 指「移民群体逐步融入主流社会的文化同化」（第 1 个义项：群体吸收进主流文化的过程）；句意为经过两代人，这个移民家庭完成了对当地社会的同化。可辨识物件：街区、节庆旗帜、学校门口、家庭餐桌。","pos":[{"tag":"n.","zh":"同化；融合（社会文化义，常作不可数）"},{"tag":"n.","zh":"吸收（生理、认知或语音义）"}],"collocations":[{"phrase":"cultural assimilation","zh":"文化同化"},{"phrase":"assimilation into society","zh":"融入社会"},{"phrase":"the assimilation of immigrants","zh":"移民的同化"},{"phrase":"phonetic assimilation","zh":"语音同化"},{"phrase":"assimilation of nutrients","zh":"营养吸收"},{"phrase":"forced assimilation","zh":"强制同化"}],"forms":[{"label":"不可数用法（整体过程）","form":"assimilation"},{"label":"可数复数（具体过程或案例）","form":"assimilations"},{"label":"动词（同化；吸收）","form":"assimilate"},{"label":"形容词（同化的）","form":"assimilative"},{"label":"形容词（可被吸收的）","form":"assimilable"},{"label":"名词（同化论者）","form":"assimilationist"}],"derivatives":[{"word":"assimilate","pos":"v.","zh":"同化；吸收；使相似"},{"word":"assimilative","pos":"adj.","zh":"同化的；吸收的"},{"word":"assimilable","pos":"adj.","zh":"可同化的；可吸收的"},{"word":"assimilationist","pos":"n./adj.","zh":"主张同化者（的）"},{"word":"assimilated","pos":"adj.","zh":"已被同化的"},{"word":"dissimilation","pos":"n.","zh":"异化（语音或文化上的反向过程）"}],"senses":[{"no":"01","title":"Cultural absorption into a host society","titleCN":"融入主流社会的文化同化","definition":"the process by which a group or person takes on the culture of a host society","definitionCN":"群体或个人逐渐接受主流社会文化的过程","example":"Over two generations, the immigrant family achieved full assimilation into the host community.","exampleCN":"经过两代人，这个移民家庭完成了对当地社会的同化。","why":"The Latin verb meant 'to make like'; in society the process makes newcomers like the majority.","whyCN":"拉丁动词意为「使相似」；在社会层面，这个过程使新来者变得像多数人。"},{"no":"02","title":"Physiological absorption","titleCN":"生理吸收","definition":"the process by which the body takes nutrients into its own tissue","definitionCN":"身体把营养纳入自身组织的过程","example":"Assimilation of nutrients begins in the small intestine.","exampleCN":"营养的吸收从小肠开始。","why":"The body literally makes food like itself, turning foreign matter into tissue, which is the oldest concrete sense.","whyCN":"身体确实把食物变得像自己，把外来物质变成组织，这是最古老的具体义。"},{"no":"03","title":"Cognitive assimilation","titleCN":"认知同化","definition":"the fitting of new experience into an existing mental framework","definitionCN":"把新经验纳入既有心智框架","example":"Piaget described assimilation as fitting new experience into an existing schema.","exampleCN":"皮亚杰把同化描述为把新经验纳入既有图式。","why":"The mind, like the body, absorbs what is new by making it fit what is already there.","whyCN":"心智与身体一样，通过让新事物贴合已有之物来吸收它。"},{"no":"04","title":"Phonetic assimilation","titleCN":"语音同化","definition":"the change of a speech sound so that it becomes more like a neighbouring sound","definitionCN":"一个语音变得与相邻语音更相似","example":"In handbag the n of hand becomes m by assimilation before b.","exampleCN":"在英语复合词「手袋」中，前一词尾的鼻音受后接双唇音影响，经同化变成双唇鼻音。","why":"Sounds, like people, adjust to their neighbours; the technical sense applies the old verb to pronunciation.","whyCN":"音与人一样会向邻居靠拢；这个技术义把古老的动词用到发音上。"},{"no":"05","title":"Immigrant assimilation policy","titleCN":"移民同化政策","definition":"a state programme that expects newcomers to adopt the majority culture","definitionCN":"要求新来者接受多数文化的国家政策","example":"The city's assimilation policy offered language classes but demanded cultural surrender.","exampleCN":"这座城市的同化政策提供语言课程，却要求文化上的归顺。","why":"When the process is planned by institutions, the noun names a policy and carries its political weight.","whyCN":"当过程由机构规划时，这个名词指一项政策，并带上政治分量。"},{"no":"06","title":"Structural assimilation","titleCN":"结构性同化","definition":"entry of a minority into the institutions and social networks of the majority","definitionCN":"少数群体进入多数群体的制度与社会网络","example":"Structural assimilation meant immigrants entered clubs, schools and political parties.","exampleCN":"结构性同化意味着移民进入俱乐部、学校与政党。","why":"Sociologists split assimilation into parts; the structural part concerns access to institutions rather than taste or language.","whyCN":"社会学家把同化分成若干部分；结构部分关乎制度准入，而非口味或语言。"},{"no":"07","title":"Forced assimilation","titleCN":"强制同化","definition":"assimilation imposed by power, often through schools, law or punishment","definitionCN":"由权力强加的同化，常通过学校、法律或惩罚","example":"Boarding schools practised forced assimilation of indigenous children.","exampleCN":"寄宿学校对原住民儿童实行强制同化。","why":"The same noun can name coercion, because absorption into a larger whole may be demanded rather than chosen.","whyCN":"同一个名词也能指强迫，因为融入更大整体可能是被要求而非自愿的。"},{"no":"08","title":"Abstract incorporation into a framework","titleCN":"抽象地并入框架","definition":"the incorporation of a foreign element into an existing system or narrative","definitionCN":"把外来要素并入既有体系或叙述","example":"The essay assimilates every dissent into one smooth narrative.","exampleCN":"这篇文章把一切异议都同化进一个平滑的叙述。","why":"The abstract sense drops people and bodies: any odd element can be made to fit a system.","whyCN":"抽象义不再涉及人与身体：任何异质要素都可以被弄得贴合某个体系。"}],"etymology":{"intro":{"en":"Assimilation comes from Latin assimilatio, from assimilare 'to make like', built on ad- 'to' and similis 'like'. English uses it for bodies, minds, sounds and societies. Dates are approximate.","cn":"assimilation 来自拉丁 assimilatio，源于 assimilare「使相似」，由 ad-「向」与 similis「相似」构成。英语用它指身体、心智、语音与社会。年代均为约数。"},"items":[{"era":"LATIN SIMILIS","en":"Similis meant 'like, similar'. It is generally connected with simul 'together' and similis 'like', but the pre-Latin shape is a reconstruction rather than a witnessed form.","cn":"similis 意为「相似的」。一般认为它与 simul「一起」同源，但拉丁语之前的形态属重构形式，并无实际书证。"},{"era":"LATIN ASSIMILARE","en":"Ad- 'to, toward' plus similis produced assimilare 'to make like, to liken, to absorb'.","cn":"ad-「向、朝」加 similis 构成 assimilare「使相似、比作、吸收」。"},{"era":"ENGLISH NOUN","en":"The noun entered English in the sixteenth century, first in the general sense of making one thing like another.","cn":"这个名词在十六世纪进入英语，最初泛指使一物像另一物。"},{"era":"BODY AND MIND","en":"Physiology adopted it for the conversion of food into tissue, and psychology later for the fitting of new experience into existing schemas.","cn":"生理学用它指食物转化为组织，心理学后来用它指把新经验纳入既有图式。"},{"era":"SOCIETY AND SPEECH","en":"Nineteenth-century sociology applied it to immigrant groups, and linguistics used it for sounds becoming like their neighbours.","cn":"十九世纪社会学把它用于移民群体，语言学则用它指语音向邻近语音靠拢。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the link of similis to simul is generally accepted but the pre-Latin form is reconstructed, and the earliest use of each technical sense is not precisely dated.","cn":"来源不确定（更深词源）：similis 与 simul 的联系虽被一般接受，但拉丁语之前的形态属重构形式；各技术义的最早书证年代并不精确。"}]},"similar":{"note":{"en":"Group one is built on the same 'like' root; group two names absorption or blending under other names.","cn":"第一组同出「相似」词根；第二组是用其他名称表达吸收或混合的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"assimilate","ipa":"/əˈsɪmɪleɪt/","tag":"the verb","definition":"The action behind the noun; it can take a direct object or appear in the passive.","definitionCN":"名词背后的动作；可带宾语，也可用被动式。"},{"word":"assimilated","ipa":"/əˈsɪmɪleɪtɪd/","tag":"past participle","definition":"Describes a person or group already absorbed, not the process.","definitionCN":"描述已被吸收的个人或群体，而非过程。"},{"word":"assimilative","ipa":"/əˈsɪmɪlətɪv/","tag":"adjective","definition":"Means tending to absorb or make similar; it describes a capacity.","definitionCN":"意为有吸收或同化倾向的；描述一种能力。"},{"word":"dissimilation","ipa":"/ˌdɪsɪmɪˈleɪʃən/","tag":"the opposite","definition":"The reverse process, in which sounds or traits become less alike; the prefix changes the direction.","definitionCN":"相反的过程，语音或特质变得更不相似；前缀改变了方向。"}]},{"heading":"NEAR MEANING","entries":[{"word":"integration","ipa":"/ˌɪntɪˈɡreɪʃən/","tag":"joining a whole","definition":"Entry into a society without necessarily losing one's own culture; assimilation is stronger.","definitionCN":"进入社会但未必失去自身文化；同化的程度更强。"},{"word":"absorption","ipa":"/əˈbzɔːpʃən/","tag":"taking in","definition":"The plain word for one thing taking in another, used of liquids, knowledge and groups.","definitionCN":"指一物吸纳另一物的普通说法，可用于液体、知识与群体。"},{"word":"acculturation","ipa":"/æˌkʌltʃəˈreɪʃən/","tag":"two-way change","definition":"Cultural change through contact that can go both ways; assimilation usually points toward the majority.","definitionCN":"接触引起的文化变化，可是双向的；同化通常指向多数群体。"},{"word":"homogenization","ipa":"/ˌhɒmədʒənaɪˈzeɪʃən/","tag":"making uniform","definition":"The result of many things becoming the same; it stresses sameness rather than absorption.","definitionCN":"指许多事物变得相同的结果，强调相同而非吸收。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real contrasts, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实对比，而非编造的顺口溜。"},"normal":[{"en":"ad- 'toward' plus similis 'like': to move toward being like.","cn":"ad-「向」加 similis「相似」：朝「像」的方向移动。"},{"en":"The family runs assimilate, assimilated, assimilation, assimilative, assimilable, assimilationist.","cn":"同族词包括 assimilate、assimilated、assimilation、assimilative、assimilable、assimilationist。"},{"en":"Fixed phrases: cultural assimilation, assimilation of immigrants, phonetic assimilation.","cn":"固定搭配：文化同化、移民的同化、语音同化。"},{"en":"The same noun serves the stomach, the mind, the mouth and the state.","cn":"同一个名词可用于胃、心智、口舌与国家。"},{"en":"Opposite direction is marked by a different prefix in dissimilation.","cn":"相反方向由 dissimilation 中的另一个前缀标记。"}],"abstract":[{"en":"Picture a lump of sugar disappearing into hot tea.","cn":"想象一块糖消失在热茶里。"},{"en":"Picture a new word being spoken in the accent of its new street.","cn":"想象一个新词用它新所在街道的口音说出。"},{"en":"Picture a map redrawn until the old border is only a faint line.","cn":"想象地图被重画，旧边界只剩一道淡线。"}]},"examples":[{"en":"Assimilation into the village took a generation and cost the family its old language.","cn":"融入这个村庄花了一代人的时间，也让这家人失去了旧语言。"},{"en":"The laboratory measured the assimilation of iron in the digestive tract.","cn":"实验室测量了消化道中铁的吸收。"},{"en":"Linguists describe the assimilation of place of articulation in rapid speech.","cn":"语言学家描述快速语流中发音部位的同化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「朝向」加「相似」加「过程」——朝「变得相似」走的过程","word":"assimilation"},"root":"拉丁 assimilare「使相似」= ad-（向）+ similis（相似），名词 assimilatio；similis 一般认为与 simul「一起」同源，但更早形态属重构。英语 assimilation。","sensesIntro":{"en":"Eight senses follow one move: something outside is made like the inside, whether the inside is a society, a body, a mind, a sound system or a written argument.","cn":"八个义项沿同一个动作展开：把外部之物变得像内部之物，这个「内部」可以是社会、身体、心智、语音系统或一篇论述。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stone dropped into thick soup, losing its outline while its taste spreads through the pot.","cn":"核心意象：一颗石子落进浓汤，外形渐失，味道却散进整锅。"},"chain":["ABSORB","MAKE LIKE","BODY","MIND","SOUND","SOCIETY"],"branches":[{"senses":"01 · 05","en":"SOCIETY AND POLICY: a group may be absorbed by the majority, and the state may demand it.","cn":"社会与政策：群体可能被多数吸收，国家也可能强制要求。"},{"senses":"02","en":"BODY: food becomes tissue, the most concrete form of the process.","cn":"身体：食物变成组织，这是该过程最具体的形式。"},{"senses":"03 · 08","en":"MIND AND TEXT: new experience fits a schema, and an argument can absorb dissent.","cn":"心智与文本：新经验贴合图式，一篇论述也能吸收异议。"},{"senses":"04","en":"SOUND: a speech sound adjusts to its neighbour.","cn":"语音：语音向邻近语音靠拢。"},{"senses":"06 · 07","en":"INSTITUTIONS AND FORCE: entry into schools and parties is different from compulsory absorption.","cn":"制度与强制：进入学校与政党，不同于强迫吸收。"}]},"affixes":{"intro":{"en":"Assimilation can be read from a Latin prefix, the Latin adjective for 'like', and the noun suffix that names a process.","cn":"assimilation 可以按拉丁前缀、表示「相似」的拉丁形容词，以及表示过程的名词后缀逐段读出。"},"latinIntro":{"en":"Latin similis supplies similar, similarity and assimilate; ad- adds direction toward, and the noun suffix names the process.","cn":"拉丁 similis 衍生 similar、similarity 与 assimilate；ad- 增添朝向，名词后缀指过程。"},"items":[{"word":"ad-","structure":"ad- (Latin prefix)","meaning":"to, toward","meaningCN":"向；朝","example":"The prefix aims the action at a target.","exampleCN":"这个前缀把动作指向目标。"},{"word":"similis","structure":"similis, simile (Latin adjective)","meaning":"like, similar","meaningCN":"相似的；相像的","example":"The adjective supplies the goal of the action.","exampleCN":"这个形容词提供动作的目标。"},{"word":"assimilare","structure":"ad- + similis (Latin verb)","meaning":"to make like, absorb","meaningCN":"使相似；吸收","example":"The verb names the act of making one thing like another.","exampleCN":"这个动词指使一物像另一物。"},{"word":"assimilation","structure":"assimilare + -ation (process noun)","meaning":"the process of becoming like or being absorbed","meaningCN":"同化或吸收的过程","example":"Assimilation can be cultural or physical.","exampleCN":"同化可以是文化的，也可以是生理的。"},{"word":"assimilate","structure":"assimilare through French","meaning":"to absorb or make similar","meaningCN":"吸收；使相似","example":"The body assimilates nutrients.","exampleCN":"身体吸收营养。"},{"word":"assimilated","structure":"assimilate + -ed (past participle)","meaning":"already absorbed or made similar","meaningCN":"已被吸收或同化的","example":"An assimilated group speaks the majority language.","exampleCN":"被同化的群体说多数人的语言。"},{"word":"assimilative","structure":"assimilate + -ive (tending to)","meaning":"tending to absorb or make similar","meaningCN":"有吸收或同化倾向的","example":"The process is assimilative by nature.","exampleCN":"这个过程本质上是同化性的。"},{"word":"assimilable","structure":"assimilate + -able (can be)","meaning":"able to be absorbed","meaningCN":"可被吸收的","example":"Some nutrients are more assimilable than others.","exampleCN":"有些营养比其他营养更易吸收。"},{"word":"assimilationist","structure":"assimilation + -ist (advocate)","meaning":"a person who favours assimilation","meaningCN":"主张同化的人","example":"The policy was defended by assimilationists.","exampleCN":"这项政策得到同化论者的辩护。"},{"word":"dissimilation","structure":"dis- (apart) + similis + -ation","meaning":"the reverse process, becoming less alike","meaningCN":"异化；变得不相似","example":"Dissimilation makes neighbouring sounds differ.","exampleCN":"异化使相邻语音变得不同。"}],"derivatives":[{"word":"similar","structure":"similis + -ar (adjective)","meaning":"like, alike","meaningCN":"相似的"},{"word":"similarity","structure":"similar + -ity (state noun)","meaning":"the state of being alike","meaningCN":"相似性"},{"word":"dissimilate","structure":"dis- + assimilare","meaning":"to make unlike; to become less similar","meaningCN":"使不同；异化"}],"latinEntries":[{"word":"similis","structure":"similis, simile (adjective)","meaning":"like, similar","meaningCN":"相似的；相像的"},{"word":"assimilare","structure":"assimilare, assimilavi, assimilatum (verb, first conjugation)","meaning":"to make like, absorb","meaningCN":"使相似；吸收"},{"word":"similitudo","structure":"similitudo, similitudinis (f., third declension)","meaning":"likeness, similarity","meaningCN":"相似；相像"}]}},{"word":"assimilate","ipa_uk":"/əˈsɪmɪleɪt/","ipa_us":"/əˈsɪmɪleɪt/","definition_zh":"吸收；同化；使相似；逐渐融入","definition_en":"to take something in and make it part of a larger whole, or to become like that whole","core_image":"一块冰放进温水，边界一点点消失，最后整杯水都带着它的凉意","scene":"身体把一碗饭变成力气，学生把新公式接进旧知识，新来的邻居慢慢学会本地口音。It took the newcomer a decade to assimilate the local customs and speech.","sceneCN":"这里 assimilate 指「吸收并融入当地习俗与语言」（第 1 个义项：把外部事物纳入自身并使之一致）；句意为这个新来者花了十年才吸收并融入当地的习俗与说话方式。可辨识物件：饭碗、课本、街区门廊、口音示意。","pos":[{"tag":"vt.","zh":"吸收（营养、知识）；使同化；使相似"},{"tag":"vi.","zh":"融入；被同化"}],"collocations":[{"phrase":"assimilate nutrients","zh":"吸收营养"},{"phrase":"assimilate information","zh":"吸收信息"},{"phrase":"assimilate knowledge","zh":"吸收知识"},{"phrase":"assimilate into society","zh":"融入社会"},{"phrase":"assimilate immigrants","zh":"同化移民"},{"phrase":"fully assimilate","zh":"完全融入"}],"forms":[{"label":"三单（he/she/it）","form":"assimilates"},{"label":"过去式","form":"assimilated"},{"label":"过去分词","form":"assimilated"},{"label":"现在分词","form":"assimilating"},{"label":"名词（同化；吸收）","form":"assimilation"},{"label":"形容词（同化的）","form":"assimilative"}],"derivatives":[{"word":"assimilation","pos":"n.","zh":"同化；吸收"},{"word":"assimilated","pos":"adj.","zh":"已被同化的；被吸收的"},{"word":"assimilative","pos":"adj.","zh":"有同化或吸收作用的"},{"word":"assimilable","pos":"adj.","zh":"可被吸收的"},{"word":"assimilationist","pos":"n.","zh":"主张同化者"},{"word":"dissimilate","pos":"v.","zh":"使不同；发生异化"}],"senses":[{"no":"01","title":"Absorb nutrients","titleCN":"吸收营养","definition":"to take food or a substance into the body and convert it into usable material","definitionCN":"把食物或物质纳入身体并转化为可用物质","example":"The body assimilates iron more easily when vitamin C is present.","exampleCN":"有维生素配合时，身体更容易吸收铁。","why":"The oldest concrete sense: the body makes foreign matter into its own substance.","whyCN":"最古老的具体义：身体把外来物质变成自身物质。"},{"no":"02","title":"Absorb and understand information","titleCN":"吸收并理解信息","definition":"to take in ideas or information until they become part of one's understanding","definitionCN":"把观念或信息纳入，使其成为理解的一部分","example":"Students need time to assimilate the new material before the exam.","exampleCN":"学生需要时间在考试前吸收新材料。","why":"The mind repeats the body's work: what is taken in must be broken down and rebuilt as one's own.","whyCN":"心智重复身体的工作：纳入之物必须被拆解并重建为自己所有。"},{"no":"03","title":"Become part of a group or culture","titleCN":"融入群体或文化","definition":"to become absorbed into a community and take on its ways, often used without an object","definitionCN":"被一个社群吸收并接受其生活方式，常不带宾语","example":"Many newcomers assimilate within a generation and keep little of the old tongue.","exampleCN":"许多新来者在一代人之内融入，只留下很少的旧语言。","why":"Here the person is both the thing absorbed and the agent of change, which is why the verb can stand alone.","whyCN":"这里的人既是被吸收之物，也是变化的行为者，因此这个动词可以单独使用。"},{"no":"04","title":"Make one thing like another","titleCN":"使一物相似于另一物","definition":"to make something resemble something else, often with 'to' in formal writing","definitionCN":"使某物与另一物相似，正式文体中常用介词引出比较对象","example":"The reform assimilates local practice to the national model.","exampleCN":"这项改革使本地做法向全国模式靠拢。","why":"This transitive pattern keeps the Latin frame: one thing is made like another, and the direction is explicit.","whyCN":"这个及物结构保留拉丁框架：一物被弄得像另一物，方向明确。"},{"no":"05","title":"Assimilate a speech sound","titleCN":"使语音同化","definition":"to change a sound so that it becomes more like a neighbouring sound","definitionCN":"改变一个语音，使其更接近相邻语音","example":"In rapid speech, speakers assimilate the final nasal to the following consonant.","exampleCN":"在快速语流中，说话人让词尾鼻音向后续辅音同化。","why":"Sounds are the smallest things that can be absorbed: one phoneme borrows a feature from its neighbour.","whyCN":"语音是可以被吸收的最小事物：一个音位从邻居借来一个特征。"},{"no":"06","title":"Absorb into an organization","titleCN":"并入组织或体系","definition":"to merge a smaller unit into a larger structure so that it operates as part of it","definitionCN":"把较小单位并入较大结构，使其作为其中一部分运作","example":"The agency assimilated the smaller office into its own structure.","exampleCN":"该机构把较小的办事处并入自己的架构。","why":"Institutions use the verb for mergers, because a merged unit is expected to adopt the parent's procedures.","whyCN":"机构用这个动词指合并，因为被并入的单位被期望采用母体的程序。"},{"no":"07","title":"Digest an experience","titleCN":"把经验消化为理解","definition":"to process a difficult experience until it can be understood and carried","definitionCN":"处理艰难经历，直到它能被理解并承受","example":"Children assimilate difficult events through play and repeated stories.","exampleCN":"儿童通过游戏与反复讲述来消化艰难事件。","why":"The psychological sense treats experience as food: it must be taken in slowly before it can nourish.","whyCN":"心理义把经验当作食物：必须慢慢纳入，才能滋养人。"},{"no":"08","title":"Absorb a people or territory by force","titleCN":"以强制手段吞并","definition":"to bring a people or region under control and erase its separate identity","definitionCN":"把民族或地区纳入控制并抹去其独立身份","example":"The empire assimilated the border province over several decades.","exampleCN":"这个帝国用几十年时间吞并了边境省份。","why":"Power uses the same word as digestion: to assimilate a people is to consume them as a body consumes food.","whyCN":"权力使用与消化相同的词：同化一个民族，就是像身体消化食物那样吞并它。"}],"etymology":{"intro":{"en":"Assimilate comes from Latin assimilare 'to make like, to absorb', from ad- 'to' and similis 'like'. It entered English through French. Dates are approximate.","cn":"assimilate 来自拉丁 assimilare「使相似、吸收」，由 ad-「向」与 similis「相似」构成，经法语进入英语。年代均为约数。"},"items":[{"era":"LATIN SIMILIS","en":"Similis meant 'like, similar'. It is generally connected with simul 'together', but the pre-Latin shape is reconstructed rather than attested.","cn":"similis 意为「相似的」。一般认为与 simul「一起」同源，但拉丁语之前的形态属重构形式，并无实际书证。"},{"era":"LATIN ASSIMILARE","en":"Ad- 'to, toward' plus similis gave assimilare 'to make like, to liken, to absorb'.","cn":"ad-「向、朝」加 similis 构成 assimilare「使相似、比作、吸收」。"},{"era":"ENGLISH VERB","en":"The verb entered English in the sixteenth century through French, first meaning 'to make similar'.","cn":"这个动词在十六世纪经法语进入英语，最初意为「使相似」。"},{"era":"BODY AND MIND","en":"Physiology applied it to food becoming tissue, and psychology to new experience becoming part of a schema.","cn":"生理学用它指食物变成组织，心理学用它指新经验成为图式的一部分。"},{"era":"SOCIETY AND SPEECH","en":"Modern sociology uses it for newcomers becoming like a host society, and linguistics for neighbouring sounds becoming alike.","cn":"现代社会学用它指新来者变得像主流社会，语言学用它指相邻语音变得相似。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the connection of similis to simul is generally accepted, but the pre-Latin form is reconstructed, and the first date of each technical sense is not fixed.","cn":"来源不确定（更深词源）：similis 与 simul 的联系虽被一般接受，但其拉丁语之前形态属重构形式；各技术义的首见年代无法确定。"}]},"similar":{"note":{"en":"Group one shares the 'like' root; group two holds verbs of taking something in.","cn":"第一组共享「相似」词根；第二组是表示纳入某物的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"assimilation","ipa":"/əˌsɪmɪˈleɪʃən/","tag":"the noun","definition":"The process or result; the verb names the act that produces it.","definitionCN":"指过程或结果；动词指产生它的动作。"},{"word":"assimilated","ipa":"/əˈsɪmɪleɪtɪd/","tag":"past participle","definition":"Describes someone or something already absorbed.","definitionCN":"描述已被吸收的人或物。"},{"word":"assimilative","ipa":"/əˈsɪmɪlətɪv/","tag":"adjective","definition":"Describes the capacity to absorb or make similar.","definitionCN":"描述吸收或同化的能力。"},{"word":"dissimilate","ipa":"/dɪˈsɪmɪleɪt/","tag":"the reverse","definition":"To make unlike or to become less similar; the prefix reverses the direction.","definitionCN":"使不同或变得不相似；前缀反转了方向。"}]},{"heading":"NEAR MEANING","entries":[{"word":"absorb","ipa":"/əˈbzɔːb/","tag":"take in","definition":"The general verb for taking in liquid, heat or knowledge; it does not say the thing is remade.","definitionCN":"指吸收液体、热量或知识的普通动词，不表示纳入之物被改造。"},{"word":"integrate","ipa":"/ˈɪntɪɡreɪt/","tag":"join a whole","definition":"To bring parts into a working whole; it stresses structure more than likeness.","definitionCN":"指把各部分带入一个运作整体，强调结构而非相似。"},{"word":"digest","ipa":"/daɪˈdʒest/","tag":"break down","definition":"To break food or information down into usable form; assimilate stresses the later incorporation.","definitionCN":"指把食物或信息分解为可用形式；assimilate 强调其后的并入。"},{"word":"incorporate","ipa":"/ɪnˈkɔːpəreɪt/","tag":"form one body","definition":"To include something as part of a body or company; it is often organizational.","definitionCN":"指把某物作为身体或公司的一部分纳入，常用于组织语境。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real verb forms, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实动词形式，而非编造的顺口溜。"},"normal":[{"en":"ad- 'toward' plus similis 'like': to move toward likeness.","cn":"ad-「向」加 similis「相似」：朝相似移动。"},{"en":"The verb family runs assimilate, assimilates, assimilated, assimilating, assimilation.","cn":"动词词族包括 assimilate、assimilates、assimilated、assimilating、assimilation。"},{"en":"Fixed phrases: assimilate nutrients, assimilate information, assimilate into society.","cn":"固定搭配：吸收营养、吸收信息、融入社会。"},{"en":"The intransitive use describes people; the transitive use can describe food, facts or sounds.","cn":"不及物用法描述人；及物用法可描述食物、事实或语音。"},{"en":"Spelling note: the prefix ends in a voiced stop, but writing has merged it into the following hissing sound.","cn":"注意双写的咝音：前缀末辅音在书写中已与后面的咝音合并。"}],"abstract":[{"en":"Picture a cube of ice losing its edge in warm water.","cn":"想象一块冰在温水里失去棱角。"},{"en":"Picture a new song becoming hummable in a foreign key.","cn":"想象一首新歌在异国调子里变得随口可哼。"},{"en":"Picture a river carrying silt until the silt is simply part of the water.","cn":"想象河流携着泥沙，直到泥沙干脆成为水的一部分。"}]},"examples":[{"en":"It takes years to assimilate a second language well enough to joke in it.","cn":"要把第二语言吸收到能开玩笑的程度，需要多年。"},{"en":"The body cannot assimilate the mineral without enough fat in the diet.","cn":"饮食中脂肪不足时，身体无法吸收这种矿物质。"},{"en":"The new department was assimilated into the older one within a year.","cn":"新部门在一年内被并入较老的部门。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「朝向」加「相似」加「使……」——使外来的东西变得像自己","word":"assimilate"},"root":"拉丁 assimilare「使相似、吸收」= ad-（向）+ similis（相似），经法语进入英语。similis 一般认为与 simul「一起」同源，更早形态属重构。","sensesIntro":{"en":"Eight senses follow one intake: something outside is brought in and made to fit, whether it is food, information, a person, a sound, an office, an experience or a conquered people.","cn":"八个义项沿同一次纳入展开：外部之物被带进来并被弄得合身，它可以是食物、信息、人、语音、机构、经历或被征服的民族。"},"semanticMap":{"core":{"en":"CORE IMAGE: a piece of ice dissolving in warm water until the whole glass carries its coolness.","cn":"核心意象：一块冰在温水中消融，直到整杯水都带着它的凉意。"},"chain":["TAKE IN","MAKE LIKE","FOOD","KNOWLEDGE","GROUP","SYSTEM"],"branches":[{"senses":"01","en":"FOOD FIRST: the body turns foreign matter into tissue.","cn":"食物在先：身体把外来物质变成组织。"},{"senses":"02 · 07","en":"MIND: information and painful experience must be broken down before they become one's own.","cn":"心智：信息与痛苦经历必须先被拆解，才能成为自己所有。"},{"senses":"03","en":"PERSON AND GROUP: a newcomer becomes like the host without losing the ability to act.","cn":"人与群体：新来者变得像主流，却不失行动能力。"},{"senses":"04 · 05","en":"LIKENESS AND SOUND: one thing is made like another, down to a single phoneme.","cn":"相似与语音：一物被弄得像另一物，小到一个音位。"},{"senses":"06 · 08","en":"POWER: an office is merged, and a people can be swallowed by an empire.","cn":"权力：机构被合并，民族也能被帝国吞并。"}]},"affixes":{"intro":{"en":"Assimilate is a Latin verb of direction plus likeness, with a family of English nouns, adjectives and a reversed form.","cn":"assimilate 是一个由方向前缀与「相似」构成的拉丁动词，并有一族英语名词、形容词与一个反向形式。"},"latinIntro":{"en":"Latin similis supplies similar and similarity; ad- turns the adjective into a verb of making, and dis- reverses it.","cn":"拉丁 similis 衍生 similar 与 similarity；ad- 把这个形容词变成「使……」的动词，dis- 则反转方向。"},"items":[{"word":"ad-","structure":"ad- (Latin prefix)","meaning":"to, toward","meaningCN":"向；朝","example":"The prefix aims the action at a target.","exampleCN":"这个前缀把动作指向目标。"},{"word":"similis","structure":"similis, simile (Latin adjective)","meaning":"like, similar","meaningCN":"相似的；相像的","example":"The adjective supplies the goal.","exampleCN":"这个形容词提供目标。"},{"word":"assimilare","structure":"ad- + similis (Latin verb)","meaning":"to make like, absorb","meaningCN":"使相似；吸收","example":"The verb names the act of making one thing like another.","exampleCN":"这个动词指使一物像另一物。"},{"word":"assimilate","structure":"assimilare through French","meaning":"to absorb or make similar","meaningCN":"吸收；使相似","example":"The body assimilates nutrients.","exampleCN":"身体吸收营养。"},{"word":"assimilation","structure":"assimilate + -ation (process noun)","meaning":"the process of being absorbed","meaningCN":"被吸收或同化的过程","example":"Assimilation can be cultural or physical.","exampleCN":"同化可以是文化的，也可以是生理的。"},{"word":"assimilated","structure":"assimilate + -ed (past participle)","meaning":"already absorbed","meaningCN":"已被吸收的","example":"An assimilated group speaks the majority language.","exampleCN":"被同化的群体说多数人的语言。"},{"word":"assimilative","structure":"assimilate + -ive (tending to)","meaning":"tending to absorb","meaningCN":"有吸收倾向的","example":"The process is assimilative.","exampleCN":"这个过程具有吸收性。"},{"word":"assimilable","structure":"assimilate + -able (can be)","meaning":"able to be absorbed","meaningCN":"可被吸收的","example":"Some nutrients are more assimilable.","exampleCN":"有些营养更易吸收。"},{"word":"dissimilate","structure":"dis- (apart) + similare","meaning":"to make unlike","meaningCN":"使不同；异化","example":"Dissimilation separates neighbouring sounds.","exampleCN":"异化使相邻语音分开。"},{"word":"similar","structure":"similis + -ar (adjective)","meaning":"alike","meaningCN":"相似的","example":"The two cases are similar.","exampleCN":"这两个案例相似。"}],"derivatives":[{"word":"assimilation","structure":"assimilate + -ation (noun)","meaning":"the process of becoming part of a whole","meaningCN":"同化；吸收"},{"word":"assimilated","structure":"assimilate + -ed (participle)","meaning":"absorbed into a larger whole","meaningCN":"已被同化的"},{"word":"dissimilation","structure":"dis- + assimilation","meaning":"the reverse process","meaningCN":"异化"}],"latinEntries":[{"word":"similis","structure":"similis, simile (adjective)","meaning":"like, similar","meaningCN":"相似的"},{"word":"assimilare","structure":"assimilare, assimilavi, assimilatum (verb, first conjugation)","meaning":"to make like, absorb","meaningCN":"使相似；吸收"},{"word":"similitudo","structure":"similitudo, similitudinis (f., third declension)","meaning":"likeness","meaningCN":"相似；相像"}]}},{"word":"acculturation","ipa_uk":"/æˌkʌltʃəˈreɪʃən/","ipa_us":"/æˌkʌltʃəˈreɪʃən/","definition_zh":"文化涵化；文化接触引起的文化变迁；个体习得第二文化的过程","definition_en":"the cultural change that follows contact between groups, or the process of acquiring a second culture","core_image":"两张餐桌并在一起，一边摆着旧家的碗碟，一边摆着新家的面包，吃饭的人两样都用手拿","scene":"两种饮食习惯在同一张餐桌上混在一起，节日既保留旧仪式也加入新做法。The mixture of foods and festivals shows a long process of acculturation between the two communities.","sceneCN":"这里 acculturation 指「两个群体长期接触后发生的文化变迁」（第 1 个义项：接触引起的文化变化过程）；句意为饮食与节日的混合显示两个社群经历了长期的涵化。可辨识物件：拼在一起的餐桌、碗碟、面包、节庆装饰。","pos":[{"tag":"n.","zh":"文化涵化（人类学术语，常作不可数）"},{"tag":"n.","zh":"个体习得第二文化的过程（心理学术语）"}],"collocations":[{"phrase":"acculturation process","zh":"涵化过程"},{"phrase":"acculturation strategies","zh":"涵化策略"},{"phrase":"acculturation stress","zh":"涵化压力"},{"phrase":"the acculturation of migrants","zh":"移民的涵化"},{"phrase":"acculturation and assimilation","zh":"涵化与同化"},{"phrase":"generational acculturation","zh":"代际涵化"}],"forms":[{"label":"不可数用法（整体过程）","form":"acculturation"},{"label":"可数复数（具体过程）","form":"acculturations"},{"label":"动词（发生涵化；使涵化）","form":"acculturate"},{"label":"形容词（涵化的）","form":"acculturative"},{"label":"过去分词（已涵化的）","form":"acculturated"}],"derivatives":[{"word":"acculturate","pos":"v.","zh":"发生涵化；使接受另一种文化"},{"word":"acculturated","pos":"adj.","zh":"已涵化的；已习得第二文化的"},{"word":"acculturative","pos":"adj.","zh":"涵化引起的"},{"word":"acculturationist","pos":"n.","zh":"研究或主张涵化者"},{"word":"cultural","pos":"adj.","zh":"文化的"},{"word":"culture","pos":"n.","zh":"文化"}],"senses":[{"no":"01","title":"Cultural change through contact","titleCN":"接触引起的文化变迁","definition":"the change in customs, values and institutions that follows prolonged contact between groups","definitionCN":"群体长期接触后风俗、价值与制度发生的变化","example":"Prolonged trade contact produced acculturation on both sides of the frontier.","exampleCN":"长期的贸易接触在边境两侧都造成了涵化。","why":"The word adds a Latin prefix meaning 'toward' to culture, so it names movement toward another culture rather than simple borrowing.","whyCN":"这个词在 culture 前加了表示「朝向」的拉丁前缀，因此指朝另一种文化移动，而非简单借用。"},{"no":"02","title":"Acquiring a second culture","titleCN":"习得第二文化","definition":"the psychological process by which a person learns and adopts a new culture","definitionCN":"个人学习并接受一种新文化的心理过程","example":"The acculturation of new employees begins with small rituals, not formal training.","exampleCN":"新员工的涵化从小仪式开始，而非正式培训。","why":"Psychology narrowed the group process to the individual learner, for whom a second culture is acquired step by step.","whyCN":"心理学把群体过程收窄到个体学习者身上：第二文化是一步步习得的。"},{"no":"03","title":"Acculturation strategies","titleCN":"涵化策略","definition":"the patterned ways people combine keeping their own culture with adopting a new one","definitionCN":"人们在保留自身文化与接受新文化之间的几种固定组合方式","example":"Berry's model describes four acculturation strategies among migrants.","exampleCN":"贝里的模型描述了移民的四种涵化策略。","why":"Once contact is continuous, people make choices; the term then names those choices rather than the contact itself.","whyCN":"一旦接触持续，人们就会作出选择；这个词随后指这些选择，而非接触本身。"},{"no":"04","title":"Material culture acquisition","titleCN":"物质文化的习得","definition":"the adoption of clothing, food, tools and household practices from another culture","definitionCN":"从另一文化接受衣着、饮食、工具与居家做法","example":"Acculturation showed first in clothing and kitchen tools.","exampleCN":"涵化最先表现在衣着与厨房用具上。","why":"Things change before beliefs because objects can be picked up without translation.","whyCN":"物件先于信念改变，因为东西可以不经翻译就被拿起。"},{"no":"05","title":"Language shift and acquisition","titleCN":"语言的转用与习得","definition":"the adoption of a new language, often at the cost of the first","definitionCN":"接受新语言，常以第一语言为代价","example":"Language shift is often the clearest measure of acculturation.","exampleCN":"语言转用常是涵化最清晰的衡量标准。","why":"Language is the deepest layer of culture that can be exchanged, so shift marks how far the process has gone.","whyCN":"语言是可以交换的最深文化层，因此转用标志着这个过程走了多远。"},{"no":"06","title":"Two-way acculturation","titleCN":"双向涵化","definition":"change that runs in both directions, affecting the host group as well as the newcomers","definitionCN":"双向变化，既影响新来者，也影响主流群体","example":"Mission schools brought acculturation that also changed the missionaries.","exampleCN":"教会学校带来的涵化也改变了传教士自己。","why":"Unlike assimilation, acculturation does not assume one side stays unchanged; the contact can alter both.","whyCN":"与同化不同，涵化不假定一方保持不变；接触可以改变双方。"},{"no":"07","title":"Generational acculturation","titleCN":"代际涵化","definition":"the different pace and shape of change across first and later generations","definitionCN":"第一代与后代在变化速度与形态上的差异","example":"The second generation's acculturation produced a hybrid music style.","exampleCN":"第二代人的涵化产生了一种混合音乐风格。","why":"Children usually move faster than parents, so the process is read across generations rather than within one life.","whyCN":"孩子通常比父母走得快，因此这个过程要跨代阅读，而非只看一生。"},{"no":"08","title":"Acculturative stress","titleCN":"涵化压力","definition":"the strain that arises when home and host expectations conflict","definitionCN":"当家乡与新地方的期待冲突时产生的紧张","example":"Acculturation can bring stress when home and host expectations clash.","exampleCN":"当家乡与新地方的期待冲突时，涵化会带来压力。","why":"The cost side of the process: change is not only gain but also loss, confusion and pressure.","whyCN":"这个过程的代价面：变化不只是获得，也是失去、困惑与压力。"}],"etymology":{"intro":{"en":"Acculturation joins ad- 'toward' with cultura 'tilling, cultivation'. It was coined in English anthropology in the late nineteenth century, generally attributed to John Wesley Powell in 1880. Dates are approximate.","cn":"acculturation 由 ad-「朝向」与 cultura「耕作、培养」构成。它于十九世纪后期在英语人类学中被造出，一般认为是约翰·韦斯利·鲍威尔在一八八零年使用。年代均为约数。"},"items":[{"era":"LATIN CULTURA","en":"Cultura came from colere 'to till, cultivate, inhabit, worship'; it first named farming and later the tending of the mind.","cn":"cultura 来自 colere「耕作、培养、居住、敬奉」；先指农耕，后指心智的培养。"},{"era":"LATIN AD-","en":"The prefix ad- meant 'to, toward' and gave the new noun a direction: movement toward another culture.","cn":"前缀 ad- 意为「向、朝」，给这个新名词一个方向：朝另一种文化移动。"},{"era":"ANTHROPOLOGICAL COINAGE","en":"The noun is generally attributed to John Wesley Powell in 1880, when American anthropology needed a term for cultural change under contact.","cn":"这个名词一般被认为由约翰·韦斯利·鲍威尔在一八八零年使用，当时美国人类学需要一个词来描述接触下的文化变化。"},{"era":"PSYCHOLOGY","en":"Twentieth-century psychology applied the word to individuals learning a second culture, and later to the strategies they choose.","cn":"二十世纪心理学把这个词用于学习第二文化的个人，后又用于他们所选择的策略。"},{"era":"MODERN RESEARCH","en":"Migration research now measures acculturation through language, dress, food and social networks, and pairs it with stress.","cn":"移民研究如今通过语言、衣着、饮食与社会网络衡量涵化，并将其与压力联系起来。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the exact first publication is not fixed beyond the general attribution to Powell, and the pre-Latin origin of colere is reconstructed rather than attested.","cn":"来源不确定（首见年代）：除一般归于鲍威尔之外，确切的首见出版物无法确定；colere 在拉丁语之前的来源属重构形式，并无实际书证。"}]},"similar":{"note":{"en":"Group one shares the culture stem; group two holds terms for change under contact, and the differences matter.","cn":"第一组共享 culture 词干；第二组是接触下变化的相关术语，彼此差异很重要。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"acculturate","ipa":"/əˈkʌltʃəreɪt/","tag":"the verb","definition":"To undergo or bring about acculturation; the noun names the process.","definitionCN":"指经历或促成涵化；名词指过程。"},{"word":"acculturated","ipa":"/əˈkʌltʃəreɪtɪd/","tag":"past participle","definition":"Describes a person or group already changed by contact.","definitionCN":"描述已被接触改变的个人或群体。"},{"word":"acculturative","ipa":"/əˈkʌltʃərətɪv/","tag":"adjective","definition":"Relates to the stress or change caused by acculturation.","definitionCN":"与涵化造成的压力或变化有关。"},{"word":"cultural","ipa":"/ˈkʌltʃərəl/","tag":"the adjective","definition":"Simply relates to culture; it does not name a process of change.","definitionCN":"只表示与文化相关，不指变化过程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"assimilation","ipa":"/əˌsɪmɪˈleɪʃən/","tag":"one-way absorption","definition":"Usually points toward absorption into the majority and loss of the old culture; acculturation can be two-way.","definitionCN":"通常指向被多数吸收并失去旧文化；涵化可以双向。"},{"word":"enculturation","ipa":"/ˌenkʌltʃəˈreɪʃən/","tag":"learning one's own","definition":"The learning of the culture one is born into, with no cross-group contact.","definitionCN":"指习得自己出生其中的文化，不涉及跨群体接触。"},{"word":"adaptation","ipa":"/ˌædæpˈteɪʃən/","tag":"adjusting to a setting","definition":"A practical adjustment to a new environment; it need not involve cultural identity.","definitionCN":"指对新环境的实际调整，不必涉及文化身份。"},{"word":"hybridization","ipa":"/ˌhaɪbrɪdaɪˈzeɪʃən/","tag":"mixing forms","definition":"The blending of cultural forms into something new, one possible outcome of acculturation.","definitionCN":"指文化形式混合成新东西，是涵化的一种可能结果。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real distinctions, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实区分，而非编造的顺口溜。"},"normal":[{"en":"ad- 'toward' plus cultura: movement toward another culture.","cn":"ad-「朝向」加 cultura：朝另一种文化移动。"},{"en":"The family runs acculturate, acculturated, acculturation, acculturative.","cn":"同族词包括 acculturate、acculturated、acculturation、acculturative。"},{"en":"Fixed phrases: acculturation process, acculturation strategies, acculturation stress.","cn":"固定搭配：涵化过程、涵化策略、涵化压力。"},{"en":"Remember the difference: acculturation can be two-way; assimilation usually is not.","cn":"记住区别：涵化可以双向，同化通常不是。"},{"en":"The word is standard in anthropology and migration studies, less common in daily speech.","cn":"这个词是人类学与移民研究的标准术语，日常口语较少用。"}],"abstract":[{"en":"Picture two kitchens slowly borrowing each other's pots.","cn":"想象两间厨房慢慢借用彼此的锅。"},{"en":"Picture a festival keeping its old date but gaining a new dish.","cn":"想象一个节日保留旧日期，却添了一道新菜。"},{"en":"Picture a child translating for a parent and correcting the parent's accent.","cn":"想象孩子替父母翻译，还纠正父母的口音。"}]},"examples":[{"en":"Acculturation rarely leaves either group exactly as it was.","cn":"涵化很少让任何一方保持原样。"},{"en":"The study measured acculturation through language use at home.","cn":"这项研究通过家庭语言使用来衡量涵化。"},{"en":"Acculturation stress was highest among those who felt loyal to both worlds.","cn":"在同时忠于两个世界的人当中，涵化压力最高。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「朝向」加「文化」加「过程」——朝另一种文化走的过程，但不一定丢掉自己的","word":"acculturation"},"root":"acculturation = ad-（朝向）+ cultura（耕作、培养），十九世纪后期英语人类学造词，一般认为始用于鲍威尔；cultura 源于 colere「耕作、培养、敬奉」。","sensesIntro":{"en":"Eight senses follow one contact: two cultures meet, and change spreads through objects, language, choices, generations and finally stress, without assuming that either side stays intact.","cn":"八个义项沿同一次接触展开：两种文化相遇，变化经由物件、语言、选择、代际，最后是压力扩散开来，且不假定任何一方保持原样。"},"semanticMap":{"core":{"en":"CORE IMAGE: two tables pushed together, with old bowls on one side and new bread on the other.","cn":"核心意象：两张桌子并在一起，一边是旧家的碗，一边是新家的面包。"},"chain":["CONTACT","CHANGE","TWO-WAY","STRATEGY","GENERATIONS","STRESS"],"branches":[{"senses":"01 · 06","en":"CONTACT AND RETURN: change begins in contact and can flow back to the host group.","cn":"接触与回流：变化始于接触，也可能回流到主流群体。"},{"senses":"02","en":"THE PERSON: an individual learns a second culture step by step.","cn":"个人：个体一步步习得第二文化。"},{"senses":"03","en":"CHOICES: people combine old and new in patterned strategies.","cn":"选择：人们以有规律的方式组合新旧。"},{"senses":"04 · 05","en":"OBJECTS AND WORDS: dress and food move first, language goes deepest.","cn":"物件与词语：衣着与饮食先行，语言走得最深。"},{"senses":"07 · 08","en":"TIME AND COST: generations move at different speeds, and the process can hurt.","cn":"时间与代价：各代速度不同，这个过程也会带来痛苦。"}]},"affixes":{"intro":{"en":"Acculturation can be read from a Latin prefix of direction, a Latin noun for cultivation, and an English process suffix.","cn":"acculturation 可以按表示方向的拉丁前缀、表示耕作的拉丁名词，以及英语过程后缀逐段读出。"},"latinIntro":{"en":"Latin cultura supplies culture and cultural; ad- adds direction, and the noun suffix names a process. The word also exists in the verb acculturate.","cn":"拉丁 cultura 衍生 culture 与 cultural；ad- 增添方向，名词后缀指过程。这个词也有动词形式 acculturate。"},"items":[{"word":"ad-","structure":"ad- (Latin prefix)","meaning":"to, toward","meaningCN":"向；朝","example":"The prefix gives the direction of change.","exampleCN":"这个前缀给出变化的方向。"},{"word":"colere","structure":"colere, colui, cultum (Latin verb)","meaning":"to till, cultivate, worship","meaningCN":"耕作；培养；敬奉","example":"The verb supplies the farming image.","exampleCN":"这个动词提供农耕意象。"},{"word":"cultura","structure":"cultura, culturae (Latin noun)","meaning":"tilling; cultivation; care","meaningCN":"耕作；培养；照料","example":"Cultura first named the field.","exampleCN":"cultura 先指田地。"},{"word":"culture","structure":"cultura through Old French","meaning":"the way of life of a people","meaningCN":"一个民族的生活方式","example":"Culture can be borrowed and changed.","exampleCN":"文化可以被借用并改变。"},{"word":"cultural","structure":"cultura + -al (relating to)","meaning":"relating to culture","meaningCN":"与文化相关的","example":"Cultural contact drives the process.","exampleCN":"文化接触推动这个过程。"},{"word":"acculturate","structure":"ad- + culture + -ate (verb)","meaning":"to undergo or cause acculturation","meaningCN":"发生涵化；使接受新文化","example":"Migrants acculturate at different speeds.","exampleCN":"移民以不同速度发生涵化。"},{"word":"acculturation","structure":"acculturate + -ation (process noun)","meaning":"the process of cultural change through contact","meaningCN":"接触引起文化变迁的过程","example":"Acculturation reshaped both communities.","exampleCN":"涵化重塑了两个社群。"},{"word":"acculturated","structure":"acculturate + -ed (past participle)","meaning":"already changed by contact","meaningCN":"已被接触改变的","example":"An acculturated family keeps both languages.","exampleCN":"一个已涵化的家庭保留两种语言。"},{"word":"acculturative","structure":"acculturate + -ive (tending to)","meaning":"relating to the change or its stress","meaningCN":"与涵化变化或压力相关的","example":"Acculturative stress rises with conflict.","exampleCN":"涵化压力随冲突上升。"},{"word":"acculturationist","structure":"acculturation + -ist (person)","meaning":"a scholar or advocate of acculturation","meaningCN":"研究或主张涵化者","example":"Acculturationists compare migrant generations.","exampleCN":"涵化研究者比较移民的各代。"}],"derivatives":[{"word":"acculturate","structure":"ad- + culture + -ate (verb)","meaning":"to undergo cultural change through contact","meaningCN":"经接触发生文化变化"},{"word":"acculturated","structure":"acculturate + -ed (participle)","meaning":"changed by contact with another culture","meaningCN":"因接触另一文化而改变的"},{"word":"acculturative","structure":"acculturate + -ive (adjective)","meaning":"causing or relating to acculturation","meaningCN":"引起涵化的；涵化性的"}],"latinEntries":[{"word":"cultura","structure":"cultura, culturae (f., first declension)","meaning":"tilling; cultivation; care","meaningCN":"耕作；培养；照料"},{"word":"colere","structure":"colere, colui, cultum (verb, third conjugation)","meaning":"to till, cultivate, worship","meaningCN":"耕作；培养；敬奉"},{"word":"cultus","structure":"cultus, cultus (m., fourth declension)","meaning":"tending; cultivation; worship","meaningCN":"照料；培养；敬奉"}]}},{"word":"cultural exchange","ipa_uk":"/ˌkʌltʃərəl ɪksˈtʃeɪndʒ/","ipa_us":"/ˌkʌltʃərəl ɪksˈtʃeɪndʒ/","definition_zh":"文化交流；不同文化之间双向的人员、艺术、观念与习俗往来","definition_en":"the two-way movement of people, arts, ideas or customs between different cultures","core_image":"两只箱子在机场互换：一只装着乐器与画册，一只装着家常菜谱与旧照片，到达后各自被打开","scene":"合唱团带着本地的歌去远方演出，又把对方的歌带回来教给学生。The choir tour became a genuine cultural exchange, with songs travelling in both directions.","sceneCN":"这里 cultural exchange 指「不同文化之间双向的艺术与人员往来」（第 1 个义项：双向的文化交流）；句意为这次合唱巡演成了真正的文化交流，歌曲朝两个方向流动。可辨识物件：合唱团、乐谱、行李箱、舞台、学生。","pos":[{"tag":"n.","zh":"文化交流（常作不可数）"},{"tag":"n.","zh":"一次具体的文化交流活动（可数）"}],"collocations":[{"phrase":"cultural exchange programme","zh":"文化交流项目"},{"phrase":"cultural exchange between countries","zh":"国家间的文化交流"},{"phrase":"promote cultural exchange","zh":"促进文化交流"},{"phrase":"student cultural exchange","zh":"学生文化交流"},{"phrase":"a cultural exchange visit","zh":"文化交流访问"},{"phrase":"cultural exchange and understanding","zh":"文化交流与理解"}],"forms":[{"label":"不可数用法（整体活动）","form":"cultural exchange"},{"label":"可数复数（具体活动）","form":"cultural exchanges"},{"label":"形容词（文化的）","form":"cultural"},{"label":"名词（交流；交换）","form":"exchange"},{"label":"动词（交流；交换）","form":"exchange"}],"derivatives":[{"word":"exchange","pos":"n./v.","zh":"交流；交换"},{"word":"exchangeable","pos":"adj.","zh":"可交换的"},{"word":"interchange","pos":"n./v.","zh":"互换；交换"},{"word":"cultural","pos":"adj.","zh":"文化的"},{"word":"culture","pos":"n.","zh":"文化"},{"word":"culturally","pos":"adv.","zh":"在文化上"}],"senses":[{"no":"01","title":"Two-way cultural traffic","titleCN":"双向的文化往来","definition":"the movement of cultural goods, people or practices in both directions","definitionCN":"文化产品、人员或做法朝两个方向流动","example":"The choir tour became a genuine cultural exchange, with songs travelling in both directions.","exampleCN":"这次合唱巡演成了真正的文化交流，歌曲朝两个方向流动。","why":"Exchange contains the idea of giving and receiving back; the phrase insists that culture moves both ways.","whyCN":"exchange 本身含有给出与收回的意思；这个短语坚持文化朝两个方向移动。"},{"no":"02","title":"People exchange","titleCN":"人员往来","definition":"the sending and receiving of students, artists, athletes or scholars","definitionCN":"互派与接待学生、艺术家、运动员或学者","example":"The two universities run a cultural exchange for art students each summer.","exampleCN":"两所大学每年夏天为艺术类学生举办文化交流。","why":"People carry culture in their bodies and habits, so a visit can transmit more than any document.","whyCN":"人把文化带在身体与习惯里，因此一次访问能传递比文件更多的东西。"},{"no":"03","title":"Arts and performance","titleCN":"艺术与演出交流","definition":"the touring of exhibitions, concerts, theatre and dance between cultures","definitionCN":"展览、音乐会、戏剧与舞蹈在不同文化间巡演","example":"The museum's cultural exchange brought a masked dance troupe from the coast.","exampleCN":"博物馆的文化交流请来了海岸的假面舞团。","why":"Performance is the most visible form: an audience can meet another culture in one evening.","whyCN":"演出是最可见的形式：观众能在一个晚上遇见另一种文化。"},{"no":"04","title":"Ideas and knowledge","titleCN":"观念与知识交流","definition":"the sharing of scholarly, religious or political ideas across cultures","definitionCN":"学术、宗教或政治观念在不同文化间共享","example":"The translation project was a cultural exchange in the form of books.","exampleCN":"这个翻译项目是以书籍形式进行的文化交流。","why":"Books and lectures travel farther than bodies, so ideas are exchanged even when people stay home.","whyCN":"书与讲座比人走得更远，因此即使人不出门，观念也在交换。"},{"no":"05","title":"Language exchange","titleCN":"语言交流","definition":"the mutual teaching and learning of languages between speakers","definitionCN":"说话者之间互相教授与学习语言","example":"The evening language tables are a small cultural exchange held every week.","exampleCN":"每周的语言角是一场小型的文化交流。","why":"Language exchange is the clearest two-way form: each side teaches and each side learns.","whyCN":"语言交流是最清晰的双向形式：每一方都教，也都学。"},{"no":"06","title":"Organized programmes","titleCN":"机构组织的交流项目","definition":"official or institutional schemes that arrange visits and partnerships","definitionCN":"官方或机构安排访问与合作的计划","example":"The ministry funded a cultural exchange to send young musicians abroad.","exampleCN":"该部资助了一项文化交流，把年轻音乐家送到国外。","why":"Institutions formalize the flow, which makes the phrase common in policy and school documents.","whyCN":"机构把流动制度化，因此这个短语常出现在政策与学校文件中。"},{"no":"07","title":"Everyday informal exchange","titleCN":"日常非正式交流","definition":"ordinary borrowing of food, customs and household habits between neighbours","definitionCN":"邻里之间对饮食、习俗与居家习惯的日常借用","example":"Neighbourhood cooking classes turned into a quiet cultural exchange.","exampleCN":"社区烹饪课变成了一场安静的文化交流。","why":"The phrase need not be official; a shared meal can exchange culture without any programme.","whyCN":"这个短语不必官方；一顿共餐就能在没有项目的情况下交流文化。"},{"no":"08","title":"Equal reciprocity as a principle","titleCN":"平等互惠的原则","definition":"a principle that cultures should meet as equals rather than one exporting to the other","definitionCN":"各文化应平等相遇，而非一方单向输出给另一方","example":"Critics ask whether the festival is a cultural exchange or a one-way advertisement.","exampleCN":"批评者追问这个节日是文化交流还是单向宣传。","why":"The abstract sense turns the phrase into a standard: real exchange requires both sides to give and to receive.","whyCN":"抽象义把这个短语变成一项标准：真正的交流要求双方都给出，也都接受。"}],"etymology":{"intro":{"en":"Cultural exchange joins cultural, from Latin cultura 'tilling, cultivation', and exchange, from Old French eschange and Vulgar Latin excambiare 'to barter'. The origin of the underlying verb cambire is uncertain, possibly Gaulish. Dates are approximate.","cn":"cultural exchange 由 cultural 与 exchange 合成：cultural 来自拉丁 cultura「耕作、培养」；exchange 经古法语 eschange 与俗拉丁 excambiare「以物易物」而来。底层动词 cambire 的来源不确定，可能来自高卢语。年代均为约数。"},"items":[{"era":"LATIN CULTURA","en":"Cultura came from colere 'to till, cultivate, worship'; it first named farming and later the tending of the mind.","cn":"cultura 来自 colere「耕作、培养、敬奉」；先指农耕，后指心智的培养。"},{"era":"LATIN CAMBIRE","en":"Cambire meant 'to exchange, barter'. Its deeper origin is uncertain and is sometimes said to be Gaulish, but that attribution is not established.","cn":"cambire 意为「交换、以物易物」。其更深来源不确定，有时被认为来自高卢语，但这一说法未得到证实。"},{"era":"VULGAR LATIN EXCAMBIARE","en":"The prefix ex- 'out' plus cambire produced a verb of trading one thing for another, which passed into Old French as eschangier.","cn":"前缀 ex-「出」加 cambire 构成「以一物换另一物」的动词，进入古法语作 eschangier。"},{"era":"ENGLISH EXCHANGE","en":"English exchange appeared in the fourteenth century, naming the act of giving one thing and receiving another.","cn":"英语 exchange 在十四世纪出现，指给出一样并收到另一样的动作。"},{"era":"MODERN PHRASE","en":"The phrase cultural exchange spread in the twentieth century with student programmes, touring companies and international organisations.","cn":"cultural exchange 在二十世纪随学生项目、巡演团体与国际组织而流行。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the first use of the exact phrase is not fixed, and the origin of cambire is unsettled, so any earlier form is a reconstruction.","cn":"来源不确定（首见年代与更深词源）：这个确切短语的最早使用无法确定；cambire 的来源亦无定论，凡更早形态均属重构形式。"}]},"similar":{"note":{"en":"Group one shares the exchange stem; group two holds related terms for cultures meeting.","cn":"第一组共享 exchange 词干；第二组是描述文化相遇的相关术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"exchange","ipa":"/ɪksˈtʃeɪndʒ/","tag":"the base noun and verb","definition":"The bare word can cover trade or conversation; the phrase limits it to culture.","definitionCN":"这个词本身可指贸易或交谈；短语把它限定到文化。"},{"word":"interchange","ipa":"/ˌɪntəˈtʃeɪndʒ/","tag":"swap between sides","definition":"Stresses mutual swapping, often of positions or ideas rather than cultures.","definitionCN":"强调双方互换，常指位置或观念而非文化。"},{"word":"exchangeable","ipa":"/ɪksˈtʃeɪndʒəbəl/","tag":"can be swapped","definition":"Describes something that can be traded, not a relationship between cultures.","definitionCN":"描述可被交换之物，而非文化间的关系。"},{"word":"cultural","ipa":"/ˈkʌltʃərəl/","tag":"the adjective","definition":"Relates to culture; it marks the field of the exchange.","definitionCN":"与文化相关，标记交流的领域。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cultural diffusion","ipa":"/ˌkʌltʃərəl dɪˈfjuːʒən/","tag":"unplanned spread","definition":"The unplanned spread of traits; exchange usually implies deliberate partners.","definitionCN":"指文化特质未经计划的传播；交流通常暗示有意的双方。"},{"word":"dialogue of cultures","ipa":"/ˈdaɪəlɒɡ əv ˈkʌltʃəz/","tag":"conversation","definition":"A phrase stressing mutual listening rather than the movement of goods or people.","definitionCN":"强调相互倾听，而非货物或人员的移动。"},{"word":"cooperation","ipa":"/kəʊˌɒpəˈreɪʃən/","tag":"working together","definition":"Joint work on a task; it may be cultural but need not involve exchange.","definitionCN":"指在任务上合作；可以是文化性的，但不必涉及交流。"},{"word":"borrowing","ipa":"/ˈbɒrəʊɪŋ/","tag":"one-way taking","definition":"The adoption of a trait by one side, which is not necessarily reciprocal.","definitionCN":"指一方采纳某种特质，未必是互惠的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real distinctions, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实区分，而非编造的顺口溜。"},"normal":[{"en":"Exchange means give and receive, so the phrase rules out a one-way export.","cn":"exchange 意为给出与收到，因此这个短语排除了单向输出。"},{"en":"The family runs culture, cultural, culturally, exchange, exchangeable.","cn":"同族词包括 culture、cultural、culturally、exchange、exchangeable。"},{"en":"Fixed phrases: cultural exchange programme, promote cultural exchange, student cultural exchange.","cn":"固定搭配：文化交流项目、促进文化交流、学生文化交流。"},{"en":"The phrase is common in schools, museums and foreign ministries.","cn":"这个短语常见于学校、博物馆与外交部门。"},{"en":"Keep exchange as a noun here: the programme is the exchange, not the exchanged.","cn":"这里 exchange 作名词：项目本身就是交流，而非被交换之物。"}],"abstract":[{"en":"Picture two suitcases crossing in mid-air, each carrying the other's songs.","cn":"想象两只行李箱在半空交错，各带着对方的歌。"},{"en":"Picture a stage where the visiting choir learns the host's chorus.","cn":"想象一个舞台，来访合唱团学会了东道主的合唱曲。"},{"en":"Picture two cooks trading recipes and both changing the dish.","cn":"想象两位厨师交换菜谱，两边的菜都变了。"}]},"examples":[{"en":"The town twinning began as a cultural exchange and ended as a trade partnership.","cn":"这对姊妹城市起初是文化交流，后来成了贸易伙伴。"},{"en":"A cultural exchange needs hosts as well as visitors to be real.","cn":"真正的文化交流既需要访客，也需要东道主。"},{"en":"The gallery describes the joint exhibition as a cultural exchange, not a loan.","cn":"美术馆把这场联合展览称为文化交流，而非借展。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「cultural（文化的）+ exchange（交换）」——两边都拿出东西，两边都带回去","word":"cultural exchange"},"root":"cultural 来自拉丁 cultura「耕作、培养」，源于 colere；exchange 经古法语 eschange 来自俗拉丁 excambiare「以物易物」，底层 cambire 的来源不确定，可能为高卢语。","sensesIntro":{"en":"Eight senses follow one round trip: culture travels through people, stages, books and language, is organised by institutions, happens informally at a table, and finally becomes a standard of equal reciprocity.","cn":"八个义项沿同一次往返展开：文化经由人、舞台、书籍与语言流动，由机构组织，也在餐桌上非正式发生，最后成为一种平等互惠的标准。"},"semanticMap":{"core":{"en":"CORE IMAGE: two suitcases crossing in mid-air, each carrying the other's songs.","cn":"核心意象：两只行李箱在半空交错，各带着对方的歌。"},"chain":["TWO-WAY FLOW","PEOPLE","ARTS","IDEAS","LANGUAGE","EVERYDAY LIFE"],"branches":[{"senses":"01","en":"BOTH WAYS: the base rule is that giving and receiving must both happen.","cn":"双向：基本规则是给出与收到都必须发生。"},{"senses":"02 · 06","en":"PEOPLE AND PROGRAMMES: bodies carry culture, and institutions arrange the journeys.","cn":"人与项目：身体承载文化，机构安排旅程。"},{"senses":"03 · 04","en":"ARTS AND IDEAS: a stage or a book can carry a culture farther than a single visit.","cn":"艺术与观念：舞台或书籍能把文化带得比一次访问更远。"},{"senses":"05 · 07","en":"LANGUAGE AND THE TABLE: the smallest exchanges teach both sides.","cn":"语言与餐桌：最小的交流让双方都学到东西。"},{"senses":"08","en":"THE STANDARD: the phrase can be used to judge whether the meeting was truly mutual.","cn":"标准：这个短语可用来判断相遇是否真正互惠。"}]},"affixes":{"intro":{"en":"The phrase can be read from a Latin noun for cultivation and a Latin verb of bartering, with English suffixes for relation and action.","cn":"这个短语可以按表示耕作的拉丁名词、表示以物易物的拉丁动词，以及表示关系与动作的英语后缀读出。"},"latinIntro":{"en":"Latin cultura supplies culture and cultural; Latin cambire, through Vulgar Latin and Old French, supplies exchange.","cn":"拉丁 cultura 衍生 culture 与 cultural；拉丁 cambire 经俗拉丁与古法语衍生 exchange。"},"items":[{"word":"colere","structure":"colere, colui, cultum (Latin verb)","meaning":"to till, cultivate, worship","meaningCN":"耕作；培养；敬奉","example":"The verb supplies the farming image behind culture.","exampleCN":"这个动词提供 culture 背后的农耕意象。"},{"word":"cultura","structure":"cultura, culturae (Latin noun)","meaning":"tilling; cultivation; care","meaningCN":"耕作；培养；照料","example":"Cultura first named the field.","exampleCN":"cultura 先指田地。"},{"word":"cultural","structure":"cultura + -al (relating to)","meaning":"relating to culture","meaningCN":"与文化相关的","example":"Cultural goods travel between countries.","exampleCN":"文化产品在国家间流动。"},{"word":"cambire","structure":"cambire (Latin verb)","meaning":"to exchange, barter","meaningCN":"交换；以物易物","example":"The verb is the base of exchange.","exampleCN":"这个动词是 exchange 的基础。"},{"word":"ex-","structure":"ex- (Latin prefix)","meaning":"out, forth","meaningCN":"向外；出","example":"The prefix marks giving out in return.","exampleCN":"这个前缀标记给出以换回。"},{"word":"excambiare","structure":"ex- + cambire (Vulgar Latin verb)","meaning":"to trade one thing for another","meaningCN":"以一物换另一物","example":"The verb passed into Old French.","exampleCN":"这个动词进入古法语。"},{"word":"exchange","structure":"excambiare through Old French eschangier","meaning":"to give and receive in return","meaningCN":"交换；交流","example":"The two schools exchange students.","exampleCN":"两所学校交换学生。"},{"word":"-able","structure":"-able (adjective suffix)","meaning":"can be","meaningCN":"可……的","example":"Exchangeable goods can be traded.","exampleCN":"可交换的货物能被交易。"},{"word":"interchange","structure":"inter- (between) + exchange","meaning":"mutual swapping","meaningCN":"互换；相互交换","example":"The two cities interchange exhibitions.","exampleCN":"两座城市互换展览。"},{"word":"cultural exchange","structure":"cultural + exchange","meaning":"two-way cultural traffic","meaningCN":"双向文化交流","example":"The programme is a cultural exchange.","exampleCN":"这个项目是文化交流。"}],"derivatives":[{"word":"exchangeable","structure":"exchange + -able (can be)","meaning":"able to be exchanged","meaningCN":"可交换的"},{"word":"interchange","structure":"inter- + change (English)","meaning":"a mutual swap","meaningCN":"互换"},{"word":"culturally","structure":"cultural + -ly (adverb)","meaning":"in cultural terms","meaningCN":"在文化方面"}],"latinEntries":[{"word":"cultura","structure":"cultura, culturae (f., first declension)","meaning":"tilling; cultivation; care","meaningCN":"耕作；培养；照料"},{"word":"cambire","structure":"cambire (verb)","meaning":"to exchange, barter","meaningCN":"交换；以物易物"},{"word":"excambium","structure":"excambium, excambii (n., second declension)","meaning":"an exchange, barter","meaningCN":"交换；易货"}]}},{"word":"cultural transmission","ipa_uk":"/ˌkʌltʃərəl trænsˈmɪʃən/","ipa_us":"/ˌkʌltʃərəl trænsˈmɪʃən/","definition_zh":"文化传递；文化通过社会学习在人与人、代与代之间传递的过程","definition_en":"the passing on of culture through social learning between people and across generations","core_image":"一双布满老茧的手把工具递给一双年轻的手，动作、节奏与禁忌都随工具一起交出去","scene":"老人把手艺一遍遍示范给孙辈，歌谣与禁忌也随同一双手传下去。Weaving skills pass from grandmother to granddaughter by cultural transmission rather than by written rules.","sceneCN":"这里 cultural transmission 指「文化经社会学习在代际之间传递」（第 1 个义项：文化传递的总过程）；句意为织布技艺靠文化传递从祖母传到孙女，而非靠成文规则。可辨识物件：织机、双手、线轴、歌谣、家屋。","pos":[{"tag":"n.","zh":"文化传递（人类学术语，常作不可数）"},{"tag":"n.","zh":"一次具体的文化传递（可数）"}],"collocations":[{"phrase":"cultural transmission of knowledge","zh":"知识的文化传递"},{"phrase":"vertical cultural transmission","zh":"纵向文化传递"},{"phrase":"cultural transmission across generations","zh":"跨代文化传递"},{"phrase":"the study of cultural transmission","zh":"文化传递研究"},{"phrase":"cultural transmission and learning","zh":"文化传递与学习"},{"phrase":"a mechanism of cultural transmission","zh":"文化传递机制"}],"forms":[{"label":"不可数用法（整体过程）","form":"cultural transmission"},{"label":"可数复数（具体传递）","form":"cultural transmissions"},{"label":"形容词（文化的）","form":"cultural"},{"label":"名词（传递）","form":"transmission"},{"label":"动词（传递）","form":"transmit"},{"label":"形容词（可传递的）","form":"transmissible"}],"derivatives":[{"word":"transmit","pos":"v.","zh":"传递；传播；传送"},{"word":"transmission","pos":"n.","zh":"传递；传播"},{"word":"transmitter","pos":"n.","zh":"传递者；发送器"},{"word":"transmissible","pos":"adj.","zh":"可传递的"},{"word":"cultural","pos":"adj.","zh":"文化的"},{"word":"culture","pos":"n.","zh":"文化"}],"senses":[{"no":"01","title":"Social learning across generations","titleCN":"跨代的社会学习","definition":"the passing of customs, skills and beliefs through teaching and imitation rather than genes","definitionCN":"风俗、技能与信念经教导与模仿而非基因传递","example":"Weaving skills pass from grandmother to granddaughter by cultural transmission rather than by written rules.","exampleCN":"织布技艺靠文化传递从祖母传到孙女，而非靠成文规则。","why":"Culture is what people learn from other people; transmission names the channel that carries it beyond one lifetime.","whyCN":"文化是人向他人学来的东西；传递指把它带出单个人一生的通道。"},{"no":"02","title":"Vertical transmission","titleCN":"纵向传递","definition":"the passing of culture from parents to children","definitionCN":"文化由父母传给孩子","example":"Vertical cultural transmission explains why dialects follow family lines.","exampleCN":"纵向文化传递解释了为何方言沿着家族线分布。","why":"The family is the first channel, and the parent-to-child direction is the one most easily observed.","whyCN":"家庭是第一通道，父母到孩子的方向也是最容易观察到的。"},{"no":"03","title":"Horizontal transmission","titleCN":"横向传递","definition":"the passing of culture between peers of the same generation","definitionCN":"同代同伴之间的文化传递","example":"Fashions spread by horizontal cultural transmission among classmates.","exampleCN":"时尚通过同学之间的横向文化传递扩散。","why":"Peers teach each other sideways, which is why a schoolyard can change faster than a household.","whyCN":"同伴横向互教，因此校园的品味变化可能比家庭更快。"},{"no":"04","title":"Oblique transmission","titleCN":"斜向传递","definition":"the passing of culture from non-parental adults of the older generation","definitionCN":"由非父母的上一代成年人传递文化","example":"Oblique cultural transmission happens through aunts, teachers and neighbours.","exampleCN":"斜向文化传递通过姑姨、教师与邻居发生。","why":"Adults other than parents also transmit, and anthropology gives this diagonal route its own name.","whyCN":"父母以外的成年人也在传递，人类学给这条斜线路径单独命名。"},{"no":"05","title":"Language and oral tradition","titleCN":"语言与口述传统","definition":"the passing of language, songs and stories by speech","definitionCN":"语言、歌谣与故事经口头传递","example":"Oral poetry survives by cultural transmission long after its first singers are forgotten.","exampleCN":"口头诗歌靠文化传递留存，远在其最早的歌者被遗忘之后。","why":"Speech is the lightest carrier: it needs no object, only a listener who repeats.","whyCN":"言语是最轻的载体：它不需要物件，只需要一个会复述的听者。"},{"no":"06","title":"Skills and apprenticeship","titleCN":"技能与师徒传授","definition":"the passing of practical skills through demonstration and practice","definitionCN":"实用技能经示范与练习传递","example":"The workshop keeps cultural transmission alive by pairing masters with beginners.","exampleCN":"这个工坊通过师徒配对让文化传递延续。","why":"Skills that live in the hands must be shown, not merely described, so apprenticeship is a distinct channel.","whyCN":"活在手上的技能必须被展示，而非仅被描述，因此师徒制是独立通道。"},{"no":"07","title":"Institutional transmission","titleCN":"制度化的传递","definition":"the passing of culture through schools, churches and formal training","definitionCN":"文化经学校、教会与正式训练传递","example":"Schools became the main institution of cultural transmission in the nineteenth century.","exampleCN":"学校在十九世纪成为文化传递的主要机构。","why":"Institutions stabilize transmission: they repeat the same lesson to many people at once.","whyCN":"机构使传递稳定：它们同时向许多人重复同一课。"},{"no":"08","title":"Transmission with modification","titleCN":"带变异的传递","definition":"the passing on of culture with small changes at each step, so the copy is never exact","definitionCN":"文化每传一步都带着小变化，因此复制从不完全相同","example":"Cultural transmission is never exact; each generation adds its own accent.","exampleCN":"文化传递从不完全精确；每一代都添上自己的口音。","why":"The word explains both stability and drift: the same channel that preserves a custom also lets it change.","whyCN":"这个词同时解释稳定与漂移：保存习俗的同一通道也允许它改变。"}],"etymology":{"intro":{"en":"Cultural transmission joins cultural, from Latin cultura 'tilling, cultivation', with transmission, from Latin transmissio, built on trans- 'across' and mittere 'to send'. Dates are approximate.","cn":"cultural transmission 由 cultural 与 transmission 合成：cultural 来自拉丁 cultura「耕作、培养」；transmission 来自拉丁 transmissio，由 trans-「越过」与 mittere「送出」构成。年代均为约数。"},"items":[{"era":"LATIN CULTURA","en":"Cultura came from colere 'to till, cultivate, worship'; it first named farming and later the tending of the mind.","cn":"cultura 来自 colere「耕作、培养、敬奉」；先指农耕，后指心智的培养。"},{"era":"LATIN MITTERE","en":"Mittere meant 'to send, let go'. Its deeper origin is not established, so no earlier form is given with confidence.","cn":"mittere 意为「送出、放走」。其更深来源未得到证明，因此无法有把握地给出更早形态。"},{"era":"LATIN TRANSMISSIO","en":"Trans- 'across' plus mittere produced transmittere 'to send across', and the noun transmissio named the act of sending through.","cn":"trans-「越过」加 mittere 构成 transmittere「送过去」，名词 transmissio 指传送的动作。"},{"era":"ENGLISH TRANSMISSION","en":"English transmission appeared in the fifteenth century for passing something through or along, including disease and signals.","cn":"英语 transmission 在十五世纪出现，指把某物传过或传下，包括疾病与信号。"},{"era":"ANTHROPOLOGY","en":"Anthropology adopted the phrase for culture learned from others, and later split it into vertical, horizontal and oblique routes.","cn":"人类学采用这个短语指从他人学来的文化，后来又把它分为纵向、横向与斜向路径。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the first use of the exact phrase is not fixed, and the pre-Latin origin of mittere is unsettled, so any older form is a reconstruction.","cn":"来源不确定（首见年代与更深词源）：这个确切短语的最早使用无法确定；mittere 在拉丁语之前的来源亦无定论，凡更早形态均属重构形式。"}]},"similar":{"note":{"en":"Group one shares the transmission stem; group two holds terms for culture being passed on.","cn":"第一组共享 transmission 词干；第二组是文化被传递的相关术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"transmit","ipa":"/trænsˈmɪt/","tag":"the verb","definition":"To send or pass something on; culture can be transmitted without being taught formally.","definitionCN":"指送出或传下某物；文化可以不经正式教学而传递。"},{"word":"transmission","ipa":"/trænsˈmɪʃən/","tag":"the bare noun","definition":"The act of passing something on; the phrase adds that the content is culture.","definitionCN":"指传递的动作；短语补充内容为文化。"},{"word":"transmitter","ipa":"/trænsˈmɪtə/","tag":"the sender","definition":"A person or device that sends something on, often used of signals or disease.","definitionCN":"指传递某物的人或装置，常用于信号或疾病。"},{"word":"transmissible","ipa":"/trænsˈmɪsəbəl/","tag":"can be passed on","definition":"Describes something able to be transmitted, such as a trait or an infection.","definitionCN":"描述可被传递之物，如特质或感染。"}]},{"heading":"NEAR MEANING","entries":[{"word":"inheritance","ipa":"/ɪnˈherɪtəns/","tag":"receiving from the past","definition":"What is received from predecessors, often including genes as well as culture.","definitionCN":"指从前辈接收之物，常同时包含基因与文化。"},{"word":"enculturation","ipa":"/ˌenkʌltʃəˈreɪʃən/","tag":"learning one's own culture","definition":"The process of learning the culture one grows up in, a form of transmission within a group.","definitionCN":"指习得自己成长其中的文化，是群体内传递的一种形式。"},{"word":"diffusion","ipa":"/dɪˈfjuːʒən/","tag":"spreading between groups","definition":"Movement of traits between societies rather than from one generation to the next.","definitionCN":"指文化特质在社会之间移动，而非代际之间。"},{"word":"socialization","ipa":"/ˌsəʊʃəlaɪˈzeɪʃən/","tag":"learning to be social","definition":"The broader process of learning how to live in a society, which includes but exceeds transmission.","definitionCN":"指学习如何在社会中生活的更广过程，包含传递但不止于此。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real routes, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实路径，而非编造的顺口溜。"},"normal":[{"en":"trans- 'across' plus mittere 'send': to send culture across time and people.","cn":"trans-「越过」加 mittere「送出」：把文化送过时间与人。"},{"en":"The family runs transmit, transmission, transmitter, transmissible.","cn":"同族词包括 transmit、transmission、transmitter、transmissible。"},{"en":"Fixed phrases: vertical cultural transmission, cultural transmission across generations.","cn":"固定搭配：纵向文化传递、跨代文化传递。"},{"en":"Remember the three routes: vertical from parents, horizontal from peers, oblique from other adults.","cn":"记住三条路径：纵向来自父母，横向来自同伴，斜向来自其他成年人。"},{"en":"The phrase explains both why customs last and why they slowly change.","cn":"这个短语同时解释习俗为何延续、又为何慢慢改变。"}],"abstract":[{"en":"Picture a tool changing hands while the rhythm of using it is also handed over.","cn":"想象工具易手时，使用它的节奏也一并交出。"},{"en":"Picture a song taught by singing, not by writing it down.","cn":"想象一首歌靠唱来教，而非写下来。"},{"en":"Picture a copy of a copy, each slightly blurred and each still recognizable.","cn":"想象复制品的复制品，每一份都略模糊，却仍可辨认。"}]},"examples":[{"en":"Language is the most studied case of cultural transmission because it leaves records.","cn":"语言是文化传递研究最多的案例，因为它留下记录。"},{"en":"The school turned informal cultural transmission into a fixed curriculum.","cn":"学校把非正式的文化传递变成固定课程。"},{"en":"Cultural transmission across generations explains why recipes survive migration.","cn":"跨代文化传递解释了为何菜谱能在迁徙中留存。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「cultural（文化的）+ transmission（传递）」——把文化像接力棒一样传下去，每一棒都带点自己的痕迹","word":"cultural transmission"},"root":"cultural 来自拉丁 cultura「耕作、培养」，源于 colere；transmission 来自拉丁 transmissio，由 trans-「越过」与 mittere「送出」构成。mittere 更早的来源不确定。","sensesIntro":{"en":"Eight senses follow one handover: culture is passed through parents, peers, other adults, speech, skilled hands and institutions, and every handover changes the copy a little.","cn":"八个义项沿同一次交接展开：文化经父母、同伴、其他成年人、言语、熟练的手与机构传递，而每一次交接都让复制品略有不同。"},"semanticMap":{"core":{"en":"CORE IMAGE: a worn hand passing a tool to a young hand, with rhythm and taboo going along with it.","cn":"核心意象：一双老手把工具递给一双年轻的手，节奏与禁忌随它一起交出。"},"chain":["HANDING ON","VERTICAL","HORIZONTAL","OBLIQUE","LANGUAGE","INSTITUTIONS"],"branches":[{"senses":"01","en":"THE CHANNEL: culture moves by learning, not by genes.","cn":"通道：文化靠学习移动，而非靠基因。"},{"senses":"02","en":"VERTICAL: parents are the first teachers.","cn":"纵向：父母是第一任教师。"},{"senses":"03 · 04","en":"SIDEWAYS AND DIAGONAL: peers and other adults open routes beyond the family.","cn":"横向与斜向：同伴与其他成年人开辟家庭之外的路径。"},{"senses":"05 · 06","en":"SPEECH AND HANDS: songs need listeners, skills need demonstration.","cn":"言语与手：歌需要听者，技能需要示范。"},{"senses":"07 · 08","en":"INSTITUTIONS AND DRIFT: schools stabilize the copy, while every step alters it.","cn":"机构与漂移：学校稳定复制品，而每一步都在改动它。"}]},"affixes":{"intro":{"en":"The phrase can be read from a Latin noun for cultivation and a Latin verb meaning to send across.","cn":"这个短语可以按表示耕作的拉丁名词与表示「送过去」的拉丁动词读出。"},"latinIntro":{"en":"Latin cultura supplies culture and cultural; Latin mittere supplies transmit, transmission and transmitter, while trans- fixes the direction across.","cn":"拉丁 cultura 衍生 culture 与 cultural；拉丁 mittere 衍生 transmit、transmission 与 transmitter，trans- 固定了越过的方向。"},"items":[{"word":"colere","structure":"colere, colui, cultum (Latin verb)","meaning":"to till, cultivate, worship","meaningCN":"耕作；培养；敬奉","example":"The verb supplies the farming image.","exampleCN":"这个动词提供农耕意象。"},{"word":"cultura","structure":"cultura, culturae (Latin noun)","meaning":"tilling; cultivation; care","meaningCN":"耕作；培养；照料","example":"Cultura first named the field.","exampleCN":"cultura 先指田地。"},{"word":"cultural","structure":"cultura + -al (relating to)","meaning":"relating to culture","meaningCN":"与文化相关的","example":"Cultural knowledge passes between people.","exampleCN":"文化知识在人与人之间传递。"},{"word":"trans-","structure":"trans- (Latin prefix)","meaning":"across, through","meaningCN":"越过；穿过","example":"The prefix marks movement across time or groups.","exampleCN":"这个前缀标记越过时间或群体。"},{"word":"mittere","structure":"mittere, misi, missum (Latin verb)","meaning":"to send, let go","meaningCN":"送出；放走","example":"The verb supplies the act of sending.","exampleCN":"这个动词提供送出的动作。"},{"word":"transmittere","structure":"trans- + mittere (Latin verb)","meaning":"to send across","meaningCN":"送过去；传递","example":"The compound names sending something through.","exampleCN":"这个合成词指把某物送过去。"},{"word":"transmission","structure":"transmittere + -ion (process noun)","meaning":"the act of sending across","meaningCN":"传递的动作","example":"Transmission carries culture beyond one life.","exampleCN":"传递把文化带出单个人一生。"},{"word":"transmit","structure":"transmittere through French","meaning":"to pass on","meaningCN":"传递；传播","example":"Parents transmit habits to children.","exampleCN":"父母把习惯传给孩子。"},{"word":"transmitter","structure":"transmit + -er (agent)","meaning":"one that sends","meaningCN":"传递者；发送器","example":"The transmitter passes the signal on.","exampleCN":"发送器把信号传出去。"},{"word":"transmissible","structure":"transmit + -ible (can be)","meaning":"able to be passed on","meaningCN":"可传递的","example":"Some traits are easily transmissible.","exampleCN":"有些特质容易传递。"}],"derivatives":[{"word":"transmission","structure":"transmit + -ion (noun)","meaning":"the act of passing something on","meaningCN":"传递；传播"},{"word":"transmitter","structure":"transmit + -er (agent)","meaning":"one that sends something on","meaningCN":"传递者；发送器"},{"word":"transmissible","structure":"transmit + -ible (can be)","meaning":"able to be passed on","meaningCN":"可传递的"}],"latinEntries":[{"word":"cultura","structure":"cultura, culturae (f., first declension)","meaning":"tilling; cultivation; care","meaningCN":"耕作；培养；照料"},{"word":"mittere","structure":"mittere, misi, missum (verb, third conjugation)","meaning":"to send, let go","meaningCN":"送出；放走"},{"word":"transmissio","structure":"transmissio, transmissionis (f., third declension)","meaning":"a sending across","meaningCN":"传送；传递"}]}},{"word":"invention","ipa_uk":"/ɪnˈvenʃən/","ipa_us":"/ɪnˈvenʃən/","definition_zh":"发明；发明物；编造；发明才能","definition_en":"the act or product of creating something new, or something made up rather than true","core_image":"一张空白的桌上先出现草图，再出现零件，最后出现一台能转动的小机器","scene":"工作台上摆着拆开的旧机器、画满草图的纸和一枚刚成形的零件。The workshop celebrates the invention of a cheap water filter.","sceneCN":"这里 invention 指「发明出来的新装置」（第 2 个义项：被造出的发明物）；句意为这个工坊庆祝一种廉价滤水器的发明。可辨识物件：工作台、旧机器、草图、金属零件、滤水器。","pos":[{"tag":"n.","zh":"发明（行为）；发明物"},{"tag":"n.","zh":"编造；虚构之事"},{"tag":"n.","zh":"发明才能；创造力"}],"collocations":[{"phrase":"the invention of printing","zh":"印刷术的发明"},{"phrase":"a brilliant invention","zh":"一项出色的发明"},{"phrase":"patent an invention","zh":"为一项发明申请专利"},{"phrase":"the age of invention","zh":"发明时代"},{"phrase":"pure invention","zh":"纯属编造"},{"phrase":"necessity is the mother of invention","zh":"需要是发明之母"}],"forms":[{"label":"单数（行为或事物）","form":"invention"},{"label":"复数（多项发明）","form":"inventions"},{"label":"动词（发明）","form":"invent"},{"label":"形容词（有创造力的）","form":"inventive"},{"label":"名词（发明者）","form":"inventor"},{"label":"形容词（虚构的）","form":"invented"}],"derivatives":[{"word":"invent","pos":"v.","zh":"发明；编造"},{"word":"inventor","pos":"n.","zh":"发明者"},{"word":"inventive","pos":"adj.","zh":"有创造力的；善于发明的"},{"word":"inventiveness","pos":"n.","zh":"创造力；发明才能"},{"word":"invented","pos":"adj.","zh":"发明的；虚构的"},{"word":"reinvent","pos":"v.","zh":"彻底改造；重新发明"}],"senses":[{"no":"01","title":"The act of creating something new","titleCN":"创造新事物的行为","definition":"the act of devising a new device, method or process","definitionCN":"设计出新装置、方法或流程的行为","example":"The invention of the printing press changed how ideas travelled.","exampleCN":"印刷机的发明改变了观念传播的方式。","why":"Invention begins with finding: the Latin verb meant 'to come upon', and the modern sense adds making what was found into a new thing.","whyCN":"invention 始于「找到」：拉丁动词意为「偶然遇到」，现代义再加上把所找到之物做成新东西。"},{"no":"02","title":"The thing invented","titleCN":"发明物","definition":"a new device or product that has been created","definitionCN":"被创造出来的新装置或产品","example":"The museum displays several inventions from the same workshop.","exampleCN":"博物馆展出同一工坊的几项发明。","why":"English often uses one noun for both the act and its product, so the same word names the work and the object on the shelf.","whyCN":"英语常用同一个名词既指行为也指产物，因此同一个词既指工作，也指架上的物件。"},{"no":"03","title":"A made-up story or false claim","titleCN":"编造的故事或虚假说法","definition":"something fabricated rather than discovered or true","definitionCN":"被编造而非发现或真实的事物","example":"The alibi was pure invention.","exampleCN":"那个不在场证明纯属编造。","why":"The same verb that means 'devise' also means 'fabricate', because both build something that was not there before.","whyCN":"既指「设计」又指「捏造」的同一个动词，因为两者都在造出原本不存在的东西。"},{"no":"04","title":"Inventive faculty","titleCN":"发明才能","definition":"the capacity to devise new things or original ideas","definitionCN":"设计新事物或原创观念的能力","example":"The essay praises invention over imitation in children's play.","exampleCN":"这篇文章称赞儿童游戏中的创造而非模仿。","why":"The noun can name the power itself, not only its exercise, just as 'reason' names a capacity as well as an act.","whyCN":"这个名词可以指能力本身，而不只是能力的运用，正如「理性」既指能力也指行为。"},{"no":"05","title":"Rhetorical invention","titleCN":"修辞学的「开题」","definition":"the first task of a speaker, namely finding arguments and material","definitionCN":"演说者的第一项任务，即寻找论点与材料","example":"Classical rhetoric treats invention as the first task of the speaker.","exampleCN":"古典修辞学把开题视为演说者的第一项任务。","why":"Ancient rhetoric called the discovery of arguments inventio, and English kept the term for that first stage.","whyCN":"古代修辞学把寻找论点称为 inventio，英语保留了这个术语指第一个阶段。"},{"no":"06","title":"A short musical piece","titleCN":"短小乐曲","definition":"a short instrumental composition, especially one showing a musical idea","definitionCN":"短小的器乐曲，尤指展示某个音乐构思的作品","example":"The pianist played a two-part invention by Bach.","exampleCN":"钢琴家演奏了巴赫的一首二部创意曲。","why":"Music borrowed the word for a piece that displays a newly devised pattern, and Bach fixed the title for a genre.","whyCN":"音乐借用这个词指展示新构思的乐曲，巴赫则把这个标题固定为一个体裁。"},{"no":"07","title":"A patentable invention","titleCN":"可获专利的发明","definition":"a new and useful technical solution that the law protects","definitionCN":"受法律保护的新颖且有用的技术方案","example":"The patent protects the invention for twenty years.","exampleCN":"专利保护这项发明二十年。","why":"Law narrows the word to what can be described, claimed and owned, which is why patent language is precise about novelty.","whyCN":"法律把这个词收窄到可被描述、主张与拥有的东西，因此专利语言对新颖性极为精确。"},{"no":"08","title":"Coming into being of an idea","titleCN":"观念的成形","definition":"the moment when an idea or possibility comes into existence","definitionCN":"某个观念或可能性开始存在的时刻","example":"The novel's central invention is a city that forgets its own history.","exampleCN":"这部小说的核心虚构是一个会忘记自身历史的城市。","why":"The abstract sense generalizes: anything that did not exist before and now exists can be called an invention, including a fictional world.","whyCN":"抽象义把它一般化：任何此前不存在、如今存在的东西都可称为发明，包括虚构世界。"}],"etymology":{"intro":{"en":"Invention comes from Latin inventio, from invenire 'to come upon, find', built on in- 'upon' and venire 'to come'. The sense shifted from finding to devising. Dates are approximate.","cn":"invention 来自拉丁 inventio，源于 invenire「偶然遇到、找到」，由 in-「在上、向内」与 venire「来」构成。词义由「发现」转为「设计」。年代均为约数。"},"items":[{"era":"LATIN VENIRE","en":"Venire meant 'to come'. Its deeper origin is generally traced to an Indo-European root for going, but the pre-Latin shape is a reconstruction.","cn":"venire 意为「来」。其更深来源一般追溯到表示「行走」的印欧词根，但拉丁语之前的形态属重构形式。"},{"era":"LATIN INVENIRE","en":"In- 'upon, into' plus venire gave invenire 'to come upon, find, discover'.","cn":"in-「在上、向内」加 venire 构成 invenire「遇到、找到、发现」。"},{"era":"LATIN INVENTIO","en":"Inventio named a finding or a discovery, and rhetoric used it for the stage of finding arguments.","cn":"inventio 指找到或发现，修辞学用它指寻找论点的阶段。"},{"era":"ENGLISH SHIFT","en":"English invention first meant 'discovery' and later 'devising something new'; the modern technical sense is the later one.","cn":"英语 invention 最初意为「发现」，后指「设计出新东西」；现代技术义属于较晚的层次。"},{"era":"PATENT AND MUSIC","en":"Patent law narrowed the word to protectable solutions, while music used it for short pieces displaying a new idea.","cn":"专利法把这个词收窄到可保护的技术方案，音乐则用它指标题短曲，展示新的乐思。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the exact first use of each later sense is not fixed, and the pre-Latin form of venire is reconstructed rather than attested.","cn":"来源不确定（首见年代）：各晚期义项的最早书证无法确定；venire 在拉丁语之前的形态属重构形式，并无实际书证。"}]},"similar":{"note":{"en":"Group one is built on the same 'come' root; group two names new things and new ideas from other angles.","cn":"第一组同出「来」词根；第二组从其他角度指称新事物与新观念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"invent","ipa":"/ɪnˈvent/","tag":"the verb","definition":"The act behind the noun; it can mean both 'devise' and 'fabricate'.","definitionCN":"名词背后的动作；既可指「设计」，也可指「捏造」。"},{"word":"inventive","ipa":"/ɪnˈventɪv/","tag":"adjective","definition":"Describes a person or solution full of new ideas.","definitionCN":"描述充满新想法的人或方案。"},{"word":"inventory","ipa":"/ɪnˈventəri/","tag":"same root, other sense","definition":"From a Latin word for a list of what is found; it names stock, not a new device.","definitionCN":"来自拉丁语「所找到之物的清单」，指存货，而非新装置。"},{"word":"prevention","ipa":"/prɪˈvenʃən/","tag":"different prefix","definition":"Built on prae- 'before' plus venire: coming before to stop something, not finding something new.","definitionCN":"由 prae-「在前」加 venire 构成：先来阻止，而非发现新事物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"innovation","ipa":"/ˌɪnəˈveɪʃən/","tag":"making new in practice","definition":"The introduction of a new method or product into use; invention is the idea, innovation the adoption.","definitionCN":"指新方法或新产品投入使用；invention 是构想，innovation 是采用。"},{"word":"discovery","ipa":"/dɪsˈkʌvəri/","tag":"finding what exists","definition":"The finding of something already in the world; invention makes something new.","definitionCN":"指发现已存在之物；invention 则造出新东西。"},{"word":"creation","ipa":"/kriˈeɪʃən/","tag":"bringing into being","definition":"A broad word for bringing something into existence, including art and fiction.","definitionCN":"指使某物开始存在的宽泛词，包括艺术与虚构。"},{"word":"patent","ipa":"/ˈpætənt/","tag":"legal protection","definition":"The legal right granted for an invention, not the invention itself.","definitionCN":"指授予发明的法律权利，而非发明本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"in- 'upon' plus venire 'come': to come upon something, then make it new.","cn":"in-「在上」加 venire「来」：遇到某物，再把它做成新的。"},{"en":"The family runs invent, inventor, inventive, inventiveness, invention.","cn":"同族词包括 invent、inventor、inventive、inventiveness、invention。"},{"en":"Fixed phrases: the invention of printing, patent an invention, pure invention.","cn":"固定搭配：印刷术的发明、为发明申请专利、纯属编造。"},{"en":"The same word covers a machine, a lie and a piece of music.","cn":"同一个词覆盖机器、谎言与一首乐曲。"},{"en":"Distinguish invention from innovation: the first is the idea, the second is its use.","cn":"区分 invention 与 innovation：前者是构想，后者是使用。"}],"abstract":[{"en":"Picture a blank desk where a sketch becomes a part and a part becomes a machine.","cn":"想象一张空桌，草图变成零件，零件变成机器。"},{"en":"Picture a door that was not there yesterday and is there today.","cn":"想象一扇昨天不存在的门，今天出现了。"},{"en":"Picture a lie told so well that it acquires its own furniture.","cn":"想象一个编得如此周密的谎，连家具都长出来了。"}]},"examples":[{"en":"The invention of a cheap battery made night study possible in villages.","cn":"廉价电池的发明让乡村的夜间学习成为可能。"},{"en":"The committee could not tell invention from clever imitation.","cn":"委员会分不清发明与巧妙的模仿。"},{"en":"Her invention as a storyteller was praised more than her facts.","cn":"她作为讲述者的虚构才能比她说的事实更受称赞。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「进入」加「来」加「名词」——一个想法走进现实，就成了发明","word":"invention"},"root":"拉丁 inventio，源于 invenire「遇到、找到」= in-（在上、向内）+ venire（来）；词义由「发现」转为「设计出新东西」。venire 更早的印欧形态属重构。","sensesIntro":{"en":"Eight senses follow one arrival: something comes upon the mind, is made into an object, can also be fabricated, can name the faculty itself, and then appears in rhetoric, music, patent law and fiction.","cn":"八个义项沿同一次到来展开：某物来到心头，被做成物件，也可以被捏造，还可以指能力本身，随后出现在修辞、音乐、专利法与虚构作品中。"},"semanticMap":{"core":{"en":"CORE IMAGE: a blank desk where a sketch becomes a part and a part becomes a working machine.","cn":"核心意象：一张空桌，草图变成零件，零件变成能运转的机器。"},"chain":["COME UPON","MAKE NEW","OBJECT","FABRICATION","ARGUMENT","ART"],"branches":[{"senses":"01 · 08","en":"ARRIVAL: an idea comes into being, whether as a machine or a fictional world.","cn":"到来：一个观念开始存在，可以是机器，也可以是虚构世界。"},{"senses":"02 · 07","en":"OBJECT AND RIGHT: the thing on the shelf may also be claimed by patent law.","cn":"物件与权利：架上的东西也可能被专利法主张。"},{"senses":"03","en":"FABRICATION: the same act can build a lie instead of a device.","cn":"捏造：同一个动作可以造出谎言，而非装置。"},{"senses":"04","en":"FACULTY: the noun can name the power to devise, not only one result.","cn":"能力：这个名词可以指设计的能力，而不只是某件成品。"},{"senses":"05 · 06","en":"ARGUMENT AND ART: rhetoric finds its material, and music displays a new pattern.","cn":"论点与艺术：修辞寻找材料，音乐展示新格局。"}]},"affixes":{"intro":{"en":"Invention can be read from a Latin prefix meaning 'upon', the Latin verb for coming, and a noun suffix naming an act.","cn":"invention 可以按表示「在上」的拉丁前缀、表示「来」的拉丁动词，以及表示动作的名词后缀逐段读出。"},"latinIntro":{"en":"Latin venire supplies invent, invention, prevent and event; in- adds the sense of coming upon.","cn":"拉丁 venire 衍生 invent、invention、prevent 与 event；in- 增添「遇到」的意思。"},"items":[{"word":"in-","structure":"in- (Latin prefix)","meaning":"upon, into","meaningCN":"在上；向内","example":"The prefix marks coming upon something.","exampleCN":"这个前缀标记遇到某物。"},{"word":"venire","structure":"venire, veni, ventum (Latin verb, fourth conjugation)","meaning":"to come","meaningCN":"来","example":"The verb supplies the movement toward.","exampleCN":"这个动词提供朝某处移动的意思。"},{"word":"invenire","structure":"in- + venire (Latin verb)","meaning":"to come upon, find","meaningCN":"遇到；找到","example":"The compound names finding by arriving.","exampleCN":"这个合成词指通过到达而找到。"},{"word":"invention","structure":"invenire + -ion (act noun)","meaning":"a finding; then a devising","meaningCN":"发现；后指设计","example":"Invention shifted from finding to making.","exampleCN":"invention 从发现转为制造。"},{"word":"invent","structure":"invenire through French","meaning":"to devise or fabricate","meaningCN":"发明；编造","example":"She invented a new device.","exampleCN":"她发明了一种新装置。"},{"word":"inventor","structure":"invent + -or (agent)","meaning":"one who invents","meaningCN":"发明者","example":"The inventor filed a patent.","exampleCN":"发明者提交了专利申请。"},{"word":"inventive","structure":"invent + -ive (tending to)","meaning":"full of new ideas","meaningCN":"有创造力的","example":"The team is inventive under pressure.","exampleCN":"这个团队在压力下很有创造力。"},{"word":"inventiveness","structure":"inventive + -ness (state)","meaning":"the quality of being inventive","meaningCN":"发明才能","example":"Her inventiveness showed early.","exampleCN":"她的发明才能很早就显现。"},{"word":"reinvent","structure":"re- (again) + invent","meaning":"to remake or devise anew","meaningCN":"彻底改造；重新发明","example":"The studio reinvented the old format.","exampleCN":"工作室彻底改造了旧形式。"},{"word":"prevention","structure":"prae- (before) + venire + -ion","meaning":"a coming before to stop something","meaningCN":"预防；阻止","example":"Prevention uses a different prefix.","exampleCN":"prevention 使用了不同的前缀。"}],"derivatives":[{"word":"inventor","structure":"invent + -or (agent)","meaning":"a person who creates something new","meaningCN":"发明者"},{"word":"inventive","structure":"invent + -ive (adjective)","meaning":"tending to devise new things","meaningCN":"有创造力的"},{"word":"reinvent","structure":"re- + invent (verb)","meaning":"to devise anew","meaningCN":"重新发明"}],"latinEntries":[{"word":"venire","structure":"venire, veni, ventum (verb, fourth conjugation)","meaning":"to come","meaningCN":"来"},{"word":"invenire","structure":"invenire, inveni, inventum (verb, fourth conjugation)","meaning":"to come upon, find","meaningCN":"遇到；找到"},{"word":"inventio","structure":"inventio, inventionis (f., third declension)","meaning":"a finding; a discovery","meaningCN":"发现；找到"}]}},{"word":"invention process","ipa_uk":"/ɪnˈvenʃən ˈprəʊses/","ipa_us":"/ɪnˈvenʃən ˈprɑːses/","definition_zh":"发明流程；从发现问题到方案被采用的完整过程","definition_en":"the sequence of stages through which a new device or method is imagined, tested and brought into use","core_image":"一块白板上从左到右排着问题、草图、样机、测试记录、申请文件和用户反馈","scene":"从发现水质问题，到画图、做样机、反复测试，再到申请保护，整条路走了三年。The invention process began with a dirty well and ended with a patented filter.","sceneCN":"这里 invention process 指「从发现问题到方案落地的完整流程」（第 1 个义项：发明全过程的总称）；句意为这条发明流程从一口脏井开始，以一台获专利的滤水器结束。可辨识物件：白板、草图、样机、测试记录、专利文件、水井。","pos":[{"tag":"n.","zh":"发明流程（可数或不可数）"},{"tag":"n.","zh":"某一次具体的发明过程"}],"collocations":[{"phrase":"the invention process begins with","zh":"发明流程始于……"},{"phrase":"manage the invention process","zh":"管理发明流程"},{"phrase":"document the invention process","zh":"记录发明流程"},{"phrase":"each stage of the invention process","zh":"发明流程的每个阶段"},{"phrase":"a long invention process","zh":"漫长的发明流程"},{"phrase":"the invention process and patenting","zh":"发明流程与专利申请"}],"forms":[{"label":"单数（一次流程）","form":"invention process"},{"label":"复数（多次流程）","form":"invention processes"},{"label":"名词（发明）","form":"invention"},{"label":"动词（发明）","form":"invent"},{"label":"名词（流程）","form":"process"}],"derivatives":[{"word":"invention","pos":"n.","zh":"发明；发明物"},{"word":"invent","pos":"v.","zh":"发明；编造"},{"word":"inventor","pos":"n.","zh":"发明者"},{"word":"process","pos":"n./v.","zh":"流程；处理"},{"word":"processing","pos":"n.","zh":"加工；处理"},{"word":"processional","pos":"adj.","zh":"列队行进的（词源相关但语义有别）"}],"senses":[{"no":"01","title":"The whole sequence","titleCN":"从问题到落地的全过程","definition":"the entire sequence from first problem to a working solution in use","definitionCN":"从最初的问题到投入使用方案的完整序列","example":"The invention process began with a dirty well and ended with a patented filter.","exampleCN":"这条发明流程从一口脏井开始，以一台获专利的滤水器结束。","why":"Process names a forward course, and invention supplies the destination: a new thing that did not exist before.","whyCN":"process 指向前推进的过程，invention 提供终点：一件此前不存在的新东西。"},{"no":"02","title":"Problem identification","titleCN":"问题识别阶段","definition":"the stage of defining the need or failure that the invention must address","definitionCN":"界定发明必须解决的需要的阶段","example":"The first step of the invention process is naming the problem precisely.","exampleCN":"发明流程的第一步是精确地命名问题。","why":"Nothing is invented until someone decides what counts as broken, so the process starts with diagnosis rather than drawing.","whyCN":"在有人判定什么算「坏了」之前，什么都不会被发明，因此流程始于诊断而非画图。"},{"no":"03","title":"Idea generation","titleCN":"构思阶段","definition":"the stage of producing possible solutions and rough concepts","definitionCN":"产生可能方案与粗略构想的阶段","example":"Sketches on the whiteboard marked the idea stage of the invention process.","exampleCN":"白板上的草图标记出发明流程的构思阶段。","why":"Ideas are cheap and many, so this stage broadcasts widely before choosing what to build.","whyCN":"想法廉价而众多，因此这个阶段先广泛发散，再决定要造什么。"},{"no":"04","title":"Prototyping and testing","titleCN":"样机制作与测试阶段","definition":"the stage of building a physical or digital model and measuring how it fails","definitionCN":"制作实物或数字模型并测量其失败方式的阶段","example":"The invention process moved from paper to a working prototype in six months.","exampleCN":"这条发明流程在六个月内从纸面推进到可运转的样机。","why":"A model turns an argument into evidence: the prototype is where the invention meets friction.","whyCN":"模型把论点变成证据：样机是发明与阻力相遇的地方。"},{"no":"05","title":"Evaluation and iteration","titleCN":"评估与迭代阶段","definition":"the stage of judging results and revising the design repeatedly","definitionCN":"判断结果并反复修改设计的阶段","example":"Most of the invention process was iteration, not inspiration.","exampleCN":"这条发明流程的大部分是迭代，而非灵感。","why":"The word process implies repetition; real invention loops back through failure instead of moving in a straight line.","whyCN":"process 一词暗示重复；真正的发明会经失败绕回，而非直线前进。"},{"no":"06","title":"Patent and legal protection","titleCN":"专利与法律保护阶段","definition":"the stage of describing the invention formally and securing rights to it","definitionCN":"正式描述发明并取得其权利的阶段","example":"The invention process includes a patent search before any public demonstration.","exampleCN":"发明流程包括在公开演示之前进行专利检索。","why":"Once an invention may be owned, the process gains a legal stage that rewards disclosure with temporary exclusivity.","whyCN":"一旦发明可以被拥有，流程就多出一个法律阶段，以公开换取临时独占。"},{"no":"07","title":"Technology transfer and commercialisation","titleCN":"技术转移与商业化阶段","definition":"the stage of moving the invention from workshop to production and market","definitionCN":"把发明从工坊推进到生产与市场的阶段","example":"The invention process stalls when no one funds the step from prototype to factory.","exampleCN":"当无人资助从样机到工厂这一步时，发明流程就会停滞。","why":"A device that stays on a bench has not finished its process; transfer is the bridge to use.","whyCN":"留在工作台上的装置并未走完流程；技术转移是通向使用的桥。"},{"no":"08","title":"Social adoption","titleCN":"社会采纳阶段","definition":"the stage in which users, institutions and habits absorb the invention","definitionCN":"使用者、机构与习惯吸收发明的阶段","example":"The invention process ends only when the filter is actually used in kitchens.","exampleCN":"只有当滤水器真的在厨房里被使用，发明流程才算结束。","why":"Adoption is the last and least visible stage: an invention changes society only when it becomes ordinary.","whyCN":"采纳是最后也最不显眼的阶段：发明白只有在变得平常时才改变社会。"}],"etymology":{"intro":{"en":"Invention process joins invention, from Latin invenire 'to come upon, find', with process, from Latin processus, from procedere 'to go forward', built on pro- 'forward' and cedere 'to go'. Dates are approximate.","cn":"invention process 由 invention 与 process 合成：invention 来自拉丁 invenire「遇到、找到」；process 来自拉丁 processus，源于 procedere「向前走」，由 pro-「向前」与 cedere「走」构成。年代均为约数。"},"items":[{"era":"LATIN INVENIRE","en":"In- 'upon' plus venire 'to come' gave invenire 'to come upon, find'; the noun inventio first named a discovery.","cn":"in-「在上」加 venire「来」构成 invenire「遇到、找到」；名词 inventio 最初指发现。"},{"era":"LATIN PROCEDERE","en":"Pro- 'forward' plus cedere 'to go, yield' gave procedere 'to go forward, advance'.","cn":"pro-「向前」加 cedere「走、让」构成 procedere「向前走、推进」。"},{"era":"LATIN PROCESSUS","en":"Processus named a going forward, an advance or a course, and later an ordered series of steps.","cn":"processus 指前进、推进或进程，后来指有序的步骤序列。"},{"era":"ENGLISH PROCESS","en":"English process entered through French in the fourteenth century, naming a course of events or a method.","cn":"英语 process 在十四世纪经法语进入，指事件进程或方法。"},{"era":"MODERN PHRASE","en":"The phrase invention process spread in the twentieth century with industrial research, patent offices and design management.","cn":"invention process 在二十世纪随工业研究、专利机构与设计管理而流行。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the first use of the exact phrase is not fixed, and the pre-Latin origins of venire and cedere are reconstructed rather than attested.","cn":"来源不确定（首见年代与更深词源）：这个确切短语的最早使用无法确定；venire 与 cedere 在拉丁语之前的来源属重构形式，并无实际书证。"}]},"similar":{"note":{"en":"Group one shares the two stems; group two names other ways of describing how new things are made.","cn":"第一组共享两个词干；第二组是从其他角度描述新事物如何被造出的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"invention","ipa":"/ɪnˈvenʃən/","tag":"the thing or act","definition":"Names what is created; the phrase adds the stages that produce it.","definitionCN":"指被造出之物或行为；短语补充产生它的各个阶段。"},{"word":"process","ipa":"/ˈprəʊses/","tag":"the course","definition":"A general forward course of steps; the phrase limits it to making something new.","definitionCN":"泛指向前推进的步骤；短语把它限定为造出新事物。"},{"word":"proceed","ipa":"/prəˈsiːd/","tag":"the verb","definition":"To go forward or continue, from the same Latin verb that gave process.","definitionCN":"指向前走或继续，与 process 同出拉丁动词。"},{"word":"procession","ipa":"/prəˈseʃən/","tag":"a moving line","definition":"A line of people or vehicles moving forward; it shares the root but not the meaning.","definitionCN":"指向前行进的人或车队；同根但意义不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"innovation process","ipa":"/ˌɪnəˈveɪʃən ˈprəʊses/","tag":"from idea to use","definition":"The path by which a new thing is adopted in practice; it overlaps but stresses use.","definitionCN":"指新事物被实际采用的路径；与发明流程重叠，但强调使用。"},{"word":"design cycle","ipa":"/ˈdaɪzən ˈsaɪkəl/","tag":"repeating loop","definition":"A repeating loop of design, test and revision, often shorter than an invention process.","definitionCN":"指设计、测试与修改的重复循环，通常比发明流程短。"},{"word":"research and development","ipa":"/rɪˈsɜːtʃ ænd ˌdevələpmənt/","tag":"organised work","definition":"The institutional activity that contains invention but also routine improvement.","definitionCN":"指包含发明但也包含常规改进的制度化活动。"},{"word":"development","ipa":"/dɪˈveləpmənt/","tag":"making ready for use","definition":"The work of turning a concept into a reliable product, one stage of the larger process.","definitionCN":"指把构想变成可靠产品的工作，是更大流程中的一个阶段。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real stages, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实阶段，而非编造的顺口溜。"},"normal":[{"en":"Invention comes from 'come upon'; process comes from 'go forward'.","cn":"invention 来自「遇到」；process 来自「向前走」。"},{"en":"The family runs invention, invent, inventor, process, processing.","cn":"同族词包括 invention、invent、inventor、process、processing。"},{"en":"Fixed phrases: manage the invention process, each stage of the invention process.","cn":"固定搭配：管理发明流程、发明流程的每个阶段。"},{"en":"Remember the order: problem, idea, prototype, test, iteration, patent, transfer, adoption.","cn":"记住顺序：问题、构思、样机、测试、迭代、专利、转移、采纳。"},{"en":"The phrase is countable: one invention process, several invention processes.","cn":"这个短语可数：一条发明流程、多条发明流程。"}],"abstract":[{"en":"Picture a whiteboard filling from left to right with failures and fixes.","cn":"想象白板从左到右写满失败与修正。"},{"en":"Picture a bench where a sketch slowly acquires weight.","cn":"想象工作台上，一张草图慢慢有了重量。"},{"en":"Picture a factory gate opening only after a long line of tests.","cn":"想象工厂大门在一长串测试之后才打开。"}]},"examples":[{"en":"The invention process is often slowed by the cost of testing, not by the lack of ideas.","cn":"发明流程常因测试成本而变慢，而非因缺少想法。"},{"en":"Her course follows the invention process from problem statement to patent claim.","cn":"她的课程沿发明流程从问题陈述讲到专利主张。"},{"en":"Universities now measure the invention process by licences rather than by prototypes.","cn":"大学如今用许可数量而非样机数量来衡量发明流程。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「invention（发明）+ process（流程）」——从问题到成品的一条流水线","word":"invention process"},"root":"invention 来自拉丁 invenire「遇到、找到」= in-（在上）+ venire（来）；process 来自拉丁 processus，源于 procedere「向前走」= pro-（向前）+ cedere（走）。更早形态均属重构。","sensesIntro":{"en":"Eight senses follow one forward course: a problem is named, ideas are sketched, a prototype is tested, the design iterates, rights are secured, the result is transferred, and users finally absorb it.","cn":"八个义项沿同一条向前的路展开：问题被命名，想法被画成草图，样机被测试，设计反复迭代，权利被确立，成果被转移，最后使用者把它吸收进日常。"},"semanticMap":{"core":{"en":"CORE IMAGE: a whiteboard filling from left to right with problem, sketch, prototype, test record, patent paper and user note.","cn":"核心意象：一块白板从左到右写满问题、草图、样机、测试记录、专利文件与用户留言。"},"chain":["PROBLEM","IDEA","PROTOTYPE","TEST","RIGHT","ADOPTION"],"branches":[{"senses":"01","en":"THE WHOLE COURSE: process supplies the forward line, invention supplies the new endpoint.","cn":"全程：process 提供向前的线，invention 提供新的终点。"},{"senses":"02 · 05","en":"DIAGNOSIS AND REVISION: naming the failure and looping back through it are two ends of the same learning.","cn":"诊断与修正：命名失败与绕回失败，是同一学习的两端。"},{"senses":"03 · 04","en":"SKETCH AND MODEL: an idea becomes evidence only when it can be built and measured.","cn":"草图与模型：想法只有在能被建造与测量时才成为证据。"},{"senses":"06 · 07","en":"RIGHT AND TRANSFER: law protects the idea, and transfer carries it toward production.","cn":"权利与转移：法律保护想法，转移把它带向生产。"},{"senses":"08","en":"ADOPTION: the process is not finished until the invention becomes ordinary.","cn":"采纳：直到发明变得平常，流程才算结束。"}]},"affixes":{"intro":{"en":"The phrase can be read from a Latin verb of finding and a Latin verb of going forward, each with an English noun form.","cn":"这个短语可以按表示「找到」的拉丁动词与表示「向前走」的拉丁动词读出，二者各有一个英语名词形式。"},"latinIntro":{"en":"Latin venire supplies invent, invention and prevent; Latin cedere supplies process, proceed and procedure.","cn":"拉丁 venire 衍生 invent、invention 与 prevent；拉丁 cedere 衍生 process、proceed 与 procedure。"},"items":[{"word":"venire","structure":"venire, veni, ventum (Latin verb)","meaning":"to come","meaningCN":"来","example":"The verb supplies the arrival behind invention.","exampleCN":"这个动词提供 invention 背后的到来。"},{"word":"invenire","structure":"in- + venire (Latin verb)","meaning":"to come upon, find","meaningCN":"遇到；找到","example":"Finding precedes making.","exampleCN":"找到先于制造。"},{"word":"inventio","structure":"invention + -io (Latin noun)","meaning":"a finding; a discovery","meaningCN":"发现；找到","example":"The noun first named discovery.","exampleCN":"这个名词最初指发现。"},{"word":"invention","structure":"inventio through French","meaning":"a finding; then a new device","meaningCN":"发现；后指新装置","example":"Invention now means making new things.","exampleCN":"invention 现在指造出新东西。"},{"word":"pro-","structure":"pro- (Latin prefix)","meaning":"forward, before","meaningCN":"向前；在前","example":"The prefix gives the forward direction.","exampleCN":"这个前缀给出向前的方向。"},{"word":"cedere","structure":"cedere, cessi, cessum (Latin verb)","meaning":"to go, yield","meaningCN":"走；让","example":"The verb supplies movement.","exampleCN":"这个动词提供移动。"},{"word":"procedere","structure":"pro- + cedere (Latin verb)","meaning":"to go forward","meaningCN":"向前走；推进","example":"The compound names advance.","exampleCN":"这个合成词指前进。"},{"word":"processus","structure":"procedere, past participle (Latin noun)","meaning":"a going forward; a course","meaningCN":"前进；进程","example":"The noun became the English process.","exampleCN":"这个名词变成英语 process。"},{"word":"process","structure":"processus through French","meaning":"a course of steps","meaningCN":"步骤序列；流程","example":"The process has stages.","exampleCN":"流程有各个阶段。"},{"word":"processing","structure":"process + -ing (noun)","meaning":"the handling of something through steps","meaningCN":"加工；处理","example":"Processing turns material into product.","exampleCN":"加工把材料变成产品。"}],"derivatives":[{"word":"invent","structure":"invenire through French (verb)","meaning":"to devise something new","meaningCN":"发明"},{"word":"inventor","structure":"invent + -or (agent)","meaning":"one who invent","meaningCN":"发明者"},{"word":"proceed","structure":"procedere through French (verb)","meaning":"to go forward","meaningCN":"前进；继续进行"}],"latinEntries":[{"word":"invenire","structure":"invenire, inveni, inventum (verb, fourth conjugation)","meaning":"to come upon, find","meaningCN":"遇到；找到"},{"word":"procedere","structure":"procedere, processi, processum (verb, third conjugation)","meaning":"to go forward","meaningCN":"向前走；推进"},{"word":"processus","structure":"processus, processus (m., fourth declension)","meaning":"a going forward; a course","meaningCN":"前进；进程"}]}},{"word":"technological advancement","ipa_uk":"/ˌteknəˈlɒdʒɪkəl ədˈvɑːnsmənt/","ipa_us":"/ˌteknəˈlɑːdʒɪkəl ədˈvænsmənt/","definition_zh":"技术进步；技术能力、工具与工艺水平的提升","definition_en":"the improvement of tools, machines, methods or technical knowledge over time","core_image":"同一块田里，牛犁、拖拉机与巡田无人机依次出现，每一代都在同一片土上留下更深的痕迹","scene":"同一块田里，先是用牛拉犁，后来用拖拉机，如今用无人机巡田。Technological advancement has changed what a single farmer can do in a day.","sceneCN":"这里 technological advancement 指「工具与工艺水平的整体提升」（第 1 个义项：技术能力随时间的进步）；句意为技术进步改变了一个农民一天能完成的工作。可辨识物件：牛犁、拖拉机、无人机、田垄、传感器。","pos":[{"tag":"n.","zh":"技术进步（常作不可数）"},{"tag":"n.","zh":"一项技术进展（可数）"}],"collocations":[{"phrase":"rapid technological advancement","zh":"迅速的技术进步"},{"phrase":"technological advancement in medicine","zh":"医学技术进步"},{"phrase":"the pace of technological advancement","zh":"技术进步的速度"},{"phrase":"technological advancement and employment","zh":"技术进步与就业"},{"phrase":"drive technological advancement","zh":"推动技术进步"},{"phrase":"a major technological advancement","zh":"一项重大技术进展"}],"forms":[{"label":"不可数用法（整体进步）","form":"technological advancement"},{"label":"可数复数（具体进展）","form":"technological advancements"},{"label":"形容词（技术的）","form":"technological"},{"label":"名词（技术）","form":"technology"},{"label":"动词（推进）","form":"advance"},{"label":"形容词（先进的）","form":"advanced"}],"derivatives":[{"word":"technology","pos":"n.","zh":"技术；工艺"},{"word":"technological","pos":"adj.","zh":"技术的"},{"word":"technologically","pos":"adv.","zh":"在技术上"},{"word":"advance","pos":"v./n.","zh":"推进；前进"},{"word":"advanced","pos":"adj.","zh":"先进的"},{"word":"advancement","pos":"n.","zh":"推进；进步"}],"senses":[{"no":"01","title":"General improvement of technique","titleCN":"技术水平的整体提升","definition":"the broad improvement of tools, methods and technical knowledge over time","definitionCN":"工具、方法与技术知识随时间的广泛改进","example":"Technological advancement has changed what a single farmer can do in a day.","exampleCN":"技术进步改变了一个农民一天能完成的工作。","why":"Advancement is forward movement, and technology is organised craft; together they name a society's growing capacity to do things.","whyCN":"advancement 是向前移动，technology 是组织化的技艺；合起来指一个社会做事能力的增长。"},{"no":"02","title":"A single breakthrough","titleCN":"单项技术突破","definition":"one major new device or method that opens new possibilities","definitionCN":"一项开辟新可能的重大新装置或方法","example":"The vaccine was hailed as a technological advancement of the decade.","exampleCN":"这种疫苗被誉为这十年的一项技术突破。","why":"The phrase can count individual breakthroughs, not only a long trend, because progress often arrives in steps.","whyCN":"这个短语可以数出单项突破，而不只是长期趋势，因为进步常以台阶形式到来。"},{"no":"03","title":"Productivity gains","titleCN":"生产率的提升","definition":"the ability to produce more or better output with the same effort","definitionCN":"以同样投入产出更多或更好的能力","example":"Technological advancement in weaving cut the cost of cloth for ordinary households.","exampleCN":"织造技术的进步降低了普通家庭的布料成本。","why":"The economic face of the phrase is productivity: new tools change how much one hour of work can make.","whyCN":"这个短语的经济面是生产率：新工具改变一小时劳动能造出多少东西。"},{"no":"04","title":"Social change driven by technology","titleCN":"技术驱动的社会变化","definition":"changes in work, communication and daily life that follow new technology","definitionCN":"随新技术而来的工作、通信与日常生活变化","example":"Technological advancement reshaped where people could work and whom they could reach.","exampleCN":"技术进步重塑了人们能在哪里工作、能联系到谁。","why":"Tools do not stay in the workshop; they rearrange schedules, cities and families.","whyCN":"工具不会留在工坊里；它们重排时间表、城市与家庭。"},{"no":"05","title":"The digital and information leap","titleCN":"数字与信息的跃迁","definition":"the rapid gain in computing, storage and communication capacity","definitionCN":"计算、存储与通信能力的快速提升","example":"Technological advancement in chips made a phone more powerful than an old room of computers.","exampleCN":"芯片技术的进步让一部手机比过去一屋子电脑更强。","why":"The modern sense is often narrowed to digital gains, because computing has been the fastest-moving frontier.","whyCN":"现代义常被收窄到数字领域的增益，因为计算是最快移动的前沿。"},{"no":"06","title":"Medical and life-science progress","titleCN":"医学与生命科学的进步","definition":"new tools for diagnosis, treatment and the understanding of life","definitionCN":"用于诊断、治疗与理解生命的新工具","example":"Technological advancement in imaging let doctors see what surgery once had to reveal.","exampleCN":"成像技术的进步让医生看见过去只能靠手术揭示的东西。","why":"Where the object is the body, advancement is measured in survival and comfort, not only speed.","whyCN":"当对象是身体时，进步以存活与舒适衡量，而不只是速度。"},{"no":"07","title":"Military and engineering progress","titleCN":"军事与工程技术的进步","definition":"gains in materials, propulsion, construction and systems of control","definitionCN":"材料、推进、建造与控制系统的增益","example":"Technological advancement in materials made the bridge both lighter and stronger.","exampleCN":"材料技术的进步让这座桥更轻也更坚固。","why":"Engineering and warfare have often driven technique forward, because both reward precision and power.","whyCN":"工程与战争常推动技艺前进，因为两者都奖赏精确与力量。"},{"no":"08","title":"Costs and unequal gains","titleCN":"代价与不均衡收益","definition":"the displacement, inequality and risk that can accompany technical progress","definitionCN":"技术进展可能伴随的取代、不平等与风险","example":"Critics ask who bears the costs of technological advancement and who collects its gains.","exampleCN":"批评者追问谁承担技术进步的代价，谁收取它的收益。","why":"The phrase is usually positive, but the same tools that raise output can put people out of work, so the sense carries a shadow.","whyCN":"这个短语通常带正面色彩，但提高产出的同一批工具也可能让人失业，因此这一义项带着阴影。"}],"etymology":{"intro":{"en":"Technological joins Greek tekhnē 'art, craft, skill' with -logia 'study', and advancement joins advance, from Old French avancier and Vulgar Latin abantiare, with the noun suffix -ment. Dates are approximate.","cn":"technological 由希腊 tekhnē「技艺、手艺」加表示「学问」的后缀构成；advancement 由 advance 加名词后缀构成，advance 经古法语 avancier 来自俗拉丁 abantiare。年代均为约数。"},"items":[{"era":"GREEK TEKHNE","en":"Tekhnē meant 'art, craft, skill, a systematic way of making'. Its deeper origin is not established.","cn":"tekhnē 意为「技艺、手艺、技能、系统的制作方式」。其更深来源未得到证明。"},{"era":"GREEK LOGIA","en":"Logia meant 'study, discourse' and came from logos 'word, reason'; the compound tekhnologia named a systematic treatment of an art.","cn":"logia 意为「学问、论述」，来自 logos「言词、理性」；合成词 tekhnologia 指对某门技艺的系统论述。"},{"era":"ENGLISH TECHNOLOGY","en":"English technology appeared in the seventeenth century as a term for the systematic study of arts, and later shifted to the tools themselves.","cn":"英语 technology 在十七世纪出现，指对技艺的系统研究，后转指工具本身。"},{"era":"LATIN ABANTE","en":"Advance came through Old French from Vulgar Latin abantiare, built on Latin abante 'from before', from ab 'from' and ante 'before'.","cn":"advance 经古法语来自俗拉丁 abantiare，源于拉丁 abante「从前方」，由 ab「从」与 ante「前」构成。"},{"era":"ENGLISH ADVANCEMENT","en":"The noun advancement appeared in the fourteenth century, naming a moving forward and then a improvement in rank or knowledge.","cn":"名词 advancement 在十四世纪出现，先指向前移动，后指地位或知识的提升。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the exact first use of the combined phrase is not fixed, and the deeper origin of tekhnē is unsettled, so any older form is a reconstruction.","cn":"来源不确定（首见年代）：这个组合短语的最早书证无法确定；tekhnē 的更早来源亦无定论，凡更早形态均属重构形式。"}]},"similar":{"note":{"en":"Group one shares the two stems; group two names progress in other registers.","cn":"第一组共享两个词干；第二组是用其他语域表达进步的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"technology","ipa":"/tekˈnɒlədʒi/","tag":"the field","definition":"The tools and systems themselves; the phrase names their improvement.","definitionCN":"指工具与系统本身；短语指它们的改进。"},{"word":"technical","ipa":"/ˈteknɪkəl/","tag":"the adjective","definition":"Relating to technique or machinery, often in contrast to human or artistic matters.","definitionCN":"与技巧或机械相关，常与人或艺术事务相对。"},{"word":"technique","ipa":"/tekˈniːk/","tag":"a method","definition":"A specific way of doing something; advancement is the gain across many techniques.","definitionCN":"指做某事的具体方法；进步则指许多技巧的整体增益。"},{"word":"technologically","ipa":"/tekˈnɒlədʒɪkli/","tag":"the adverb","definition":"Means by means of technology; it does not name progress.","definitionCN":"意为在技术上；不指进步本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"progress","ipa":"/ˈprəʊɡres/","tag":"general forward movement","definition":"A broad word for improvement in any field; it does not specify tools.","definitionCN":"泛指任何领域的改善，不特指工具。"},{"word":"innovation","ipa":"/ˌɪnəˈveɪʃən/","tag":"new things introduced","definition":"The introduction of new products or methods; one engine of technological advancement.","definitionCN":"指新产品或新方法的引入，是技术进步的一台引擎。"},{"word":"breakthrough","ipa":"/ˈbreɪkθruː/","tag":"a sudden opening","definition":"A single decisive advance that removes an obstacle.","definitionCN":"指一次决定性的进展，消除了障碍。"},{"word":"modernization","ipa":"/ˌmɒdənaɪˈzeɪʃən/","tag":"becoming modern","definition":"A wider social process that includes technology but also institutions and habits.","definitionCN":"指更广的社会过程，包含技术，也包含制度与习惯。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real contrasts, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实对比，而非编造的顺口溜。"},"normal":[{"en":"The Greek word for craft plus the Greek word for study gives the technology half; the Latin word for forward gives the advancement half.","cn":"「技艺」加「学问」组成技术这一半；「向前」加名词后缀组成进步这一半。"},{"en":"The family runs technology, technological, technologically, advance, advanced, advancement.","cn":"同族词包括 technology、technological、technologically、advance、advanced、advancement。"},{"en":"Fixed phrases: rapid technological advancement, the pace of technological advancement.","cn":"固定搭配：迅速的技术进步、技术进步的速度。"},{"en":"The phrase can be uncountable for a trend or countable for a single breakthrough.","cn":"这个短语可不可数指趋势，也可可数指单项突破。"},{"en":"Remember the cost side: the same tools can raise output and displace workers.","cn":"记住代价面：同一批工具既能提高产出，也能取代工人。"}],"abstract":[{"en":"Picture a field where a plough, a tractor and a drone appear in turn.","cn":"想象一块田里依次出现犁、拖拉机与无人机。"},{"en":"Picture a phone doing the work of a room full of old machines.","cn":"想象一部手机干完一屋子旧机器的活。"},{"en":"Picture a bridge that grows lighter as its metal grows stronger.","cn":"想象一座桥随金属变强而变轻。"}]},"examples":[{"en":"Technological advancement lowered the cost of solar power faster than forecasts expected.","cn":"技术进步使太阳能成本下降得比预测更快。"},{"en":"The report links technological advancement to wage gaps rather than to overall growth alone.","cn":"报告把技术进步与工资差距联系起来，而非只看总体增长。"},{"en":"Each technological advancement in printing made books cheaper to own.","cn":"印刷术的每一次技术进步都让书籍更便宜。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「technological（技术的）+ advancement（前进）」——工具一代代往前走，把人的手越伸越长","word":"technological advancement"},"root":"technological 来自希腊 tekhnē「技艺」与表示「学问」的后缀；advancement 来自 advance 加名词后缀，advance 经古法语 avancier 出自俗拉丁 abantiare，源于拉丁 abante（ab + ante，从前方）。","sensesIntro":{"en":"Eight senses follow one rising line: technique improves overall, a breakthrough opens a door, output rises, society rearranges, computing leaps, medicine and engineering gain, and the costs appear.","cn":"八个义项沿一条上升线展开：技艺整体提高，一项突破打开一扇门，产出上升，社会重新排布，计算能力跃迁，医学与工程获益，代价也随之出现。"},"semanticMap":{"core":{"en":"CORE IMAGE: the same field crossed first by a plough, then a tractor, then a drone.","cn":"核心意象：同一块田先被犁走过，再被拖拉机走过，最后被无人机掠过。"},"chain":["BETTER TOOLS","BREAKTHROUGH","PRODUCTIVITY","SOCIETY","DIGITAL","COST"],"branches":[{"senses":"01","en":"THE TREND: improvement is continuous and cumulative.","cn":"趋势：改进是连续且累积的。"},{"senses":"02 · 07","en":"STEPS AND SYSTEMS: a single breakthrough and a whole engineering field both move the line.","cn":"台阶与系统：单项突破与整个工程领域都在推动这条线。"},{"senses":"03 · 04","en":"OUTPUT AND LIFE: productivity changes work, and work rearranges society.","cn":"产出与生活：生产率改变工作，工作又重排社会。"},{"senses":"05 · 06","en":"COMPUTING AND BODY: chips and medicine are the two most visible frontiers.","cn":"计算与身体：芯片与医学是最可见的两个前沿。"},{"senses":"08","en":"THE SHADOW: every gain has a bearer of cost.","cn":"阴影：每一项收益都有承担代价的人。"}]},"affixes":{"intro":{"en":"The phrase can be read from a Greek noun for craft, a Greek noun for study, and a Latin-derived verb of moving forward.","cn":"这个短语可以按表示技艺的希腊名词、表示学问的希腊名词，以及拉丁来源的「向前移动」动词读出。"},"latinIntro":{"en":"Greek tekhnē supplies technology and technique; Greek logos supplies the study suffix; Latin abante supplies advance and advancement.","cn":"希腊 tekhnē 衍生 technology 与 technique；希腊 logos 提供表示学问的后缀；拉丁 abante 衍生 advance 与 advancement。"},"items":[{"word":"tekhnē","structure":"tekhnē (Greek noun)","meaning":"art, craft, skill","meaningCN":"技艺；手艺；技能","example":"The noun supplies the craft half of the word.","exampleCN":"这个名词提供词中「技艺」的一半。"},{"word":"-logia","structure":"-logia (Greek suffix)","meaning":"study, discourse","meaningCN":"学问；论述","example":"The suffix names a field of study.","exampleCN":"这个后缀指一个研究领域。"},{"word":"technology","structure":"tekhnē + -logia","meaning":"the study of arts; later tools and systems","meaningCN":"技艺研究；后指工具与系统","example":"Technology shifted from study to hardware.","exampleCN":"technology 从研究转向硬件。"},{"word":"technological","structure":"technology + -ical (relating to)","meaning":"relating to technology","meaningCN":"与技术相关的","example":"Technological change is fast.","exampleCN":"技术变化很快。"},{"word":"technique","structure":"tekhnē through French","meaning":"a way of doing something","meaningCN":"技巧；方法","example":"A technique is one method.","exampleCN":"技巧是一种方法。"},{"word":"ab","structure":"ab (Latin preposition)","meaning":"from, away","meaningCN":"从；离开","example":"The preposition begins the Latin phrase.","exampleCN":"这个介词开启拉丁短语。"},{"word":"ante","structure":"ante (Latin preposition)","meaning":"before","meaningCN":"在前","example":"The word names what stands before.","exampleCN":"这个词指在前之物。"},{"word":"abante","structure":"ab + ante (Latin adverb)","meaning":"from before","meaningCN":"从前方","example":"The adverb gave the verb of moving forward.","exampleCN":"这个副词衍生出向前移动的动词。"},{"word":"advance","structure":"abantiare through Old French avancier","meaning":"to move forward","meaningCN":"前进；推进","example":"Tools advance year by year.","exampleCN":"工具逐年推进。"},{"word":"advancement","structure":"advance + -ment (noun suffix)","meaning":"a moving forward; an improvement","meaningCN":"前进；提升","example":"Advancement can be measured.","exampleCN":"进步可以被衡量。"}],"derivatives":[{"word":"advanced","structure":"advance + -ed (past participle)","meaning":"having moved forward; highly developed","meaningCN":"先进的；高级的"},{"word":"advancing","structure":"advance + -ing (participle)","meaning":"moving forward","meaningCN":"正在推进的"},{"word":"technologically","structure":"technological + -ly (adverb)","meaning":"by means of technology","meaningCN":"在技术上"}],"latinEntries":[{"word":"tekhnē","structure":"tekhnē (Greek noun, first declension)","meaning":"art, craft, skill","meaningCN":"技艺；手艺"},{"word":"abante","structure":"ab + ante (Latin adverb)","meaning":"from before","meaningCN":"从前方"},{"word":"abantiare","structure":"abantiare (Vulgar Latin verb)","meaning":"to move forward","meaningCN":"向前移动"}]}},{"word":"advancement","ipa_uk":"/ədˈvɑːnsmənt/","ipa_us":"/ədˈvænsmənt/","definition_zh":"推进；进步；晋升；（款项的）预付","definition_en":"the act of moving something forward, or the state of having moved to a higher level","core_image":"一列人沿着同一道台阶往上走，有人换了更高的职位，有人把一叠钱先交到工地，台阶本身也在变高","scene":"一名学徒从擦工具做起，十年后坐到设计桌前，负责整条生产线。Her advancement from apprentice to chief engineer took ten years.","sceneCN":"这里 advancement 指「职位上的晋升」（第 2 个义项：地位或职级的提升）；句意为她从中学徒晋升为总工程师花了十年。可辨识物件：工具台、设计桌、工牌、生产线、台阶。","pos":[{"tag":"n.","zh":"推进；进步；提升"},{"tag":"n.","zh":"晋升；地位提高"},{"tag":"n.","zh":"预付；垫付的款项（较旧用法）"}],"collocations":[{"phrase":"career advancement","zh":"职业晋升"},{"phrase":"professional advancement","zh":"专业发展；职位提升"},{"phrase":"the advancement of knowledge","zh":"知识的进步"},{"phrase":"the advancement of science","zh":"科学的推进"},{"phrase":"advancement of funds","zh":"款项的预付"},{"phrase":"social advancement","zh":"社会地位提升"}],"forms":[{"label":"不可数用法（抽象进步）","form":"advancement"},{"label":"可数复数（具体提升）","form":"advancements"},{"label":"动词（推进；前进）","form":"advance"},{"label":"形容词（先进的）","form":"advanced"},{"label":"现在分词（正在推进的）","form":"advancing"}],"derivatives":[{"word":"advance","pos":"v./n.","zh":"推进；前进；预付款"},{"word":"advanced","pos":"adj.","zh":"先进的；高级的"},{"word":"advancing","pos":"adj.","zh":"正在推进的"},{"word":"advantage","pos":"n.","zh":"优势；有利条件（同源但语义分化）"},{"word":"advantageous","pos":"adj.","zh":"有利的"}],"senses":[{"no":"01","title":"Moving something forward","titleCN":"把事物向前推进","definition":"the act of pushing a process, project or cause forward","definitionCN":"推动进程、项目或事业向前的行为","example":"The advancement of the bridge project required a new survey.","exampleCN":"桥梁项目的推进需要一次新的勘测。","why":"Advancement is the noun of forward motion: something that stood still is made to move.","whyCN":"advancement 是向前运动的名称：原本停着的东西被推动起来。"},{"no":"02","title":"Promotion in rank","titleCN":"职位晋升","definition":"a rise to a higher position or grade in work","definitionCN":"在工作中升至更高职位或级别","example":"Her advancement from apprentice to chief engineer took ten years.","exampleCN":"她从中学徒晋升为总工程师花了十年。","why":"Careers are ladders in this idiom, so moving up a rung is naturally called advancement.","whyCN":"在这一比喻里职业是梯子，因此向上爬一级自然被称为晋升。"},{"no":"03","title":"Progress of knowledge or a cause","titleCN":"知识或事业的进步","definition":"the improvement or furthering of knowledge, science or a public cause","definitionCN":"知识、科学或公共事业的改善与推进","example":"The foundation works for the advancement of rural education.","exampleCN":"该基金会致力于推进乡村教育。","why":"Here the object is not a person but a body of knowledge, which is moved toward a better state.","whyCN":"这里对象不是人，而是一片知识，被推向更好的状态。"},{"no":"04","title":"A payment made ahead","titleCN":"预付的款项","definition":"money paid before it is due or before work is completed","definitionCN":"在到期或工作完成之前支付的款项","example":"The contractor received an advancement to buy materials.","exampleCN":"承包商收到一笔预付款用于购买材料。","why":"The financial sense keeps the original image of something sent forward before its time.","whyCN":"金融义保留原意象：某物在到期之前被提前送出。"},{"no":"05","title":"Forward movement of a body","titleCN":"队伍或部队的前进","definition":"the forward movement of troops, travellers or a moving body","definitionCN":"部队、旅人或移动队伍的前进","example":"The advancement of the column was slowed by rain.","exampleCN":"纵队的前进因雨而减慢。","why":"The oldest physical sense survives in military and formal writing, where bodies still move in formation.","whyCN":"最古老的物理义仍活在军事与正式文体中，那里的人仍成队形移动。"},{"no":"06","title":"Rise in social standing","titleCN":"社会地位的提升","definition":"an improvement in a person's or group's social position","definitionCN":"个人或群体社会位置的改善","example":"Education was the family's main route to social advancement.","exampleCN":"教育是这个家庭实现社会地位提升的主要途径。","why":"When the ladder is social rather than professional, the same noun names class mobility.","whyCN":"当梯子是社会性的而非职业性的，同一个名词就指阶层流动。"},{"no":"07","title":"Staged development of a project","titleCN":"项目按阶段推进","definition":"the step-by-step carrying of a plan through its stages","definitionCN":"计划按阶段逐步被推进","example":"The committee reviewed each advancement of the plan before releasing funds.","exampleCN":"委员会在放款前审查计划的每一步推进。","why":"Projects advance in stages, and the noun can name each step as well as the whole movement.","whyCN":"项目按阶段推进，这个名词既可指每一步，也可指整体运动。"},{"no":"08","title":"Approach to a better state","titleCN":"向更好状态靠近","definition":"the general movement of a thing toward a higher or better condition","definitionCN":"事物朝更高或更好状态的一般运动","example":"The essay measures advancement by health and freedom, not by output alone.","exampleCN":"这篇文章以健康与自由衡量进步，而非只看产出。","why":"The abstract sense asks 'better toward what?', which is why the word invites debate about standards.","whyCN":"抽象义会追问「向什么更好？」，因此这个词会引发关于标准的争论。"}],"etymology":{"intro":{"en":"Advancement joins advance, from Old French avancier and Vulgar Latin abantiare, with the noun suffix -ment. The Latin base is abante 'from before', from ab 'from' and ante 'before'. Dates are approximate.","cn":"advancement 由 advance 加名词后缀构成；advance 经古法语 avancier 来自俗拉丁 abantiare，其拉丁基础是 abante「从前方」，由 ab「从」与 ante「前」构成。年代均为约数。"},"items":[{"era":"LATIN ANTE","en":"Ante meant 'before, in front of'. Its deeper origin is not established.","cn":"ante 意为「在前、在……前面」。其更深来源未得到证明。"},{"era":"LATIN ABANTE","en":"Ab 'from' plus ante gave abante 'from before', an adverb of position in front.","cn":"ab「从」加 ante 构成 abante「从前方」，是表示前方位置的副词。"},{"era":"VULGAR LATIN ABANTIARE","en":"The vulgar verb abantiare developed the sense 'to move forward', and Old French avancier carried it onward.","cn":"俗拉丁动词 abantiare 发展出「向前移动」的意思，古法语 avancier 把它继续传下。"},{"era":"ENGLISH ADVANCE","en":"English advance appeared in the thirteenth century as a verb of moving forward, and later gained the financial sense of paying ahead.","cn":"英语 advance 在十三世纪出现，指向前移动的动词，后来获得提前付款的金融义。"},{"era":"NOUN ADVANCEMENT","en":"The noun advancement followed in the fourteenth century, naming the act of moving forward and later a rise in rank.","cn":"名词 advancement 随后在十四世纪出现，指向前移动的行为，后指职级提升。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest use of the noun is not precisely dated, and the deeper origin of ante is unsettled, so any older form is a reconstruction.","cn":"来源不确定（首见年代）：这个名词的最早书证年代不精确；ante 的更早来源亦无定论，凡更早形态均属重构形式。"}]},"similar":{"note":{"en":"Group one shares the forward-motion stem; group two names progress and promotion in other words.","cn":"第一组共享「向前运动」词干；第二组用其他词表达进步与晋升。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"advance","ipa":"/ədˈvɑːns/","tag":"verb and noun","definition":"The base word; as a noun it can also mean a payment ahead or a proposal.","definitionCN":"基础词；作名词时也可指预付款或提议。"},{"word":"advanced","ipa":"/ədˈvɑːnst/","tag":"adjective","definition":"Describes something already at a high stage, not the movement toward it.","definitionCN":"描述已处于高阶段的事物，而非朝它移动。"},{"word":"advancing","ipa":"/ədˈvɑːnsɪŋ/","tag":"participle","definition":"Describes something in motion or progressing now.","definitionCN":"描述正在移动或正在进步的事物。"},{"word":"advantage","ipa":"/ədˈvɑːntɪdʒ/","tag":"same root, different sense","definition":"From the same 'before' base but names a favourable position, not forward movement.","definitionCN":"同出「在前」的词基，却指有利位置，而非向前运动。"}]},{"heading":"NEAR MEANING","entries":[{"word":"progress","ipa":"/ˈprəʊɡres/","tag":"general improvement","definition":"The broad word for moving toward a better state; advancement often implies a deliberate push.","definitionCN":"指向更好状态移动的宽泛词；advancement 常含有人为推动。"},{"word":"promotion","ipa":"/prəˈməʊʃən/","tag":"a rise in rank","definition":"The specific act of moving to a higher job grade, one kind of advancement.","definitionCN":"指升到更高职级的具体行为，是 advancement 的一种。"},{"word":"development","ipa":"/dɪˈveləpmənt/","tag":"growth over time","definition":"Gradual growth or maturing, often of a project, person or economy.","definitionCN":"指随时间的逐步成长或成熟，常用于项目、人或经济。"},{"word":"furtherance","ipa":"/ˈfɜːðərəns/","tag":"helping forward","definition":"The act of helping a cause or plan move ahead, close to the first sense of advancement.","definitionCN":"指帮助事业或计划向前，接近 advancement 的第一个义项。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real contrasts, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实对比，而非编造的顺口溜。"},"normal":[{"en":"The Latin base is 'from before': to advance is to come forward from where you stood.","cn":"拉丁词基意为「从前方」：前进就是从原处向前来。"},{"en":"The family runs advance, advanced, advancing, advancement, advantage.","cn":"同族词包括 advance、advanced、advancing、advancement、advantage。"},{"en":"Fixed phrases: career advancement, the advancement of knowledge, advancement of funds.","cn":"固定搭配：职业晋升、知识的进步、款项预付。"},{"en":"The noun can be countable: several advancements in a field.","cn":"这个名词可数：一个领域中的多项进展。"},{"en":"Keep the financial sense in mind; it is old but still used in contracts.","cn":"记住金融义：它虽旧，仍在合同中使用。"}],"abstract":[{"en":"Picture a staircase where each step is a little higher than the last.","cn":"想象一道台阶，每一级都比上一级高一点。"},{"en":"Picture a hand pushing a stalled cart until it rolls again.","cn":"想象一只手推动停滞的车，直到它重新滚动。"},{"en":"Picture money handed over before the bricks arrive.","cn":"想象砖还没到，钱先递了过去。"}]},"examples":[{"en":"The society was founded for the advancement of natural history.","cn":"该学会为推进博物学而创立。"},{"en":"She turned down a promotion because the advancement would have moved her abroad.","cn":"她拒绝了晋升，因为那次提升会把她调往海外。"},{"en":"The contract specified an advancement of a quarter of the sum.","cn":"合同规定预付总额的四分之一。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「向前」加「名词」——向前走一步，职位、知识或款项都算","word":"advancement"},"root":"advance 经古法语 avancier 来自俗拉丁 abantiare，源于拉丁 abante「从前方」= ab（从）+ ante（前）；加名词后缀构成 advancement。ante 更早来源不确定。","sensesIntro":{"en":"Eight senses follow one forward push: a project moves, a worker rises, knowledge grows, money is paid ahead, a column marches, a family climbs socially, a plan clears its stages, and a society asks what 'better' means.","cn":"八个义项沿同一次推动展开：项目前进，职员上升，知识增长，款项预付，队伍行进，家庭向上流动，计划逐段通过，社会则追问「更好」指什么。"},"semanticMap":{"core":{"en":"CORE IMAGE: a staircase where each step is higher, and different people climb different flights.","cn":"核心意象：一道每级都更高的台阶，不同的人爬不同的段落。"},"chain":["FORWARD","RANK","KNOWLEDGE","MONEY","STATUS","BETTER STATE"],"branches":[{"senses":"01","en":"PLAIN MOTION: something stalled is made to move forward.","cn":"单纯运动：停滞之物被推动向前。"},{"senses":"02 · 05","en":"UP AND OUT: a career rises, and a column physically advances.","cn":"向上与向外：职业上升，队伍也实地前进。"},{"senses":"03 · 07","en":"CAUSE AND PLAN: knowledge is furthered, and a project clears its stages.","cn":"事业与计划：知识被推进，项目逐段通过。"},{"senses":"04","en":"MONEY: payment sent before its time keeps the original image of forward motion.","cn":"金钱：提前送出的款项保留「向前」的原意象。"},{"senses":"06 · 08","en":"SOCIAL LADDER: class mobility repeats the staircase, and the standard of 'better' is contested.","cn":"社会阶梯：阶层流动重复了台阶意象，而「更好」的标准仍被争论。"}]},"affixes":{"intro":{"en":"Advancement can be read from a Latin phrase meaning 'from before' and an English noun suffix.","cn":"advancement 可以按意为「从前方」的拉丁短语与英语名词后缀逐段读出。"},"latinIntro":{"en":"Latin ab and ante combine into abante, which through Vulgar Latin and French gives advance; -ment turns it into a noun.","cn":"拉丁 ab 与 ante 合成 abante，经俗拉丁与法语衍生 advance；-ment 把它变成名词。"},"items":[{"word":"ab","structure":"ab (Latin preposition)","meaning":"from, away","meaningCN":"从；离开","example":"The preposition begins the phrase.","exampleCN":"这个介词开启短语。"},{"word":"ante","structure":"ante (Latin preposition)","meaning":"before, in front of","meaningCN":"在前；在……前面","example":"The word names the position ahead.","exampleCN":"这个词指前方位置。"},{"word":"abante","structure":"ab + ante (Latin adverb)","meaning":"from before","meaningCN":"从前方","example":"The adverb gave the verb of moving forward.","exampleCN":"这个副词衍生出向前移动的动词。"},{"word":"abantiare","structure":"abantiare (Vulgar Latin verb)","meaning":"to move forward","meaningCN":"向前移动","example":"The vulgar verb carried the action.","exampleCN":"俗拉丁动词承载这个动作。"},{"word":"advance","structure":"abantiare through Old French avancier","meaning":"to move forward; to pay ahead","meaningCN":"前进；预付","example":"Advance has both motion and money senses.","exampleCN":"advance 兼有运动与金钱义。"},{"word":"-ment","structure":"-ment (noun suffix, from Latin -mentum)","meaning":"an action or result","meaningCN":"动作或结果","example":"The suffix makes the verb a noun.","exampleCN":"这个后缀把动词变成名词。"},{"word":"advancement","structure":"advance + -ment","meaning":"a moving forward; a rise","meaningCN":"推进；晋升","example":"Advancement can be career or knowledge.","exampleCN":"advancement 可以是职业或知识。"},{"word":"advanced","structure":"advance + -ed (past participle)","meaning":"having moved far forward","meaningCN":"先进的；高级的","example":"Advanced tools are far along the line.","exampleCN":"先进工具处在这条线的前端。"},{"word":"advancing","structure":"advance + -ing (participle)","meaning":"moving forward now","meaningCN":"正在推进的","example":"The advancing team gained ground.","exampleCN":"推进中的队伍取得进展。"},{"word":"advantage","structure":"abante through Old French avantage","meaning":"a position in front; a benefit","meaningCN":"优势；有利条件","example":"Advantage keeps the 'front' image.","exampleCN":"advantage 保留「在前」的意象。"}],"derivatives":[{"word":"advanced","structure":"advance + -ed (participle)","meaning":"far forward in development","meaningCN":"先进的"},{"word":"advancing","structure":"advance + -ing (participle)","meaning":"in forward motion","meaningCN":"正在推进的"},{"word":"advantageous","structure":"advantage + -ous (adjective)","meaning":"giving a benefit","meaningCN":"有利的"}],"latinEntries":[{"word":"abante","structure":"ab + ante (Latin adverb)","meaning":"from before","meaningCN":"从前方"},{"word":"abantiare","structure":"abantiare (Vulgar Latin verb)","meaning":"to move forward","meaningCN":"向前移动"},{"word":"ante","structure":"ante (Latin preposition)","meaning":"before, in front of","meaningCN":"在前；在……前面"}]}},{"word":"social transformation","ipa_uk":"/ˌsəʊʃəl trænsfəˈmeɪʃən/","ipa_us":"/ˌsoʊʃəl trænsfɔːrˈmeɪʃən/","definition_zh":"社会转型；社会结构、制度与生活方式发生的深层整体变化","definition_en":"a deep and wide change in the structure, institutions or daily life of a society","core_image":"同一座城镇的旧地图与新地图叠在一起，码头、工厂、住宅区与道路的位置全部换了","scene":"一个靠捕鱼为生的小镇，在港口扩建与工厂进驻后，家庭分工与婚俗都变了。The fishing town underwent a social transformation after the new port opened.","sceneCN":"这里 social transformation 指「社会结构层面的深层转变」（第 1 个义项：整体社会形态的转型）；句意为新港口开通后，这座渔镇经历了社会转型。可辨识物件：旧地图、新地图、渔港、工厂、住宅区、婚礼服饰。","pos":[{"tag":"n.","zh":"社会转型（常作不可数）"},{"tag":"n.","zh":"一次具体的社会转型（可数）"}],"collocations":[{"phrase":"rapid social transformation","zh":"快速的社会转型"},{"phrase":"social transformation and development","zh":"社会转型与发展"},{"phrase":"a process of social transformation","zh":"社会转型的过程"},{"phrase":"undergo social transformation","zh":"经历社会转型"},{"phrase":"industrial social transformation","zh":"工业社会转型"},{"phrase":"the agents of social transformation","zh":"社会转型的推动者"}],"forms":[{"label":"不可数用法（整体过程）","form":"social transformation"},{"label":"可数复数（具体转型）","form":"social transformations"},{"label":"形容词（社会的）","form":"social"},{"label":"名词（转型）","form":"transformation"},{"label":"动词（使转型）","form":"transform"},{"label":"形容词（转型的）","form":"transformative"}],"derivatives":[{"word":"transform","pos":"v.","zh":"改变；使转型"},{"word":"transformation","pos":"n.","zh":"转型；转变"},{"word":"transformative","pos":"adj.","zh":"有转型作用的"},{"word":"social","pos":"adj.","zh":"社会的"},{"word":"society","pos":"n.","zh":"社会"},{"word":"socially","pos":"adv.","zh":"在社会层面"}],"senses":[{"no":"01","title":"Structural change of a society","titleCN":"社会结构的整体转变","definition":"a deep change in the way a society is organised, including its classes, work and families","definitionCN":"社会组织的深层变化，包括阶层、工作与家庭","example":"The fishing town underwent a social transformation after the new port opened.","exampleCN":"新港口开通后，这座渔镇经历了社会转型。","why":"Transformation is a change of form, so the phrase points to a new shape of society rather than a single new law.","whyCN":"transformation 是形态的改变，因此这个短语指向社会的新形态，而非某一条新法律。"},{"no":"02","title":"Institutional transformation","titleCN":"制度转型","definition":"a change in the rules, organisations and offices that govern a society","definitionCN":"治理社会的规则、组织与机构发生变化","example":"Land reform was the first step in the country's social transformation.","exampleCN":"土地改革是这个国家社会转型的第一步。","why":"Institutions are the skeleton of society; when they are rebuilt, the change outlasts any single government.","whyCN":"制度是社会的骨架；骨架重建后，变化会比任何一届政府都长久。"},{"no":"03","title":"Industrial and urban transformation","titleCN":"工业化与城市化驱动的转型","definition":"the reshaping of work and settlement that follows industry and urban growth","definitionCN":"随工业与城市增长而来的工作与居住形态重塑","example":"Industrialisation drove a social transformation that moved families from fields to factories.","exampleCN":"工业化推动了一场社会转型，把家庭从田地移向工厂。","why":"Machines and cities are the usual engines: they change where people live and what they do.","whyCN":"机器与城市是常见引擎：它们改变人住在哪里、做什么。"},{"no":"04","title":"Change in values and daily life","titleCN":"价值与日常生活的变化","definition":"a shift in beliefs, habits and expectations about family, work and status","definitionCN":"关于家庭、工作与地位的信念、习惯与期待发生转变","example":"The social transformation showed first in smaller households and later marriages.","exampleCN":"这场社会转型最先表现在家庭变小与晚婚上。","why":"Numbers and habits are where deep change becomes visible, long before any constitution is rewritten.","whyCN":"数字与习惯是深层变化显现之处，远早于宪法被改写。"},{"no":"05","title":"A planned programme of change","titleCN":"有计划的改造工程","definition":"a deliberate campaign by a state or movement to remake society","definitionCN":"国家或运动有意识地重塑社会","example":"The literacy campaign was part of a wider social transformation.","exampleCN":"扫盲运动是更广泛社会转型的一部分。","why":"The phrase can name a project with agents and targets, not only an unplanned drift.","whyCN":"这个短语可以指有推动者与目标的项目，而不只是无意的漂移。"},{"no":"06","title":"Digital transformation of social life","titleCN":"社会生活的数字化转型","definition":"the reshaping of communication, work and services by digital networks","definitionCN":"数字网络对通信、工作与服务的重塑","example":"Mobile payment brought a quiet social transformation to market stalls.","exampleCN":"移动支付给菜市场带来一场安静的社会转型。","why":"Each technology wave produces its own version of the phrase, and digital networks are the current one.","whyCN":"每一波技术都会产生自己版本的这一短语，数字网络是当前的一版。"},{"no":"07","title":"Dislocation and unequal costs","titleCN":"失序与不均衡代价","definition":"the disruption and uneven burdens that accompany deep change","definitionCN":"深层变化伴随的失序与不均衡负担","example":"The social transformation enriched the coast while emptying the inland villages.","exampleCN":"这场社会转型让沿海富裕，却让内陆村庄空心化。","why":"Deep change redistributes not only benefits but also losses, and the phrase often carries that ledger.","whyCN":"深层变化不只重新分配收益，也分配损失，这个短语常带着这本账。"},{"no":"08","title":"Shift from one social form to another","titleCN":"从一种社会形态转到另一种","definition":"the abstract passage of a society from one organised form to another","definitionCN":"社会从一种组织形态过渡到另一种","example":"Historians describe the social transformation as a change of form, not a change of fashion.","exampleCN":"历史学家把这场社会转型描述为形态的改变，而非风尚的改变。","why":"The abstract sense keeps the Latin image of form: a society is reshaped, as clay is reshaped.","whyCN":"抽象义保留拉丁「形状」的意象：社会被重新塑造，如同黏土被重新塑形。"}],"etymology":{"intro":{"en":"Social transformation joins social, from Latin socius 'companion, ally', with transformation, from Late Latin transformatio, built on trans- 'across' and forma 'shape'. Dates are approximate.","cn":"social transformation 由 social 与 transformation 合成：social 来自拉丁 socius「同伴、盟友」；transformation 来自晚期拉丁 transformatio，由 trans-「越过」与 forma「形状」构成。年代均为约数。"},"items":[{"era":"LATIN SOCIUS","en":"Socius meant 'companion, ally, partner'. It is generally connected with sequi 'to follow', but that link is a hypothesis and the pre-Latin form is reconstructed.","cn":"socius 意为「同伴、盟友、伙伴」。一般认为与 sequi「跟随」有关，但这一联系只是假说，拉丁语之前的形态属重构形式。"},{"era":"LATIN FORMA","en":"Forma meant 'shape, form, mould'. Its deeper origin is not established.","cn":"forma 意为「形状、形态、模子」。其更深来源未得到证明。"},{"era":"LATIN TRANSFORMATIO","en":"Trans- 'across' plus forma produced transformare 'to change the shape of', and the noun transformatio named the change.","cn":"trans-「越过」加 forma 构成 transformare「改变形状」，名词 transformatio 指这种改变。"},{"era":"ENGLISH TRANSFORMATION","en":"English transformation entered in the fourteenth century through French, first as a change of form or appearance.","cn":"英语 transformation 在十四世纪经法语进入，最初指形状或外观的改变。"},{"era":"MODERN SOCIAL USE","en":"Social science applied the phrase to deep structural change in the nineteenth and twentieth centuries, often alongside industrialisation.","cn":"社会科学在十九与二十世纪把这个短语用于深层结构变化，常与工业化并提。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the first use of the exact phrase is not fixed, and the link of socius to sequi is a hypothesis rather than a demonstrated derivation.","cn":"来源不确定（首见年代）：这个确切短语的最早使用无法确定；socius 与 sequi 的联系只是假说，并非已证实的派生。"}]},"similar":{"note":{"en":"Group one shares the two stems; group two holds other names for societies changing.","cn":"第一组共享两个词干；第二组是用其他名称表达社会变化。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"social","ipa":"/ˈsəʊʃəl/","tag":"the adjective","definition":"Relating to society; it marks the field, not the change.","definitionCN":"与社会相关；标记领域，而非变化。"},{"word":"society","ipa":"/səˈsaɪəti/","tag":"the noun","definition":"The organised group itself; transformation is what happens to it.","definitionCN":"指组织起来的群体本身；转型是它经历的事。"},{"word":"transformation","ipa":"/trænsfəˈmeɪʃən/","tag":"the bare noun","definition":"A change of form in anything; the phrase narrows it to society.","definitionCN":"指任何事物的形态变化；短语把它限定到社会。"},{"word":"transform","ipa":"/trænsˈfɔːm/","tag":"the verb","definition":"To change the form of something; it can be used of clay, data or a society.","definitionCN":"指改变某物的形态；可用于黏土、数据或社会。"}]},{"heading":"NEAR MEANING","entries":[{"word":"social change","ipa":"/ˌsəʊʃəl ˈtʃeɪndʒ/","tag":"broader and neutral","definition":"Any alteration in social life; transformation stresses depth and a new shape.","definitionCN":"指社会生活中的任何改变；转型强调深度与新形态。"},{"word":"transition","ipa":"/trænˈzɪʃən/","tag":"passing between states","definition":"The passage from one state to another, often without implying a better end.","definitionCN":"指从一种状态过渡到另一种，常不暗示更好的终点。"},{"word":"reform","ipa":"/rɪˈfɔːm/","tag":"planned repair","definition":"A deliberate improvement of institutions, usually within the existing form.","definitionCN":"指对制度的有意改良，通常在既有形态内进行。"},{"word":"modernization","ipa":"/ˌmɒdənaɪˈzeɪʃən/","tag":"becoming modern","definition":"A specific historical direction of change, while transformation can go in any direction.","definitionCN":"指一个特定的历史变化方向，而转型可以朝任何方向。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real contrasts, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实对比，而非编造的顺口溜。"},"normal":[{"en":"Trans- is across and forma is shape: a transformation is a change of shape.","cn":"trans- 是越过，forma 是形状：transformation 就是形状的改变。"},{"en":"The family runs social, society, socially, transform, transformation, transformative.","cn":"同族词包括 social、society、socially、transform、transformation、transformative。"},{"en":"Fixed phrases: rapid social transformation, undergo social transformation.","cn":"固定搭配：快速的社会转型、经历社会转型。"},{"en":"Distinguish it from social change: change is any alteration, transformation is deep and structural.","cn":"与 social change 区分：change 是任何改变，transformation 是深层结构性的。"},{"en":"The phrase often appears with industry, ports, cities and generations.","cn":"这个短语常与工业、港口、城市与代际连用。"}],"abstract":[{"en":"Picture two maps of one town laid on top of each other.","cn":"想象同一座城镇的两张地图叠在一起。"},{"en":"Picture a harbour where fishing boats give way to container cranes.","cn":"想象一个港口，渔船让位给集装箱吊机。"},{"en":"Picture clay being pressed into a new mould and keeping the fingerprints.","cn":"想象黏土被压进新模子，却留下指纹。"}]},"examples":[{"en":"The social transformation of the valley began with a road and ended with a new generation.","cn":"这个山谷的社会转型始于一条路，终于新一代人。"},{"en":"Economists measure social transformation by employment, education and household size.","cn":"经济学家用就业、教育与家庭规模衡量社会转型。"},{"en":"A social transformation can be welcomed and resisted in the same town.","cn":"同一座城镇里，社会转型可以同时被欢迎与被抵制。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「social（社会的）+ transformation（变形）」——整个社会换了一副骨架","word":"social transformation"},"root":"social 来自拉丁 socius「同伴、盟友」，一般认为与 sequi「跟随」有关，但属假说；transformation 来自晚期拉丁 transformatio = trans-（越过）+ forma（形状）。更早形态均为重构。","sensesIntro":{"en":"Eight senses follow one reshaping: structures change, institutions are rebuilt, industry and cities move people, values shift, programmes are launched, digital networks spread, costs are unevenly borne, and the society ends in a new form.","cn":"八个义项沿同一次重塑展开：结构改变，制度重建，工业与城市迁移人口，价值转变，改造项目启动，数字网络铺开，代价分配不均，社会最终呈现新形态。"},"semanticMap":{"core":{"en":"CORE IMAGE: two maps of one town laid on top of each other, with harbour, factories and homes all moved.","cn":"核心意象：同一座城镇的两张地图叠在一起，港口、工厂与住宅都换了位置。"},"chain":["DEEP CHANGE","STRUCTURE","INSTITUTIONS","INDUSTRY","VALUES","COST"],"branches":[{"senses":"01 · 08","en":"FORM ITSELF: deep change is a new shape, not a new fashion.","cn":"形态本身：深层变化是新形状，而非新风尚。"},{"senses":"02","en":"SKELETON: institutions are rebuilt and outlast governments.","cn":"骨架：制度被重建，且比政府更长久。"},{"senses":"03 · 06","en":"ENGINES: industry, cities and digital networks each move people and work.","cn":"引擎：工业、城市与数字网络各自迁移人口与工作。"},{"senses":"04","en":"DAILY LIFE: households and marriages show the change before documents do.","cn":"日常生活：家庭与婚姻比文件更早显现变化。"},{"senses":"05 · 07","en":"PLAN AND LEDGER: a campaign can drive change, and the losses are distributed unevenly.","cn":"计划与账本：运动可以推动变化，损失却分配不均。"}]},"affixes":{"intro":{"en":"The phrase can be read from a Latin noun for a companion and a Latin verb of changing shape.","cn":"这个短语可以按表示同伴的拉丁名词与表示改变形状的拉丁动词读出。"},"latinIntro":{"en":"Latin socius supplies social, society and associate; Latin forma supplies form, format and transformation, with trans- adding the change.","cn":"拉丁 socius 衍生 social、society 与 associate；拉丁 forma 衍生 form、format 与 transformation，trans- 增添变化。"},"items":[{"word":"socius","structure":"socius, socii (Latin noun)","meaning":"companion, ally, partner","meaningCN":"同伴；盟友；伙伴","example":"The noun supplies the social half.","exampleCN":"这个名词提供「社会」的一半。"},{"word":"social","structure":"socius + -al (relating to)","meaning":"relating to society","meaningCN":"与社会相关的","example":"Social relations are reshaped.","exampleCN":"社会关系被重塑。"},{"word":"society","structure":"societas through Old French","meaning":"an organised community","meaningCN":"有组织的社会","example":"Society changes form.","exampleCN":"社会改变形态。"},{"word":"forma","structure":"forma, formae (Latin noun)","meaning":"shape, form, mould","meaningCN":"形状；形态；模子","example":"The noun supplies the image of shape.","exampleCN":"这个名词提供形状意象。"},{"word":"trans-","structure":"trans- (Latin prefix)","meaning":"across, beyond","meaningCN":"越过；穿过","example":"The prefix marks change from one form to another.","exampleCN":"这个前缀标记从一种形态到另一种。"},{"word":"transformare","structure":"trans- + forma (Latin verb)","meaning":"to change the shape of","meaningCN":"改变形状","example":"The verb names reshaping.","exampleCN":"这个动词指重新塑形。"},{"word":"transformation","structure":"transformare + -ation (process noun)","meaning":"a change of form","meaningCN":"形态的改变","example":"The noun names the change.","exampleCN":"这个名词指这种改变。"},{"word":"transform","structure":"transformare through French","meaning":"to change the form of","meaningCN":"改变形态；使转型","example":"Industry transformed the town.","exampleCN":"工业改变了这座城镇。"},{"word":"transformative","structure":"transform + -ative (tending to)","meaning":"causing deep change","meaningCN":"有转型作用的","example":"The experience was transformative.","exampleCN":"这段经历具有转型作用。"},{"word":"social transformation","structure":"social + transformation","meaning":"a deep change in society's form","meaningCN":"社会形态的深层变化","example":"The port brought social transformation.","exampleCN":"港口带来社会转型。"}],"derivatives":[{"word":"transform","structure":"transformare through French (verb)","meaning":"to change the form of","meaningCN":"改变形态"},{"word":"transformative","structure":"transform + -ative (adjective)","meaning":"tending to cause deep change","meaningCN":"有转型作用的"},{"word":"socially","structure":"social + -ly (adverb)","meaning":"in social terms","meaningCN":"在社会层面"}],"latinEntries":[{"word":"socius","structure":"socius, socii (m., second declension)","meaning":"companion, ally","meaningCN":"同伴；盟友"},{"word":"forma","structure":"forma, formae (f., first declension)","meaning":"shape, form","meaningCN":"形状；形态"},{"word":"transformatio","structure":"transformatio, transformationis (f., third declension)","meaning":"a change of form","meaningCN":"形态的改变"}]}},{"word":"social change","ipa_uk":"/ˌsəʊʃəl ˈtʃeɪndʒ/","ipa_us":"/ˌsoʊʃəl ˈtʃeɪndʒ/","definition_zh":"社会变迁；社会关系、制度、文化与生活方式发生的任何改变","definition_en":"any alteration in social relationships, institutions, culture or ways of life","core_image":"一条老街的招牌、住户、通勤方式与家庭人数逐年不同，街还在，内容却一层层换了","scene":"街上的店铺换了招牌，家庭规模变小，通勤方式也从自行车变成地铁。Rising rents and new jobs brought rapid social change to the old neighbourhood.","sceneCN":"这里 social change 指「社会关系与生活方式的变化」（第 1 个义项：社会变迁的广义总称）；句意为租金上涨与新工作给老街区带来了快速的社会变迁。可辨识物件：店铺招牌、住宅楼、自行车、地铁入口、家庭合影。","pos":[{"tag":"n.","zh":"社会变迁（常作不可数）"},{"tag":"n.","zh":"一次具体的社会变化（可数）"}],"collocations":[{"phrase":"rapid social change","zh":"快速的社会变迁"},{"phrase":"social change and development","zh":"社会变迁与发展"},{"phrase":"a driver of social change","zh":"社会变迁的推动因素"},{"phrase":"the direction of social change","zh":"社会变迁的方向"},{"phrase":"social change in rural areas","zh":"乡村地区的社会变迁"},{"phrase":"adapt to social change","zh":"适应社会变迁"}],"forms":[{"label":"不可数用法（整体过程）","form":"social change"},{"label":"可数复数（具体变化）","form":"social changes"},{"label":"形容词（社会的）","form":"social"},{"label":"名词（变化）","form":"change"},{"label":"动词（改变）","form":"change"},{"label":"形容词（变化的）","form":"changing"}],"derivatives":[{"word":"change","pos":"n./v.","zh":"变化；改变"},{"word":"changing","pos":"adj.","zh":"正在变化的"},{"word":"changed","pos":"adj.","zh":"已改变的"},{"word":"social","pos":"adj.","zh":"社会的"},{"word":"society","pos":"n.","zh":"社会"},{"word":"socially","pos":"adv.","zh":"在社会层面"}],"senses":[{"no":"01","title":"Any alteration in society","titleCN":"社会中的任何改变","definition":"any alteration in social relationships, institutions or daily life","definitionCN":"社会关系、制度或日常生活中的任何改变","example":"Rising rents and new jobs brought rapid social change to the old neighbourhood.","exampleCN":"租金上涨与新工作给老街区带来了快速的社会变迁。","why":"Change is the widest word for becoming different, and social limits it to the life people share.","whyCN":"change 是「变得不同」最宽泛的词，social 把它限定到人们共享的生活。"},{"no":"02","title":"Gradual reform","titleCN":"渐进式改革","definition":"slow alteration through policy, law or habit rather than sudden rupture","definitionCN":"通过政策、法律或习惯缓慢改变，而非突然断裂","example":"Social change in the school system came one grade at a time.","exampleCN":"学校制度的社会变迁是一级一级来的。","why":"Reform is change that keeps the frame while adjusting its parts, which is why it is often called gradual.","whyCN":"改革是保留框架、调整部件的变化，因此常被称作渐进。"},{"no":"03","title":"Abrupt or revolutionary change","titleCN":"突变或革命式变化","definition":"sudden and fundamental alteration, often through conflict or crisis","definitionCN":"突然而根本的改变，常经冲突或危机而来","example":"The fall of the old regime produced social change within a single year.","exampleCN":"旧政权的垮台在一年之内造成了社会变迁。","why":"The same noun covers rupture: when the frame itself breaks, change arrives all at once.","whyCN":"同一个名词也覆盖断裂：当框架本身破碎，变化会一次到来。"},{"no":"04","title":"Demographic change","titleCN":"人口结构变化","definition":"change in birth rates, migration, household size or age structure","definitionCN":"出生率、迁移、家庭规模或年龄结构的变化","example":"Falling birth rates were the quietest social change of the century.","exampleCN":"出生率下降是一个世纪里最安静的社会变迁。","why":"People are the substance of society, so a change in who lives where is a change in society itself.","whyCN":"人是社会的实质，因此谁住在哪里的变化就是社会本身的变化。"},{"no":"05","title":"Technology-driven change","titleCN":"技术驱动的变化","definition":"change in work, communication and daily habits caused by new tools","definitionCN":"新工具引起的工作、通信与日常习惯变化","example":"The mobile phone brought social change to queues, markets and family dinners.","exampleCN":"手机给排队、市场与家庭晚餐带来了社会变迁。","why":"Tools rearrange the small routines that hold a society together, which makes them engines of change.","whyCN":"工具重排维系社会的细小惯例，因此成为变化的引擎。"},{"no":"06","title":"Cultural and value change","titleCN":"文化与价值的变化","definition":"change in beliefs, norms, tastes and expectations","definitionCN":"信念、规范、品味与期待的变化","example":"Social change showed in what families expected daughters to do.","exampleCN":"社会变迁体现在家庭对女儿的期待上。","why":"Values change more slowly than tools, but when they do, the change reaches every institution.","whyCN":"价值比工具变得慢，但一旦改变，就会触及每个制度。"},{"no":"07","title":"Institutional and policy change","titleCN":"制度与政策的变化","definition":"change in laws, organisations and public provision","definitionCN":"法律、组织与公共供给的变化","example":"A new pension law produced social change for three generations at once.","exampleCN":"一项新的养老金法一次改变了三代人的社会处境。","why":"Policy is deliberate change from above; it can be fast and visible, even when habits lag behind.","whyCN":"政策是从上而下的有意改变；它可以迅速可见，即便习惯仍滞后。"},{"no":"08","title":"Change in the pattern of relationships","titleCN":"关系格局的改变","definition":"a shift in how people connect, marry, work together or care for one another","definitionCN":"人们在联结、婚姻、合作与照料方式上的转变","example":"The census recorded social change in who lived alone and who shared a roof.","exampleCN":"人口普查记录了谁独居、谁同住的社会变迁。","why":"The abstract sense reduces change to its pattern: not one event, but a new arrangement of ties.","whyCN":"抽象义把变化还原为格局：不是单一事件，而是关系的新排布。"}],"etymology":{"intro":{"en":"Social change joins social, from Latin socius 'companion, ally', with change, from Old French changier and Late Latin cambiare 'to exchange'. The deeper origin of cambiare is uncertain. Dates are approximate.","cn":"social change 由 social 与 change 合成：social 来自拉丁 socius「同伴、盟友」；change 经古法语 changier 来自晚期拉丁 cambiare「交换」。cambiare 的更深来源不确定。年代均为约数。"},"items":[{"era":"LATIN SOCIUS","en":"Socius meant 'companion, ally'. It is generally connected with sequi 'to follow', but that link is a hypothesis and the pre-Latin form is reconstructed.","cn":"socius 意为「同伴、盟友」。一般认为与 sequi「跟随」有关，但这一联系只是假说，拉丁语之前的形态属重构形式。"},{"era":"LATIN CAMBIARE","en":"Cambiare meant 'to exchange, barter'. Its deeper origin is uncertain; it is sometimes said to be Gaulish, but that is not established.","cn":"cambiare 意为「交换、以物易物」。其更深来源不确定，有时被认为来自高卢语，但未得到证实。"},{"era":"OLD FRENCH CHANGIER","en":"Old French changier developed the sense 'to alter, become different' from the idea of exchanging one state for another.","cn":"古法语 changier 从「把一种状态换成另一种」发展出「改变、变得不同」的意思。"},{"era":"ENGLISH CHANGE","en":"English change appeared in the thirteenth century, covering both exchange and alteration.","cn":"英语 change 在十三世纪出现，兼指交换与改变。"},{"era":"MODERN PHRASE","en":"The phrase social change became standard in sociology in the nineteenth and twentieth centuries as a neutral name for any alteration in society.","cn":"social change 在十九与二十世纪成为社会学的标准说法，作为社会任何变化的中性名称。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the first use of the exact phrase is not fixed, and the origin of cambiare is unsettled, so any earlier form is a reconstruction.","cn":"来源不确定（首见年代与更深词源）：这个确切短语的最早使用无法确定；cambiare 的来源亦无定论，凡更早形态均属重构形式。"}]},"similar":{"note":{"en":"Group one shares the two stems; group two holds stronger or narrower names for change.","cn":"第一组共享两个词干；第二组是更强或更窄的变化名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"change","ipa":"/tʃeɪndʒ/","tag":"the base noun","definition":"Any becoming different; social limits it to shared life.","definitionCN":"指任何变得不同；social 把它限定到共同生活。"},{"word":"exchange","ipa":"/ɪksˈtʃeɪndʒ/","tag":"same Latin root","definition":"A giving and receiving of one thing for another; it is a doublet of change but no longer means alteration.","definitionCN":"指以一物换另一物；它是 change 的同源双式词，但不再指改变。"},{"word":"social","ipa":"/ˈsəʊʃəl/","tag":"the adjective","definition":"Relating to society; it marks the field of the change.","definitionCN":"与社会相关；标记变化的领域。"},{"word":"society","ipa":"/səˈsaɪəti/","tag":"the noun","definition":"The organised community that undergoes the change.","definitionCN":"指经历变化的组织化社群。"}]},{"heading":"NEAR MEANING","entries":[{"word":"social transformation","ipa":"/ˌsəʊʃəl trænsfəˈmeɪʃən/","tag":"deeper change","definition":"A change of social form, deeper than ordinary change and often structural.","definitionCN":"指社会形态的改变，比一般变化更深，常是结构性的。"},{"word":"reform","ipa":"/rɪˈfɔːm/","tag":"planned repair","definition":"A deliberate improvement within the existing order, a species of gradual social change.","definitionCN":"指在既有秩序内的有意改良，是渐进社会变迁的一种。"},{"word":"evolution","ipa":"/ˌiːvəˈluːʃən/","tag":"slow unfolding","definition":"Gradual development over time, often without design.","definitionCN":"指随时间缓慢展开，常无设计。"},{"word":"upheaval","ipa":"/ʌpˈhiːvəl/","tag":"violent disruption","definition":"Sudden, disruptive change that overturns ordinary life.","definitionCN":"指突然而破坏性的变化，颠覆日常生活。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real contrasts, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实对比，而非编造的顺口溜。"},"normal":[{"en":"Social comes from a word for companion; change came from a word for exchange.","cn":"social 来自表示同伴的词；change 来自表示交换的词。"},{"en":"The family runs social, society, socially, change, changing, changed.","cn":"同族词包括 social、society、socially、change、changing、changed。"},{"en":"Fixed phrases: rapid social change, a driver of social change, adapt to social change.","cn":"固定搭配：快速的社会变迁、社会变迁的推动因素、适应社会变迁。"},{"en":"Remember the scale: change is the broad term; transformation is the deep, structural one.","cn":"记住尺度：change 是宽泛术语；transformation 是深层结构性的。"},{"en":"The phrase can be countable: several social changes in one decade.","cn":"这个短语可数：十年间的多项社会变化。"}],"abstract":[{"en":"Picture the same street with new signs, new residents and a new way to get to work.","cn":"想象同一条街换了招牌、住户与通勤方式。"},{"en":"Picture a family photograph where the number of people keeps shrinking.","cn":"想象一张家庭合影，人数一代比一代少。"},{"en":"Picture a queue that no longer needs to stand still.","cn":"想象一支不再需要站定的队伍。"}]},"examples":[{"en":"Social change is often measured by schooling, income and household size.","cn":"社会变迁常以教育、收入与家庭规模衡量。"},{"en":"The factory closure caused social change faster than any policy could direct.","cn":"工厂关闭引发的社会变迁比任何政策引导都快。"},{"en":"Demographers study social change through the stories told by birth rates.","cn":"人口学家通过出生率讲述的故事研究社会变迁。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「social（社会的）+ change（变化）」——社会这层皮一直在换，但换得慢的时候最难看见","word":"social change"},"root":"social 来自拉丁 socius「同伴、盟友」，一般认为与 sequi「跟随」有关，属假说；change 经古法语 changier 来自晚期拉丁 cambiare「交换」，cambiare 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one alteration: society may change slowly, suddenly, in its numbers, through tools, in its values, by law, and finally in the pattern of its relationships.","cn":"八个义项沿同一次改变展开：社会可以缓慢地变、突然地变、在人口数字上变、经工具而变、在价值上变、由法律而变，最后在关系格局上变。"},"semanticMap":{"core":{"en":"CORE IMAGE: the same street with different signs, residents, family sizes and ways of getting to work.","cn":"核心意象：同一条街，招牌、住户、家庭人数与通勤方式都不同了。"},"chain":["ALTERATION","GRADUAL","ABRUPT","DEMOGRAPHY","TECHNOLOGY","CULTURE"],"branches":[{"senses":"01","en":"THE WIDEST WORD: any becoming different counts.","cn":"最宽的词：任何变得不同都算。"},{"senses":"02 · 07","en":"SLOW AND DELIBERATE: reform adjusts the frame, policy changes it from above.","cn":"缓慢与有意：改革调整框架，政策从上而下改变框架。"},{"senses":"03","en":"RUPTURE: when the frame breaks, change arrives at once.","cn":"断裂：框架破碎时，变化一次到来。"},{"senses":"04 · 05","en":"PEOPLE AND TOOLS: who lives where, and what they use, are two engines.","cn":"人与工具：谁住在哪里、用什么，是两台引擎。"},{"senses":"06 · 08","en":"VALUES AND TIES: beliefs shift slowly, and relationships rearrange.","cn":"价值与关系：信念慢慢移动，关系重新排布。"}]},"affixes":{"intro":{"en":"The phrase can be read from a Latin noun for a companion and a Latin verb of exchanging.","cn":"这个短语可以按表示同伴的拉丁名词与表示交换的拉丁动词读出。"},"latinIntro":{"en":"Latin socius supplies social, society and associate; Latin cambiare, through French, supplies change and exchange.","cn":"拉丁 socius 衍生 social、society 与 associate；拉丁 cambiare 经法语衍生 change 与 exchange。"},"items":[{"word":"socius","structure":"socius, socii (Latin noun)","meaning":"companion, ally","meaningCN":"同伴；盟友","example":"The noun supplies the social half.","exampleCN":"这个名词提供「社会」的一半。"},{"word":"social","structure":"socius + -al (relating to)","meaning":"relating to society","meaningCN":"与社会相关的","example":"Social ties are rearranged.","exampleCN":"社会关系被重排。"},{"word":"society","structure":"societas through Old French","meaning":"an organised community","meaningCN":"有组织的社会","example":"Society is the thing that changes.","exampleCN":"社会是发生变化之物。"},{"word":"cambiare","structure":"cambiare (Late Latin verb)","meaning":"to exchange, barter","meaningCN":"交换；以物易物","example":"The verb is the base of change.","exampleCN":"这个动词是 change 的基础。"},{"word":"change","structure":"cambiare through Old French changier","meaning":"to alter; to exchange","meaningCN":"改变；交换","example":"One state is exchanged for another.","exampleCN":"一种状态被换成另一种。"},{"word":"changing","structure":"change + -ing (participle)","meaning":"altering now","meaningCN":"正在变化的","example":"A changing street tells the story.","exampleCN":"一条变化的街道讲述这个故事。"},{"word":"changed","structure":"change + -ed (participle)","meaning":"already altered","meaningCN":"已改变的","example":"The changed household is smaller.","exampleCN":"改变后的家庭更小。"},{"word":"social change","structure":"social + change","meaning":"alteration in shared life","meaningCN":"社会生活的改变","example":"The phrase names the field.","exampleCN":"这个短语命名这一领域。"},{"word":"-al","structure":"-al (adjective suffix)","meaning":"relating to","meaningCN":"与……相关的","example":"The suffix marks relation.","exampleCN":"这个后缀标记关系。"},{"word":"exchange","structure":"ex- + cambiare","meaning":"a giving and receiving","meaningCN":"交换","example":"Exchange is the doublet of change.","exampleCN":"exchange 是 change 的同源双式词。"}],"derivatives":[{"word":"changing","structure":"change + -ing (participle)","meaning":"in the process of altering","meaningCN":"正在变化的"},{"word":"changed","structure":"change + -ed (participle)","meaning":"already different","meaningCN":"已改变的"},{"word":"socially","structure":"social + -ly (adverb)","meaning":"in social terms","meaningCN":"在社会层面"}],"latinEntries":[{"word":"socius","structure":"socius, socii (m., second declension)","meaning":"companion, ally","meaningCN":"同伴；盟友"},{"word":"cambiare","structure":"cambiare (Late Latin verb)","meaning":"to exchange, barter","meaningCN":"交换；以物易物"},{"word":"societas","structure":"societas, societatis (f., third declension)","meaning":"fellowship; an association","meaningCN":"伙伴关系；社团"}]}}]);
